def volcengine_access_key_env():
    return "VOLCENGINE_ACCESS_KEY_ID"

def volcengine_secret_key_env():
    return "VOLCENGINE_SECRET_ACCESS_KEY"

def read_api_env_value(key: str) -> str:
    key = str(key or "").strip()
    if not key or not os.path.exists(API_ENV_FILE):
        return ""
    try:
        with open(API_ENV_FILE, "r", encoding="utf-8-sig") as f:
            for raw_line in f.read().splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                env_key, value = line.split("=", 1)
                if env_key.strip() == key:
                    return value.strip().strip('"').strip("'")
    except Exception:
        return ""
    return ""

def provider_env_key_value(provider_id: str) -> str:
    provider_id = str(provider_id or "").strip().lower()
    env_key = provider_key_env(provider_id)
    key = os.getenv(env_key, "") or read_api_env_value(env_key)
    if key:
        return key
    if provider_id == "ai-money":
        # 兼容旧版已保存的 Key；新保存统一使用 LAOHU 命名。
        return os.getenv("API_PROVIDER_AI_MONEY_KEY", "") or read_api_env_value("API_PROVIDER_AI_MONEY_KEY")
    if provider_id == "modelscope":
        return MODELSCOPE_API_KEY or ""
    return ""

def runninghub_region_key_value(region="global", use_wallet=False) -> str:
    region = runninghub_normalize_region(region)
    env_key = runninghub_key_env(region, use_wallet=use_wallet)
    value = os.getenv(env_key, "") or read_api_env_value(env_key)
    if value:
        return value
    if region == "global":
        legacy_env = "RUNNINGHUB_WALLET_API_KEY" if use_wallet else "RUNNINGHUB_API_KEY"
        legacy_value = os.getenv(legacy_env, "") or read_api_env_value(legacy_env)
        if not legacy_value:
            return ""
        # 旧版保存逻辑曾把当前国内站 Key 同时写入通用变量。国际站只在该
        # legacy 值不等于国内专用 Key 时才兼容读取，避免把国内凭证带到国际站。
        cn_env = runninghub_key_env("cn", use_wallet=use_wallet)
        cn_value = os.getenv(cn_env, "") or read_api_env_value(cn_env)
        if cn_value and hmac.compare_digest(str(legacy_value), str(cn_value)):
            return ""
        return legacy_value
    return ""

def runninghub_wallet_key_value(region="global") -> str:
    return runninghub_region_key_value(region, use_wallet=True)

def volcengine_access_key_value() -> str:
    env_key = volcengine_access_key_env()
    return os.getenv(env_key, "") or read_api_env_value(env_key)

def volcengine_secret_key_value() -> str:
    env_key = volcengine_secret_key_env()
