def codex_env_value(key):
    return os.getenv(key, "") or read_api_env_value(key)

def codex_cli_env():
    env = os.environ.copy()
    # GPT CLI 只跟随当前 Codex 环境。项目不持有第二份认证，
    # 也不允许历史项目变量覆盖当前 CODEX_HOME。
    env.pop("CODEX_CLI_HOME", None)
    return env

def codex_models_cache_path():
    """Return the model catalog maintained by the current Codex environment."""
    codex_home = str(codex_cli_env().get("CODEX_HOME") or "").strip()
    if codex_home:
        return Path(os.path.expanduser(codex_home)) / "models_cache.json"
    return Path.home() / ".codex" / "models_cache.json"

def codex_cached_model_catalog():
    """Read public model choices from Codex's cache without touching auth data."""
    cache_path = codex_models_cache_path()
    try:
        payload = json.loads(cache_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return None
    if not isinstance(payload, dict) or not isinstance(payload.get("models"), list):
        return None

    models = []
    model_names = {"auto": "Codex 当前配置"}
    seen = {"auto"}
    for item in payload["models"]:
        if not isinstance(item, dict):
            continue
        if str(item.get("visibility") or "list").strip().lower() != "list":
            continue
        slug = str(item.get("slug") or "").strip()
        if not slug or slug in seen:
            continue
        seen.add(slug)
        models.append(slug)
        display_name = str(item.get("display_name") or "").strip()
        if display_name:
            model_names[slug] = display_name

    if not models:
        return None
    return {
        "chat_models": ["auto", *models],
        "model_names": model_names,
        "fetched_at": str(payload.get("fetched_at") or "").strip(),
        "client_version": str(payload.get("client_version") or "").strip(),
    }

def codex_cli_candidates():
    configured = str(codex_env_value("CODEX_BIN") or "").strip()
    candidates = []
    if configured:
        configured_path = os.path.expanduser(configured)
        if os.path.isabs(configured_path) or os.sep in configured_path or (os.altsep and os.altsep in configured_path):
            candidates.append(configured_path)
        else:
            candidates.append(configured)
    candidates.extend(["codex", "codex.exe", "codex.cmd"])
    home = os.path.expanduser("~")
    if sys.platform == "darwin":
        candidates.extend([
            "/Applications/ChatGPT.app/Contents/Resources/codex",
            os.path.join(home, "Applications", "ChatGPT.app", "Contents", "Resources", "codex"),
        ])
    elif os.name == "nt":
        app_data = os.getenv("APPDATA", "")
        local_app_data = os.getenv("LOCALAPPDATA", "")
        candidates.extend([
            os.path.join(app_data, "npm", "codex.cmd") if app_data else "",
            os.path.join(local_app_data, "Programs", "codex", "codex.exe") if local_app_data else "",
            os.path.join(local_app_data, "npm", "codex.cmd") if local_app_data else "",
        ])
    else:
        candidates.extend([
            os.path.join(home, ".local", "bin", "codex"),
            "/usr/local/bin/codex",
            "/usr/bin/codex",
        ])
    result = []
    seen = set()
    for candidate in candidates:
        candidate = str(candidate or "").strip()
        if candidate and candidate not in seen:
            result.append(candidate)
            seen.add(candidate)
    return result

def codex_cli_executable():
    for candidate in codex_cli_candidates():
        resolved = shutil.which(candidate)
        if resolved:
            return resolved
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    return ""

def codex_timeout(default=CODEX_DEFAULT_TIMEOUT):
    try:
        return max(30, min(3600, int(os.getenv("CODEX_CLI_TIMEOUT", str(default)) or default)))
    except Exception:
        return default

def codex_model_for_exec(model="", fallback=""):
    value = str(model or fallback or "").strip()
    low = value.lower()
    if not value or low == "auto" or low.startswith("$imagegen") or low.startswith("gpt-image"):
        return ""
    return value

def codex_decode_output(stdout, stderr):
    out_text = (stdout or b"").decode("utf-8", errors="replace").strip()
    err_text = (stderr or b"").decode("utf-8", errors="replace").strip()
    return out_text, err_text

async def run_codex_cli(prompt, model="", image_paths=None, timeout=None, output_last_message=True):
    exe = codex_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 OpenAI Codex CLI。请先在 API 设置的 GPT CLI 卡片中安装或更新，并在 Codex 桌面端或官方 CLI 中完成登录。")
    image_paths = [str(path) for path in (image_paths or []) if path and os.path.isfile(str(path))]
    last_path = ""
    args = [
        exe,
        "exec",
        "--cd",
        BASE_DIR,
        "--sandbox",
        "workspace-write",
        "--skip-git-repo-check",
    ]
    exec_model = codex_model_for_exec(model)
    if exec_model:
        args.extend(["--model", exec_model])
    for path in image_paths:
        args.extend(["--image", path])
    if output_last_message:
        fd, last_path = tempfile.mkstemp(prefix="codex_last_", suffix=".txt", dir=OUTPUT_OUTPUT_DIR)
        os.close(fd)
        args.extend(["--output-last-message", last_path])
    args.append("-")
    prompt_bytes = str(prompt or "").encode("utf-8")
    try:
        proc = await asyncio.create_subprocess_exec(
            *args,
            cwd=BASE_DIR,
            env=codex_cli_env(),
            stdin=asyncio.subprocess.PIPE,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(input=prompt_bytes), timeout=timeout or codex_timeout())
    except asyncio.TimeoutError as exc:
        raise HTTPException(status_code=504, detail="OpenAI Codex CLI 执行超时。可设置 CODEX_CLI_TIMEOUT 增大等待时间。") from exc
    except FileNotFoundError as exc:
        raise HTTPException(status_code=400, detail=f"未找到 OpenAI Codex CLI：{exe}") from exc
    out_text, err_text = codex_decode_output(stdout, stderr)
    last_text = ""
    if last_path and os.path.exists(last_path):
        try:
            with open(last_path, "r", encoding="utf-8-sig") as f:
                last_text = f.read().strip()
        except Exception:
            last_text = ""
        try:
            os.remove(last_path)
        except Exception:
            pass
    if proc.returncode != 0:
        message = err_text or out_text or last_text or f"exit={proc.returncode}"
        raise HTTPException(status_code=502, detail=f"OpenAI Codex CLI 调用失败：{message[:1200]}")
    return {"text": last_text or out_text, "_stdout": out_text, "_stderr": err_text}

def codex_output_image_files(since_time=0):
    exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    root = os.path.abspath(OUTPUT_OUTPUT_DIR)
    files = []
    try:
        for name in os.listdir(root):
            path = os.path.join(root, name)
            if not os.path.isfile(path):
                continue
            ext = os.path.splitext(name)[1].lower()
            if ext not in exts:
                continue
            mtime = os.path.getmtime(path)
            if mtime + 1 < float(since_time or 0):
                continue
            files.append((mtime, path))
    except Exception:
        return []
    return [path for _mtime, path in sorted(files, reverse=True)]

def codex_output_url_from_path(path):
    path = os.path.abspath(str(path or ""))
    root = os.path.abspath(OUTPUT_OUTPUT_DIR)
    try:
        if os.path.commonpath([root, path]) == root:
            return output_url_for(os.path.basename(path), "output")
    except Exception:
        return ""
    return ""

def codex_postprocess_image_to_requested_size(path="", requested_size="", provider=""):
    provider_text = str(provider or "").strip().lower()
    if provider_text != "gemini-cli":
        return ""
    width, height = parse_size_pair(requested_size)
    if not width or not height or not path or not os.path.isfile(path):
        return ""
    try:
        with Image.open(path) as img:
            img.load()
            if img.width == width and img.height == height:
                return ""
            resample = getattr(Image, "Resampling", Image).LANCZOS
            oriented = ImageOps.exif_transpose(img)
            converted = oriented.convert("RGBA") if oriented.mode in ("RGBA", "LA", "P") else oriented.convert("RGB")
            resized = ImageOps.fit(converted, (width, height), method=resample, centering=(0.5, 0.5))
            base, _ext = os.path.splitext(path)
            upscaled_path = f"{base}_upscaled_{width}x{height}.png"
            resized.save(upscaled_path, format="PNG")
            return upscaled_path
    except Exception as exc:
        print(f"Gemini CLI 图片尺寸后处理失败：{exc}")
        return ""

async def codex_prepare_local_media(ref_url):
    text = str(ref_url or "").strip()
    if not text:
        return "", []
    if is_local_media_reference(text):
        path = local_media_reference_path(text)
        if path:
            return path, []
        raise HTTPException(status_code=404, detail=f"OpenAI CLI 参考素材不存在：{text}")
    temp_paths = []
    suffix = ".png"
    if text.startswith("data:"):
        if ";base64," not in text:
            raise HTTPException(status_code=400, detail="OpenAI CLI 参考素材 data URL 缺少 base64 数据")
        header, encoded = text.split(";base64,", 1)
        mime = header.split(":", 1)[1].split(";", 1)[0] if ":" in header else ""
        suffix = mimetypes.guess_extension(mime) or suffix
        fd, path = tempfile.mkstemp(prefix="codex_ref_", suffix=suffix)
        with os.fdopen(fd, "wb") as f:
            f.write(base64.b64decode(encoded))
        temp_paths.append(path)
        return path, temp_paths
    if text.startswith(("http://", "https://")):
        async with httpx.AsyncClient(timeout=httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0), follow_redirects=True) as client:
            response = await client.get(text)
            response.raise_for_status()
            clean_path = urllib.parse.urlparse(text).path
            suffix = os.path.splitext(clean_path)[1] or mimetypes.guess_extension(response.headers.get("content-type", "")) or suffix
            fd, path = tempfile.mkstemp(prefix="codex_ref_", suffix=suffix)
            with os.fdopen(fd, "wb") as f:
                f.write(response.content)
            temp_paths.append(path)
            return path, temp_paths
    raise HTTPException(status_code=400, detail=f"OpenAI CLI 无法读取参考素材：{text[:120]}")

async def codex_reference_paths(reference_images=None):
    paths = []
    temp_paths = []
    try:
        for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
            url = ref.get("url") if isinstance(ref, dict) else getattr(ref, "url", "")
            if not url:
                continue
            path, created = await codex_prepare_local_media(url)
            if path:
                paths.append(path)
            temp_paths.extend(created)
        return paths, temp_paths
    except Exception:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass
        raise

def codex_models_payload(raw=None):
    catalog = codex_cached_model_catalog()
    if catalog:
        chat_models = catalog["chat_models"]
        model_names = catalog["model_names"]
        source = "codex_models_cache"
        fetched_at = catalog["fetched_at"]
        client_version = catalog["client_version"]
        message = "模型列表来自当前 Codex 的本机模型缓存；具体模型能否使用，仍以该节点实际运行结果为准。"
    else:
        chat_models = list(CODEX_DEFAULT_CHAT_MODELS)
        model_names = {"auto": "Codex 当前配置", "gpt-5.5": "GPT 5.5"}
        source = "fallback_defaults"
        fetched_at = ""
        client_version = ""
        message = "暂未读取到当前 Codex 的模型缓存，已显示保底选项；也可以手动添加模型 ID。"
    all_models = [*CODEX_DEFAULT_IMAGE_MODELS, *chat_models]
    return {
        "ok": True,
        "protocol": "codex",
        "status": 200,
        "message": message,
        "model_count": len(all_models),
        "total": len(all_models),
        "image_models": CODEX_DEFAULT_IMAGE_MODELS,
        "chat_models": chat_models,
        "video_models": [],
        "audio_models": [],
        "all": all_models,
        "model_names": model_names,
        "source": source,
        "fetched_at": fetched_at,
        "client_version": client_version,
        "raw": raw or {},
    }

async def generate_codex_provider_image(prompt, size, model, reference_images=None, provider=None):
    raise HTTPException(status_code=400, detail="OpenAI Codex CLI 当前只支持文本生成，不支持图片生成。")

def codex_chat_prompt(payload, history_messages=None):
    parts = []
    system_prompt = str(getattr(payload, "system_prompt", "") or "").strip()
    if system_prompt:
        parts.append(f"系统要求：\n{system_prompt}")
    for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
        role = str(item.get("role") or "").strip()
        content = item.get("content")
        if role in {"user", "assistant"} and content:
            label = "用户" if role == "user" else "助手"
            parts.append(f"{label}：\n{content}")
    message = str(getattr(payload, "message", "") or "").strip()
    parts.append(f"用户：\n{message}")
    parts.append("请直接回答用户，输出纯文本，不要修改项目文件。")
    return "\n\n".join(part for part in parts if part).strip()

async def codex_chat_text(payload, history_messages=None):
    image_paths = []
    temp_paths = []
    try:
        image_values = []
        if hasattr(payload, "images"):
            image_values.extend([{"url": item} for item in (getattr(payload, "images", None) or []) if item])
        if hasattr(payload, "reference_images"):
            image_values.extend([ref.dict() for ref in (getattr(payload, "reference_images", None) or []) if getattr(ref, "url", "")])
        image_paths, temp_paths = await codex_reference_paths(image_values)
        raw = await run_codex_cli(
            codex_chat_prompt(payload, history_messages),
            model=getattr(payload, "model", "") or CODEX_DEFAULT_CHAT_MODELS[0],
            image_paths=image_paths,
            timeout=codex_timeout(),
            output_last_message=True,
        )
        text = str(raw.get("text") or "").strip()
        return text or "Codex CLI 返回了空回复。", raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def gemini_cli_env_value(key):
    return os.getenv(key, "") or read_api_env_value(key)

def antigravity_cli_winget_candidates():
    patterns = [
        os.path.join(os.path.expanduser("~"), "AppData", "Local", "Microsoft", "WinGet", "Packages", "Google.AntigravityCLI_*", "agy.exe"),
        os.path.join(os.getenv("LOCALAPPDATA", ""), "Microsoft", "WinGet", "Packages", "Google.AntigravityCLI_*", "agy.exe"),
    ]
    candidates = []
    for pattern in patterns:
        if not pattern:
            continue
        candidates.extend(glob.glob(pattern))
    return sorted(dict.fromkeys(path for path in candidates if os.path.exists(path)), reverse=True)

def gemini_cli_executable():
    for key in ("ANTIGRAVITY_BIN", "AGY_BIN", "GEMINI_BIN"):
        configured = str(gemini_cli_env_value(key) or "").strip().strip('"')
        if configured:
            return configured
    for name in ("agy", "agy.exe"):
        found = shutil.which(name)
        if found:
            return found
    for candidate in antigravity_cli_winget_candidates():
        return candidate
    return shutil.which("gemini") or shutil.which("gemini.exe") or shutil.which("gemini.cmd") or ""

def is_antigravity_cli(exe):
    text = str(exe or "").lower()
    return os.path.basename(text).startswith("agy") or "antigravity" in text

def gemini_cli_display_name(exe=None):
    return "Antigravity CLI" if is_antigravity_cli(exe or gemini_cli_executable()) else "Gemini CLI"

def gemini_cli_timeout(default=GEMINI_CLI_DEFAULT_TIMEOUT):
    try:
        return max(30, min(3600, int(os.getenv("GEMINI_CLI_TIMEOUT", str(default)) or default)))
    except Exception:
        return default

def gemini_cli_image_timeout():
    raw = os.getenv("ANTIGRAVITY_IMAGE_TIMEOUT") or os.getenv("GEMINI_CLI_IMAGE_TIMEOUT") or "300"
    try:
        return max(60, min(1800, int(raw)))
    except Exception:
        return 300

def gemini_cli_model(model="", fallback=""):
    value = str(model or fallback or "").strip()
    return value or "auto"

def gemini_cli_text_from_raw(raw, fallback_text=""):
    if isinstance(raw, str):
        return raw.strip()
    if isinstance(raw, dict):
        for key in ("response", "text", "content", "message", "output"):
            value = raw.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        candidates = []
        for value in raw.values():
            if isinstance(value, str) and value.strip():
                candidates.append(value.strip())
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        text = gemini_cli_text_from_raw(item)
                        if text:
                            candidates.append(text)
                    elif isinstance(item, str) and item.strip():
                        candidates.append(item.strip())
        if candidates:
            return "\n".join(candidates).strip()
    if isinstance(raw, list):
        parts = [gemini_cli_text_from_raw(item) for item in raw]
        return "\n".join(part for part in parts if part).strip()
    return str(fallback_text or "").strip()

def gemini_cli_parse_stdout(out_text):
    text = str(out_text or "").strip()
    if not text:
        return {}, ""
    try:
        raw = json.loads(text)
        return raw, gemini_cli_text_from_raw(raw, text)
    except Exception:
        pass
    parsed = jimeng_extract_json(text)
    if isinstance(parsed, (dict, list)) and parsed != {"text": text}:
        return parsed, gemini_cli_text_from_raw(parsed, text)
    return {"text": text}, text

async def run_gemini_cli(prompt, model="", timeout=None, allow_tools=False):
    exe = gemini_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 Antigravity CLI。请先安装 Google Antigravity CLI，并完成 agy 登录。")
    timeout_seconds = timeout or gemini_cli_timeout()
    if is_antigravity_cli(exe):
        args = [exe, "--print-timeout", f"{int(timeout_seconds)}s"]
        selected = gemini_cli_model(model)
        if selected and selected != "auto":
            args.extend(["--model", selected])
        if allow_tools:
            args.append("--dangerously-skip-permissions")
        args.extend(["-p", str(prompt or "")])
    else:
        args = [
            exe,
            "--model",
            gemini_cli_model(model),
            "--output-format",
            "json",
            "--skip-trust",
        ]
        if allow_tools:
            args.extend(["--approval-mode", "yolo"])
        args.extend(["--prompt", str(prompt or "")])
    proc = None
    try:
        proc = await asyncio.create_subprocess_exec(
            *args,
            cwd=BASE_DIR,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=timeout_seconds)
    except asyncio.TimeoutError as exc:
        if proc and proc.returncode is None:
            try:
                proc.kill()
                await proc.wait()
            except Exception:
                pass
        raise HTTPException(status_code=504, detail=f"{gemini_cli_display_name(exe)} 执行超时。可设置 GEMINI_CLI_TIMEOUT 增大等待时间。") from exc
    except FileNotFoundError as exc:
        raise HTTPException(status_code=400, detail=f"未找到 {gemini_cli_display_name(exe)}：{exe}") from exc
    out_text, err_text = codex_decode_output(stdout, stderr)
    raw, text = gemini_cli_parse_stdout(out_text)
    if proc.returncode != 0:
        message = err_text or out_text or f"exit={proc.returncode}"
        raise HTTPException(status_code=502, detail=f"{gemini_cli_display_name(exe)} 调用失败：{message[:1200]}")
    return {"text": text or out_text, "raw": raw, "_stdout": out_text, "_stderr": err_text}

def gemini_cli_models_payload(raw=None):
    all_models = [*GEMINI_CLI_DEFAULT_IMAGE_MODELS, *GEMINI_CLI_DEFAULT_CHAT_MODELS]
    all_models = model_list_from_values(all_models)
    return {
        "ok": True,
        "protocol": "gemini-cli",
        "status": 200,
        "message": "Antigravity CLI 可用，模型列表使用 auto 默认模型。",
        "model_count": len(all_models),
        "total": len(all_models),
        "image_models": GEMINI_CLI_DEFAULT_IMAGE_MODELS,
        "chat_models": GEMINI_CLI_DEFAULT_CHAT_MODELS,
        "video_models": [],
        "audio_models": [],
        "all": all_models,
        "raw": raw or {},
    }

def gemini_cli_reference_note(reference_images=None):
    refs = []
    temp_paths = []
    for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
        url = ref.get("url") if isinstance(ref, dict) else getattr(ref, "url", "")
        if not url:
            continue
        refs.append(url)
    return refs, temp_paths

async def gemini_cli_reference_paths(reference_images=None):
    return await codex_reference_paths(reference_images)

def gemini_cli_image_size_instruction(size="", model=""):
    size_text = str(size or "").strip()
    model_text = str(model or "").strip()
    match = re.match(r"^\s*(\d{2,5})\s*[xX*]\s*(\d{2,5})\s*$", size_text)
    if match:
        width, height = int(match.group(1)), int(match.group(2))
        if width > 0 and height > 0:
            orientation = "正方形" if width == height else ("横版" if width > height else "竖版")
            return (
                f"目标输出分辨率：{width}x{height} 像素（宽 x 高），画面方向：{orientation}。"
                f"最终保存到输出目录的图片文件实际像素必须是 {width}x{height}。"
                "如果生成器先得到较小图片，请在保存前放大或导出到目标尺寸，不要返回 1024px 小图。"
            )
    combined = f"{size_text} {model_text}".lower()
    if "4k" in combined:
        return "目标输出为 4K 高分辨率图片；最终保存文件需要达到当前画幅对应的 4K 像素尺寸，不要默认输出 1024px 小图。"
    if "2k" in combined:
        return "目标输出为 2K 高分辨率图片；最终保存文件需要达到当前画幅对应的 2K 像素尺寸，不要默认输出 1024px 小图。"
    return f"尺寸/比例参考：{size_text or 'auto'}。如果可以指定分辨率，请优先输出高分辨率图片。"

async def generate_gemini_cli_provider_image(prompt, size, model, reference_images=None, provider=None):
    ref_paths, temp_paths = await gemini_cli_reference_paths(reference_images)
    since = time.time()
    try:
        ref_text = ""
        if ref_paths:
            ref_text = "\n参考图片本地路径：\n" + "\n".join(ref_paths)
        size_context = f"{model or ''} {prompt or ''}"
        image_prompt = (
            f"你正在为 Infinite Canvas 生成图片。\n"
            f"任务：{prompt}\n\n"
            f"{gemini_cli_image_size_instruction(size, size_context)}\n"
            f"{ref_text}\n\n"
            f"如果当前 Antigravity CLI/模型支持图片生成或图片编辑，请把最终图片保存到这个本地目录：{OUTPUT_OUTPUT_DIR}\n"
            "文件格式优先 png 或 jpg。只输出最终文件路径和一句简短说明；不要修改项目代码，不要创建额外文档。\n"
            "如果你无法真正创建图片文件，请在 60 秒内直接回复“无法生成图片文件”，不要只写计划，也不要持续尝试。"
        )
        raw = await run_gemini_cli(
            image_prompt,
            model=model or GEMINI_CLI_DEFAULT_IMAGE_MODELS[0],
            timeout=gemini_cli_image_timeout() if is_antigravity_cli(gemini_cli_executable()) else gemini_cli_timeout(),
            allow_tools=True,
        )
        files = codex_output_image_files(since)
        urls = []
        for path in files:
            processed_path = codex_postprocess_image_to_requested_size(path, size, "gemini-cli")
            url = codex_output_url_from_path(processed_path or path)
            if url and url not in urls:
                urls.append(url)
        if not urls:
            text = f"{raw.get('text') or raw.get('_stdout') or ''}\n{raw.get('_stderr') or ''}"
            pattern = r"([A-Za-z]:\\[^\r\n\"'<>]+\.(?:png|jpe?g|webp|gif)|/[^\r\n\"'<>]+\.(?:png|jpe?g|webp|gif))"
            for match in re.findall(pattern, text, flags=re.I):
                match_path = match.strip()
                processed_path = codex_postprocess_image_to_requested_size(match_path, size, "gemini-cli")
                url = codex_output_url_from_path(processed_path or match_path)
                if url and url not in urls:
                    urls.append(url)
        if not urls:
            status_text = (raw.get("text") or raw.get("_stdout") or raw.get("_stderr") or "")[:1200]
            raise HTTPException(status_code=502, detail=f"{gemini_cli_display_name()} 已返回，但没有在输出目录发现图片：{status_text}")
        return {"type": "url", "value": urls[0]}, {"images": urls, "text": raw.get("text"), "provider": "gemini-cli", "raw": raw.get("raw")}
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def gemini_cli_chat_prompt(payload, history_messages=None):
    parts = []
    system_prompt = str(getattr(payload, "system_prompt", "") or "").strip()
    if system_prompt:
        parts.append(f"系统要求：\n{system_prompt}")
    for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
        role = str(item.get("role") or "").strip()
        content = item.get("content")
        if role in {"user", "assistant"} and content:
            label = "用户" if role == "user" else "助手"
            parts.append(f"{label}：\n{content}")
    message = str(getattr(payload, "message", "") or "").strip()
    parts.append(f"用户：\n{message}")
    image_values = []
    if hasattr(payload, "images"):
        image_values.extend([{"url": item} for item in (getattr(payload, "images", None) or []) if item])
    if hasattr(payload, "reference_images"):
        image_values.extend([ref.dict() for ref in (getattr(payload, "reference_images", None) or []) if getattr(ref, "url", "")])
    refs = []
    temp_paths = []
    return "\n\n".join(part for part in parts if part).strip(), image_values

async def gemini_cli_chat_text(payload, history_messages=None):
    temp_paths = []
    try:
        prompt, image_values = gemini_cli_chat_prompt(payload, history_messages)
        image_paths, temp_paths = await gemini_cli_reference_paths(image_values)
        if image_paths:
            prompt = f"{prompt}\n\n可参考的本地图片路径：\n" + "\n".join(image_paths)
        prompt = f"{prompt}\n\n请直接回答用户，输出纯文本，不要修改项目文件。"
        raw = await run_gemini_cli(
            prompt,
            model=getattr(payload, "model", "") or GEMINI_CLI_DEFAULT_CHAT_MODELS[0],
            timeout=gemini_cli_timeout(),
            allow_tools=False,
        )
        text = str(raw.get("text") or "").strip()
        return text or f"{gemini_cli_display_name()} 返回了空回复。", raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def is_yuli_provider(provider):
    # 玉玉API（yuli.host）的视频接口走自有格式（/v1/video/create + /v1/video/query），
    # 与通用 OpenAI /v1/videos/generations 不同，需单独识别。
    base_url = str((provider or {}).get("base_url") or "").lower()
    return "yuli.host" in base_url

def is_lingjing_provider(provider):
    base_url = str((provider or {}).get("base_url") or "").lower()
    provider_id = str((provider or {}).get("id") or "").strip().lower()
    return provider_id == "lingjing" or "apistudio.vip" in base_url

def is_agnes_provider(provider, model=""):
    base_url = str((provider or {}).get("base_url") or "").lower()
    model_id = str(model or "").strip().lower()
    return "apihub.agnes-ai.com" in base_url or model_id.startswith("agnes-video-")

def jimeng_env_value(key):
    return os.getenv(key, "") or read_api_env_value(key)

def jimeng_use_wsl():
    value = str(jimeng_env_value("JIMENG_USE_WSL") or "").strip().lower()
    return value in {"1", "true", "yes", "on", "wsl"}

def jimeng_cli_executable():
    if jimeng_use_wsl():
        return shutil.which("wsl.exe") or shutil.which("wsl") or "wsl.exe"
    configured = str(
        jimeng_env_value("JIMENG_BIN")
        or jimeng_env_value("DREAMINA_BIN")
        or ""
    ).strip()
    if configured:
        return configured
    return shutil.which("dreamina") or shutil.which("dreamina.exe") or shutil.which("dreamina.cmd") or ""

def decode_utf16_auto(raw: bytes) -> str:
    # WSL/Windows interop emits UTF-16 for null-heavy diagnostics, but the
    # endianness varies by source (console vs proxy vs subprocess), so a
    # hard-coded "utf-16le" silently byte-swaps UTF-16BE text into garbage
    # (e.g. "localhost" -> 氀漀挀愀氀栀漀猀琀). Decode both ways and keep
    # whichever produces more plain ASCII, since diagnostics are ASCII-heavy.
    try:
        le = raw.decode("utf-16le", errors="ignore")
    except Exception:
        le = ""
    try:
        be = raw.decode("utf-16be", errors="ignore")
    except Exception:
        be = ""
    def ascii_score(text):
        return sum(1 for ch in text if 0x20 <= ord(ch) <= 0x7e)
    return le if ascii_score(le) >= ascii_score(be) else be

def decode_wsl_output(data: bytes) -> str:
    data = data or b""
    if not data:
        return ""

    # WSL can mix UTF-16 diagnostics with UTF-8 command output in the same
    # stream. Decode per line so a WSL proxy warning does not corrupt CLI errors.
    if b"\x00" in data[:400]:
        lines = []
        for raw_line in data.splitlines():
            if not raw_line:
                lines.append("")
                continue
            sample = raw_line[:200]
            nul_ratio = sample.count(0) / max(1, len(sample))
            if nul_ratio > 0.2:
                try:
                    lines.append(decode_utf16_auto(raw_line))
                    continue
                except Exception:
                    pass
            lines.append(raw_line.decode("utf-8-sig", errors="ignore"))
        return "\n".join(lines)
    if b"\x00" in data[:200]:
        try:
            return decode_utf16_auto(data)
        except Exception:
            pass
    return data.decode("utf-8-sig", errors="ignore")

def jimeng_wsl_base_args(exe="wsl.exe"):
    configured = str(jimeng_env_value("JIMENG_WSL_DISTRO") or "").strip()
    names = []
    try:
        proc = subprocess.run(
            [exe, "-l", "-q"],
            cwd=BASE_DIR,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            timeout=5,
            check=False,
        )
        names = [
            line.replace("\x00", "").strip().lstrip("*").strip()
            for line in decode_wsl_output(proc.stdout).splitlines()
            if line.replace("\x00", "").strip()
        ]
    except Exception:
        names = []
    if configured and (not names or configured in names):
        return ["-d", configured]
    if configured and names:
        print(f"JIMENG_WSL_DISTRO={configured} 不存在，已回退自动选择。可用发行版：{names}")
    try:
        ubuntu = next((name for name in names if re.match(r"^Ubuntu($|-)", name)), "")
        if ubuntu:
            return ["-d", ubuntu]
    except Exception:
        pass
    return []

def jimeng_clean_wsl_stderr(text):
    lines = []
    skip_next_warning_context = False
    for line in str(text or "").splitlines():
        clean = line.replace("\x00", "").strip()
        low = clean.lower()
        is_proxy_warning = "localhost" in low and "wsl" in low and ("nat" in low or "proxy" in low or "代理" in clean)
        # Windows/WSL can mojibake the proxy warning. Keep explicit failures, but
        # do not turn a completed Dreamina task into a failed request for this noise.
        is_proxy_mojibake = "localhost" in low and len(clean) < 120 and not any(
            token in low for token in ("error", "failed", "traceback", "exception", "refused", "denied")
        )
        is_python_warning = "requestsdependencywarning" in low or (skip_next_warning_context and clean.startswith("warnings.warn("))
        skip_next_warning_context = "requestsdependencywarning" in low
        if clean and not is_proxy_warning and not is_proxy_mojibake and not is_python_warning:
            lines.append(clean)
    return "\n".join(lines).strip()

def jimeng_has_result_payload(raw):
    """Recognize CLI output that is usable even when its process exit code is non-zero."""
    found = False
    def visit(value):
        nonlocal found
        if found:
            return
        if isinstance(value, dict):
            keys = {str(key).lower() for key in value}
            if keys & {"submit_id", "submitid", "task_id", "taskid", "gen_status", "result_json", "images", "videos", "data"}:
                found = True
                return
            for item in value.values():
                if isinstance(item, (dict, list)):
                    visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(raw)
    return found

def windows_path_to_wsl(path):
    text = str(path or "").replace("\\", "/")
    match = re.match(r"^([A-Za-z]):/(.*)$", text)
    if match:
        return f"/mnt/{match.group(1).lower()}/{match.group(2)}"
    return text

def wsl_path_to_windows(path):
    text = str(path or "").strip()
    match = re.match(r"^/mnt/([A-Za-z])/(.*)$", text)
    if match:
        tail = match.group(2).replace("/", "\\")
        return f"{match.group(1).upper()}:\\{tail}"
    return text

def jimeng_cli_path_arg(path):
    return windows_path_to_wsl(path) if jimeng_use_wsl() else path

def jimeng_poll_seconds(default=JIMENG_DEFAULT_POLL_SECONDS):
    try:
        return max(1, min(3600, int(os.getenv("JIMENG_POLL_SECONDS", str(default)) or default)))
    except Exception:
        return default

def jimeng_video_submit_poll_seconds():
    """Keep the HTTP submission short; pending jobs continue through query_result polling."""
    try:
        return max(0, min(30, int(os.getenv("JIMENG_VIDEO_SUBMIT_POLL", "12") or 12)))
    except Exception:
        return 12

def jimeng_extract_json(text):
    text = str(text or "").strip()
    if not text:
        return {}
    decoder = json.JSONDecoder()
    parsed = []
    for i, ch in enumerate(text):
        if ch not in "[{":
            continue
        try:
            obj, _end = decoder.raw_decode(text[i:])
            if not text[:i].strip():
                return obj
            parsed.append((i, obj))
        except Exception:
            continue
    def score(item):
        _idx, obj = item
        if not isinstance(obj, dict):
            return 1
        keys = {str(key).lower() for key in obj.keys()}
        weight = 0
        for key in ("submit_id", "gen_status", "result_json", "images", "videos", "data", "total_credit"):
            if key in keys:
                weight += 10
        return weight
    return max(parsed, key=score)[1] if parsed else {"text": text}

async def run_jimeng_cli(args, timeout=120, raw_text=False):
    exe = jimeng_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 dreamina CLI。请先安装：curl -fsSL https://jimeng.jianying.com/cli | bash，并完成 dreamina login。")
    clean_args = [str(arg) for arg in args if str(arg) != ""]
    command = jimeng_command(clean_args, exe)
    try:
        proc = await asyncio.create_subprocess_exec(
            *command,
            cwd=BASE_DIR,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError as exc:
        raise HTTPException(status_code=504, detail=f"即梦 CLI 执行超时：{' '.join(command[:3])}") from exc
    except FileNotFoundError as exc:
        raise HTTPException(status_code=400, detail=f"未找到即梦 CLI：{exe}") from exc
    out_text, clean_err_text = jimeng_decode_cli_output(stdout, stderr)
    if proc.returncode != 0:
        # Some Dreamina CLI versions return a non-zero code after already emitting
        # a usable task payload. Preserve that task so the canvas can continue polling.
        if out_text:
            raw = jimeng_extract_json(out_text)
            if isinstance(raw, dict) and jimeng_has_result_payload(raw):
                raw.setdefault("_stdout", out_text)
                if clean_err_text:
                    raw.setdefault("_stderr", clean_err_text)
                return raw
        message = clean_err_text or out_text or f"exit={proc.returncode}"
        raise HTTPException(status_code=502, detail=f"即梦 CLI 调用失败：{jimeng_friendly_error_detail(message[:1000])}")
    # 帮助等纯文本输出不应被 JSON 提取吞掉（如 [0.5, 8] 会被误判为结果）
    if raw_text:
        return {"_stdout": out_text, "_stderr": clean_err_text}
    raw = jimeng_extract_json(f"{out_text}\n{clean_err_text}".strip())
    if isinstance(raw, dict):
        raw.setdefault("_stdout", out_text)
        if clean_err_text:
            raw.setdefault("_stderr", clean_err_text)
    return raw

# 旧版 dreamina CLI 将 submit_id 用 16 位 hex，v1.4.2 起升级为 UUID，
# 与当前轮询逻辑不兼容。这里做尽力而为的版本探测，失败不阻断主流程。
JIMENG_MIN_CLI_VERSION = (1, 4, 2)

def jimeng_parse_version(text):
    match = re.search(r"(\d+)\.(\d+)\.(\d+)", str(text or ""))
    if not match:
        return None
    return tuple(int(part) for part in match.groups())

async def jimeng_cli_version():
    for flag in ("--version", "-V", "version"):
        try:
            raw = await run_jimeng_cli([flag], timeout=15)
        except HTTPException:
            continue
        text = raw if isinstance(raw, str) else (raw.get("_stdout") or raw.get("_stderr") or "" if isinstance(raw, dict) else "")
        version = jimeng_parse_version(text)
        if version:
            return version, str(text).strip()
    return None, ""

def jimeng_command(clean_args, exe=None):
    exe = exe or jimeng_cli_executable()
    if jimeng_use_wsl():
        shell_line = (
            ". ~/.profile >/dev/null 2>&1 || true; . ~/.bashrc >/dev/null 2>&1 || true; "
            "DREAMINA_BIN=$(command -v dreamina || find \"$HOME\" -maxdepth 4 -type f -name dreamina 2>/dev/null | head -n 1); "
            "if [ -z \"$DREAMINA_BIN\" ]; then echo 'dreamina CLI not found in WSL' >&2; exit 127; fi; "
            "\"$DREAMINA_BIN\" " + " ".join(shlex.quote(arg) for arg in clean_args)
        )
        return [exe, *jimeng_wsl_base_args(exe), "-e", "sh", "-lc", shell_line]
    return [exe, *clean_args]

def jimeng_decode_cli_output(stdout, stderr):
    out_text = (decode_wsl_output(stdout) if jimeng_use_wsl() else stdout.decode("utf-8", errors="replace")).strip()
    err_text = (decode_wsl_output(stderr) if jimeng_use_wsl() else stderr.decode("utf-8", errors="replace")).strip()
    clean_err_text = jimeng_clean_wsl_stderr(err_text) if jimeng_use_wsl() else err_text
    return out_text, clean_err_text

def jimeng_login_text():
    parts = []
    for key in ("stdout", "stderr"):
        value = str(JIMENG_LOGIN_SESSION.get(key) or "").strip()
        if value:
            parts.append(value)
    return "\n".join(parts).strip()

def jimeng_verification_url_is_allowed(value):
    try:
        parsed = urllib.parse.urlparse(str(value or "").strip())
    except ValueError:
        return False
    return parsed.scheme == "https" and (parsed.hostname or "").lower() == "jimeng.jianying.com"

def jimeng_login_field_from_text(text, field):
    match = re.search(rf"(?im)^\s*{re.escape(field)}\s*[:=]\s*([^\s]+)", str(text or ""))
    return match.group(1).strip() if match else ""

def jimeng_login_details_from_text(text):
    text = str(text or "")
    verification_url = jimeng_login_field_from_text(text, "verification_uri") or jimeng_login_field_from_text(text, "verification_url")
    if not jimeng_verification_url_is_allowed(verification_url):
        verification_url = ""
    return {
        "verification_url": verification_url,
        "qr_data": verification_url,
        "user_code": jimeng_login_field_from_text(text, "user_code"),
        "device_code": jimeng_login_field_from_text(text, "device_code"),
        "expires_at": jimeng_login_field_from_text(text, "expires_at"),
    }

def jimeng_login_check_args(text, poll_seconds=600):
    device_code = jimeng_login_details_from_text(text).get("device_code") or ""
    if not device_code:
        return []
    return ["login", "checklogin", f"--device_code={device_code}", f"--poll={max(1, int(poll_seconds))}"]

def jimeng_qr_png(value):
    qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=7, border=4)
    qr.add_data(str(value or ""))
    qr.make(fit=True)
    image = qr.make_image(fill_color="black", back_color="white")
    output = BytesIO()
    image.save(output, format="PNG")
    return output.getvalue()

def jimeng_browser_command(url, os_name=None, sys_platform=None):
    os_name = os_name or os.name
    sys_platform = sys_platform or sys.platform
    if os_name == "nt":
        return ["rundll32.exe", "url.dll,FileProtocolHandler", url]
    if sys_platform == "darwin":
        return ["open", url]
    return ["xdg-open", url]

def open_jimeng_verification_url(url):
    if not jimeng_verification_url_is_allowed(url):
        raise ValueError("即梦验证地址无效")
    command = jimeng_browser_command(url)
    kwargs = {
        "stdout": subprocess.DEVNULL,
        "stderr": subprocess.DEVNULL,
    }
    if os.name != "nt":
        kwargs["start_new_session"] = True
    subprocess.Popen(command, **kwargs)

def jimeng_login_payload(running=False, logged_in=False, raw=None, returncode=None):
    text = jimeng_login_text()
    details = jimeng_login_details_from_text(jimeng_login_text())
    if logged_in:
        state = "authenticated"
        message = "即梦 CLI 登录验证成功"
    elif running:
        state = "waiting"
        message = "等待即梦授权验证"
    elif re.search(r"登录已过期|认证已过期|授权已过期|expired", text, re.I):
        state = "expired"
        message = "本次认证已过期，请重新点击扫码登录"
    elif returncode not in (None, 0):
        state = "failed"
        message = "即梦登录验证失败，请重新登录"
    else:
        state = "idle"
        message = "即梦 CLI 尚未登录"
    expose_authorization = state == "waiting"
    return {
        "success": True,
        "running": bool(running),
        "logged_in": bool(logged_in),
        "state": state,
        "message": message,
        "verification_url": details["verification_url"] if expose_authorization else "",
        "has_qr": bool(details["qr_data"]) and expose_authorization,
        "user_code": details["user_code"] if expose_authorization else "",
        "expires_at": details["expires_at"] if expose_authorization else "",
        "started_at": JIMENG_LOGIN_SESSION.get("started_at") or 0,
        "raw": raw,
    }

async def jimeng_login_reader(proc):
    async def read_stream(stream, key):
        while True:
            chunk = await stream.readline()
            if not chunk:
                break
            text = (decode_wsl_output(chunk) if jimeng_use_wsl() else chunk.decode("utf-8", errors="replace"))
            if key == "stderr":
                text = jimeng_clean_wsl_stderr(text)
            if text:
                JIMENG_LOGIN_SESSION[key] = str(JIMENG_LOGIN_SESSION.get(key) or "") + text
    await asyncio.gather(read_stream(proc.stdout, "stdout"), read_stream(proc.stderr, "stderr"))

def jimeng_submit_id(raw):
    found = []
    def visit(value):
        if isinstance(value, dict):
            for key, item in value.items():
                if str(key).lower() in {"submit_id", "submitid", "task_id", "taskid"} and item:
                    found.append(str(item))
                else:
                    visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(raw)
    return found[0] if found else ""

def normalize_jimeng_queue_info(queue_info):
    normalized = dict(queue_info) if isinstance(queue_info, dict) else {}
    raw_position = next((normalized.get(key) for key in ("queue_idx", "queue_index", "queue_position", "position") if normalized.get(key) is not None), None)
    raw_total = next((normalized.get(key) for key in ("queue_length", "queue_total", "total") if normalized.get(key) is not None), None)
    for key in ("queue_idx", "queue_index", "queue_position", "position", "queue_length", "queue_total", "total"):
        normalized.pop(key, None)
    if isinstance(raw_position, bool) or isinstance(raw_total, bool):
        return normalized
    try:
        position = float(raw_position)
        total = float(raw_total)
    except (TypeError, ValueError):
        return normalized
    if not math.isfinite(position) or not math.isfinite(total) or not position.is_integer() or not total.is_integer():
        return normalized
    position = int(position)
    total = int(total)
    if position > 0 and total > 0 and position <= total:
        normalized["queue_idx"] = position
        normalized["queue_length"] = total
    return normalized

def jimeng_queue_progress(queue_info):
    normalized = normalize_jimeng_queue_info(queue_info)
    position = normalized.get("queue_idx")
    total = normalized.get("queue_length")
    return (position, total) if position and total else None

class JimengPendingError(Exception):
    """即梦任务还在云端排队/生成（轮询超时但未失败）。submit_id 可用于后续续查。"""
    def __init__(self, submit_id, kind="image", queue_info=None, raw=None):
        self.submit_id = str(submit_id or "")
        self.kind = kind or "image"
        self.queue_info = normalize_jimeng_queue_info(queue_info)
        self.raw = raw
        super().__init__(f"jimeng pending submit_id={self.submit_id}")

def jimeng_queue_info(raw):
    """从即梦原始返回里就近取出 queue_info（含 queue_idx/queue_length/queue_status）。"""
    found = []
    def visit(value):
        if isinstance(value, dict):
            qi = value.get("queue_info")
            if isinstance(qi, dict) and qi:
                found.append(qi)
            for item in value.values():
                if isinstance(item, (dict, list)):
                    visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(raw)
    return normalize_jimeng_queue_info(found[0]) if found else {}

def jimeng_pending_payload(exc: "JimengPendingError"):
    qi = normalize_jimeng_queue_info(exc.queue_info)
    progress = jimeng_queue_progress(qi)
    if progress:
        position, total = progress
        msg = f"即梦云端排队中（第 {position}/{total} 位），任务未丢失，可继续等待或手动查询。submit_id={exc.submit_id}"
    else:
        msg = f"即梦任务正在云端处理，任务未丢失。submit_id={exc.submit_id}"
    return {
        "jimeng_pending": True,
        "submit_id": exc.submit_id,
        "kind": exc.kind,
        "queue_info": qi,
        "message": msg,
    }

@app.exception_handler(JimengPendingError)
async def jimeng_pending_exception_handler(request: Request, exc: JimengPendingError):
    # 轮询超时但任务还在云端排队：返回 202 + submit_id，让前端保持「排队中」卡片并续查
    return JSONResponse(status_code=202, content=jimeng_pending_payload(exc))

def jimeng_failure_reason(raw):
    found = []
    def visit(value):
        if isinstance(value, dict):
            status = str(value.get("gen_status") or value.get("status") or "").strip().lower()
            reason = value.get("fail_reason") or value.get("failReason") or value.get("error") or value.get("message") or value.get("msg")
            if reason and (status in {"fail", "failed", "error"} or "fail" in str(reason).lower() or "invalid param" in str(reason).lower()):
                found.append(str(reason))
            for item in value.values():
                if isinstance(item, (dict, list)):
                    visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(raw)
    return jimeng_friendly_error_detail(found[0]) if found else ""

def jimeng_friendly_error_detail(detail):
    text = str(detail or "").strip()
    if "aigccomplianceconfirmationrequired" in text.lower():
        return "即梦要求先完成内容安全授权。请在 Dreamina 网页端按提示确认授权后，再返回此处重试。"
    return text

def jimeng_collect_media_values(value, outputs):
    media_ext = re.compile(r"\.(png|jpe?g|webp|gif|bmp|mp4|webm|mov|m4v|avi|mkv)(\?|#|$)", re.I)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return
        if text.startswith((
            "http://", "https://", "/api/results/", "/api/materials/",
            "/output/", "/assets/", "file://",
        )) or media_ext.search(text):
            outputs.append(text)
        return
    if isinstance(value, list):
        for item in value:
            jimeng_collect_media_values(item, outputs)
        return
    if isinstance(value, dict):
        for key in (
            "url", "urls", "image", "images", "image_url", "image_urls",
            "video", "videos", "video_url", "video_urls", "output", "outputs",
            "result", "results", "file", "files", "path", "paths",
            "download_url", "download_urls", "downloadUrl", "file_path", "filePath",
        ):
            if key in value:
                jimeng_collect_media_values(value.get(key), outputs)
        for item in value.values():
            if isinstance(item, (dict, list)):
                jimeng_collect_media_values(item, outputs)

def jimeng_output_values(raw):
    outputs = []
    jimeng_collect_media_values(raw, outputs)
    deduped = []
    for value in outputs:
        if value not in deduped:
            deduped.append(value)
    return deduped

JIMENG_RATIO_CHOICES = [(21, 9), (16, 9), (3, 2), (4, 3), (1, 1), (3, 4), (2, 3), (9, 16)]
def jimeng_ratio_from_size(size, fallback="1:1"):
    width, height = parse_size_pair(size)
    if not width or not height:
        return fallback
    ratio = width / max(1, height)
    left, right = min(JIMENG_RATIO_CHOICES, key=lambda item: abs(ratio - item[0] / item[1]))
    return f"{left}:{right}"

# 官方 dreamina 支持的图片模型（来自 text2image/image2image -h）。
# image2image 不支持 3.0/3.1。
JIMENG_TEXT2IMAGE_MODELS = {"3.0", "3.1", "4.0", "4.1", "4.5", "4.6", "4.7", "5.0", "5.0Pro"}
JIMENG_IMAGE2IMAGE_MODELS = {"4.0", "4.1", "4.5", "4.6", "4.7", "5.0", "5.0Pro"}

def jimeng_normalize_image_model(model):
    text = str(model or "").strip()
    if re.search(r"\b5(?:\.0)?\s*[-_ ]?pro\b", text, re.IGNORECASE):
        return "5.0Pro"
    match = re.search(r"(\d+\.\d+)", text)
    return match.group(1) if match else ""

def jimeng_image_model_version(model, mode="text2image"):
    version = jimeng_normalize_image_model(model)
    allowed = JIMENG_IMAGE2IMAGE_MODELS if mode == "image2image" else JIMENG_TEXT2IMAGE_MODELS
    return version if version in allowed else ""

def jimeng_validate_image_resolution(model, resolution, mode="text2image"):
    requested = str(resolution or "").strip().lower()
    if not requested:
        return ""
    version = jimeng_image_model_version(model, mode)
    if not version:
        supported_models = ", ".join(sorted(JIMENG_IMAGE2IMAGE_MODELS if mode == "image2image" else JIMENG_TEXT2IMAGE_MODELS))
        raise HTTPException(status_code=400, detail=f"即梦 {mode} 不支持图片模型「{model}」，当前支持：{supported_models}。")
    options = jimeng_image_resolution_options(version, mode)
    if requested not in options:
        readable = "、".join(item.upper() for item in options)
        raise HTTPException(status_code=400, detail=f"即梦图片模型 {version} 不支持分辨率 {requested.upper()}，请选择：{readable}。")
    return requested

def jimeng_image_resolution(model, size, mode="text2image"):
    text = str(model or "").lower()
    if "4k" in text:
        desired = "4k"
    elif "1k" in text:
        desired = "1k"
    elif "2k" in text:
        desired = "2k"
    else:
        width, height = parse_size_pair(size)
        longest_side = max(width, height)
        pixel_count = width * height
        if longest_side > 3072 or pixel_count > 6000000:
            desired = "4k"
        elif longest_side > 1536 or pixel_count > 1572864:
            desired = "2k"
        else:
            desired = "1k"
    version = jimeng_image_model_version(model, mode) or "5.0"
    options = jimeng_image_resolution_options(version, mode)
    if not options:
        raise HTTPException(status_code=400, detail=f"即梦图片模型 {model} 不支持当前的图片输入模式。")
    if desired in options:
        return desired
    if desired == "4k" and "4k" in options:
        return "4k"
    if desired in {"2k", "4k"} and "2k" in options:
        return "2k"
    # 扩充显式选项不改变未选择参数时的既有 2K 兜底。
    if version == "5.0Pro":
        return "2k"
    return options[0]

JIMENG_VIDEO_MODEL_VERSIONS = {
    "seedance1.0fast", "seedance1.5pro", "seedance2.0", "seedance2.0fast",
    "seedance2.0_vip", "seedance2.0fast_vip", "seedance2.0mini", "seedance2.5",
}
JIMENG_VIDEO_MODELS_BY_COMMAND = {
    "text2video": {"seedance2.0", "seedance2.0fast", "seedance2.0_vip", "seedance2.0fast_vip", "seedance2.0mini", "seedance2.5"},
    "image2video": {"seedance1.0fast", "seedance1.5pro", "seedance2.0", "seedance2.0fast", "seedance2.0_vip", "seedance2.0fast_vip", "seedance2.0mini", "seedance2.5"},
    "multimodal2video": {"seedance2.0", "seedance2.0fast", "seedance2.0_vip", "seedance2.0fast_vip", "seedance2.0mini", "seedance2.5"},
    "frames2video": {"seedance1.5pro", "seedance2.0", "seedance2.0fast", "seedance2.0_vip", "seedance2.0fast_vip", "seedance2.0mini", "seedance2.5"},
}

def jimeng_video_resolution(model, resolution):
    version = jimeng_video_model_version(model)
    requested = str(resolution or "").strip().lower()
    if not requested:
        requested = "720p"
    elif requested in {"4k", "4kp"}:
        requested = "4k"
    elif requested in {"1080p", "1080"}:
        requested = "1080p"
    elif requested in {"720p", "720"}:
        requested = "720p"
    elif requested in {"480p", "480"}:
        requested = "480p"
    else:
        raise HTTPException(status_code=400, detail="即梦视频分辨率无效：Seedance 2.5 支持 480p、720p；Seedance 2.0 VIP 支持 720p、1080p、4k；其他模型支持 720p。")
    allowed = ["480p", "720p"] if version == "seedance2.5" else (["720p", "1080p", "4k"] if version == "seedance2.0_vip" else ["720p"])
    if requested not in allowed:
        raise HTTPException(status_code=400, detail=f"即梦模型 {version or model} 只支持 {'、'.join(allowed)}。")
    return requested

# 各模型支持的时长区间（秒）：3.0 系列 3-10，3.5pro 4-12，seedance 4-15
def jimeng_video_duration_range(model, command=""):
    version = jimeng_video_model_version(model)
    if version == "seedance2.5":
        return 4, 30
    if command in {"image2video", "frames2video"} and version == "seedance1.5pro":
        return 5, 12
    if command == "image2video" and version == "seedance1.0fast":
        return 5, 10
    return 4, 15

def jimeng_video_duration(duration, model=None, command=""):
    low, high = jimeng_video_duration_range(model, command)
    default = max(low, min(high, 5))
    try:
        text = str(duration).strip() if duration is not None else ""
        value = default if text == "" else int(text)
    except Exception:
        raise HTTPException(status_code=400, detail=f"即梦视频时长必须是 {low}-{high} 秒的整数。")
    if not low <= value <= high:
        raise HTTPException(status_code=400, detail=f"即梦模型 {jimeng_video_model_version(model) or model} 只支持 {low}-{high} 秒时长。")
    return value

def jimeng_transition_duration(total_duration, transition_count):
    count = max(1, int(transition_count or 1))
    try:
        total = float(total_duration) if str(total_duration).strip() else 0.0
    except Exception:
        total = 0.0
    return max(1, min(8, int(round(3.0 if total <= 0 else total / count))))

def jimeng_multiframe_transition_prompts(prompt, segments):
    segments = max(1, int(segments or 1))
    prompts = [line.strip() for line in str(prompt or "").splitlines() if line.strip()]
    if not prompts:
        return []
    if len(prompts) == 1:
        prompts *= segments
    elif len(prompts) < segments:
        prompts.extend([prompts[-1]] * (segments - len(prompts)))
    return prompts[:segments]

def jimeng_video_model_version(model):
    value = str(model or "").strip()
    low = value.lower()
    aliases = {
        "seedance2.5": "seedance2.5",
        "seedance1.0fast": "seedance1.0fast",
        "seedance1.5pro": "seedance1.5pro",
        "seedance2.0fast_vip": "seedance2.0fast_vip",
        "seedance2.0_vip": "seedance2.0_vip",
        "seedance2.0mini": "seedance2.0mini",
        "seedance2.0fast": "seedance2.0fast",
        "seedance2.0": "seedance2.0",
    }
    for key, mapped in aliases.items():
        if key in low:
            return mapped if mapped in JIMENG_VIDEO_MODEL_VERSIONS else ""
    return ""

def jimeng_video_model_for_command(model, command):
    version = jimeng_video_model_version(model)
    allowed = JIMENG_VIDEO_MODELS_BY_COMMAND.get(command) or set()
    if version in allowed:
        return version
    supported = "、".join(sorted(allowed))
    raise HTTPException(status_code=400, detail=f"即梦 {command} 不支持模型「{model}」。可用模型：{supported}。")

def jimeng_video_resolution_arg(model, resolution):
    return jimeng_video_resolution(model, resolution)

def jimeng_video_ratio_arg(aspect_ratio):
    value = str(aspect_ratio or "").strip()
    allowed = {"1:1", "3:4", "16:9", "4:3", "9:16", "21:9"}
    if value in allowed:
        return value
    return ""

def jimeng_video_ratio(aspect_ratio, default="16:9"):
    value = str(aspect_ratio or "").strip()
    if not value:
        return default
    ratio = jimeng_video_ratio_arg(value)
    if not ratio:
        raise HTTPException(status_code=400, detail="即梦视频比例仅支持 1:1、3:4、16:9、4:3、9:16、21:9。")
    return ratio

def jimeng_append_model_resolution_args(args, payload: CanvasVideoRequest, model_version="", resolution=None):
    if model_version:
        args.append(f"--model_version={model_version}")
    requested_resolution = payload.resolution if resolution is None else resolution
    args.append(f"--video_resolution={jimeng_video_resolution_arg(model_version or payload.model, requested_resolution)}")

def jimeng_multiframe_resolution(resolution):
    value = str(resolution or "").strip().lower()
    if not value:
        return "720p"
    if value in {"720", "720p"}:
        return "720p"
    if value in {"1080", "1080p"}:
        return "1080p"
    raise HTTPException(status_code=400, detail="即梦多帧视频只支持 720p 或 1080p。")

def jimeng_video_ref_role(ref):
    role = getattr(ref, "role", "")
    if isinstance(ref, dict):
        role = ref.get("role", role)
    return str(role or "").lower()

def jimeng_video_ref_url(ref):
    url = getattr(ref, "url", "")
    if isinstance(ref, dict):
        url = ref.get("url", url)
    return str(url or "").strip()

def jimeng_local_output_url(path, kind="image"):
    path = os.path.abspath(str(path or ""))
    if not os.path.isfile(path):
        return ""
    output_root = os.path.abspath(OUTPUT_OUTPUT_DIR)
    try:
        if os.path.commonpath([output_root, path]) == output_root:
            return output_url_for(os.path.basename(path), "output")
    except Exception:
        pass
    ext = os.path.splitext(path)[1].lower()
    allowed = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv"}
    if ext not in allowed:
        ct = content_type_for_path(path)
        ext = ".mp4" if ct.startswith("video/") else ".png"
    prefix = "jimeng_video_" if kind == "video" else "jimeng_"
    filename = f"{prefix}{uuid.uuid4().hex[:10]}{ext}"
    dest = output_path_for(filename, "output")
    shutil.copyfile(path, dest)
    return output_url_for(filename, "output")

async def jimeng_store_output_value(value, kind="image"):
    text = str(value or "").strip()
    if not text:
        return ""
    if is_local_media_reference(text):
        local_path = local_media_reference_path(text)
        route = _local_media_route(text)
        if route:
            return text
        if local_path:
            return jimeng_local_output_url(local_path, kind)
        return ""
    if text.startswith("file://"):
        text = urllib.parse.unquote(urllib.parse.urlparse(text).path)
        if os.name == "nt" and re.match(r"^/[A-Za-z]:/", text):
            text = text[1:]
    if jimeng_use_wsl() and text.startswith("/mnt/"):
        text = wsl_path_to_windows(text)
    if text.startswith(("http://", "https://")):
        if kind == "video":
            return await save_remote_video_to_output(text, prefix="jimeng_video_")
        return await save_ai_image_to_output({"type": "url", "value": text}, prefix="jimeng_")
    if os.path.isfile(text):
        return jimeng_local_output_url(text, kind)
    return ""

async def jimeng_query_result(submit_id, kind="image"):
    args = [
        "query_result",
        f"--submit_id={submit_id}",
        f"--download_dir={jimeng_cli_path_arg(OUTPUT_OUTPUT_DIR)}",
    ]
    return await run_jimeng_cli(args, timeout=min(300, jimeng_poll_seconds() + 60))

async def jimeng_store_outputs(raw, kind="image", allow_query=True):
    failure = jimeng_failure_reason(raw)
    if failure:
        raise HTTPException(status_code=502, detail=f"即梦生成失败：{failure}")
    values = jimeng_output_values(raw)
    urls = []
    for value in values:
        local_url = await jimeng_store_output_value(value, kind)
        if local_url and local_url not in urls:
            urls.append(local_url)
    if urls:
        return urls
    submit_id = jimeng_submit_id(raw)
    if submit_id and allow_query:
        queried = await jimeng_query_result(submit_id, kind)
        try:
            return await jimeng_store_outputs(queried, kind, allow_query=False)
        except HTTPException as exc:
            if getattr(exc, "status_code", None) == 502:
                status_text = json.dumps(queried, ensure_ascii=False)[:800] if isinstance(queried, (dict, list)) else str(queried)[:800]
                raise HTTPException(status_code=502, detail=f"即梦任务已返回但没有下载到媒体：{status_text}") from exc
            raise
    status_text = json.dumps(raw, ensure_ascii=False)[:800] if isinstance(raw, (dict, list)) else str(raw)[:800]
    if submit_id:
        raise JimengPendingError(submit_id, kind, jimeng_queue_info(raw), raw)
    raise HTTPException(status_code=502, detail=f"即梦 CLI 未返回可用媒体结果：{status_text}")

async def jimeng_prepare_local_media(ref_url, kind="image"):
    text = str(ref_url or "").strip()
    if not text:
        return "", []
    if is_local_media_reference(text):
        path = local_media_reference_path(text)
        if path:
            return path, []
        raise HTTPException(status_code=404, detail=f"即梦参考素材不存在：{text}")
    suffix = ".mp4" if kind == "video" else (".mp3" if kind == "audio" else ".png")
    temp_paths = []
    if text.startswith("data:"):
        if ";base64," not in text:
            raise HTTPException(status_code=400, detail="即梦参考素材 data URL 缺少 base64 数据")
        header, encoded = text.split(";base64,", 1)
        mime = header.split(":", 1)[1].split(";", 1)[0] if ":" in header else ""
        suffix = mimetypes.guess_extension(mime) or suffix
        fd, path = tempfile.mkstemp(prefix="jimeng_ref_", suffix=suffix)
        with os.fdopen(fd, "wb") as f:
            f.write(base64.b64decode(encoded))
        temp_paths.append(path)
        return path, temp_paths
    if text.startswith(("http://", "https://")):
        async with httpx.AsyncClient(timeout=httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0), follow_redirects=True) as client:
            response = await client.get(text)
            response.raise_for_status()
            clean_path = urllib.parse.urlparse(text).path
            suffix = os.path.splitext(clean_path)[1] or mimetypes.guess_extension(response.headers.get("content-type", "")) or suffix
            fd, path = tempfile.mkstemp(prefix="jimeng_ref_", suffix=suffix)
            with os.fdopen(fd, "wb") as f:
                f.write(response.content)
            temp_paths.append(path)
            return path, temp_paths
    raise HTTPException(status_code=400, detail=f"即梦 CLI 只支持本地文件参考素材，无法读取：{text[:120]}")

async def generate_jimeng_provider_image(prompt, size, model, reference_images=None, provider=None, capability_parameters=None):
    refs = [ref for ref in (reference_images or []) if ref.get("url")]
    mapped_parameters = dict(capability_parameters or {})
    requested_ratio = str(mapped_parameters.get("ratio") or "").strip()
    requested_resolution = str(mapped_parameters.get("resolution_type") or mapped_parameters.get("resolution") or "").strip()
    mode = "image2image" if refs else "text2image"
    model_version = jimeng_image_model_version(model, mode)
    if not model_version:
        raise HTTPException(status_code=400, detail=f"即梦 {mode} 不支持图片模型「{model}」，请重新选择模型。")
    resolution = jimeng_validate_image_resolution(model_version, requested_resolution, mode) if requested_resolution else jimeng_image_resolution(model_version, size, mode)
    temp_paths = []
    try:
        args = []
        if refs:
            image_paths = []
            for ref in refs[:10]:
                image_path, created = await jimeng_prepare_local_media(ref.get("url"), "image")
                image_paths.append(jimeng_cli_path_arg(image_path))
                temp_paths.extend(created)
            args = [
                "image2image",
                f"--images={','.join(image_paths)}",
                f"--prompt={prompt}",
                f"--resolution_type={resolution}",
                f"--poll={jimeng_poll_seconds()}",
            ]
            if requested_ratio:
                args.append(f"--ratio={requested_ratio}")
            if model_version:
                args.append(f"--model_version={model_version}")
        else:
            args = [
                "text2image",
                f"--prompt={prompt}",
                f"--ratio={requested_ratio or jimeng_ratio_from_size(size)}",
                f"--resolution_type={resolution}",
                f"--poll={jimeng_poll_seconds()}",
            ]
            if model_version:
                args.append(f"--model_version={model_version}")
        raw = await run_jimeng_cli(args, timeout=jimeng_poll_seconds() + 120)
        urls = await jimeng_store_outputs(raw, "image")
        return {"type": "url", "value": urls[0]}, raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

JIMENG_UPSCALE_RESOLUTIONS = {"2k", "4k", "8k"}

def jimeng_normalize_upscale_resolution(value):
    resolution = str(value or "").strip().lower()
    return resolution if resolution in JIMENG_UPSCALE_RESOLUTIONS else "2k"

async def generate_jimeng_upscale_image(reference_images, resolution_type):
    refs = [ref for ref in (reference_images or []) if ref.get("url")]
    if not refs:
        raise HTTPException(status_code=400, detail="请先选择要放大的图片")
    temp_paths = []
    try:
        image_path, created = await jimeng_prepare_local_media(refs[0]["url"], "image")
        temp_paths.extend(created)
        raw = await run_jimeng_cli([
            "image_upscale",
            f"--image={jimeng_cli_path_arg(image_path)}",
            f"--resolution_type={jimeng_normalize_upscale_resolution(resolution_type)}",
            f"--poll={jimeng_poll_seconds()}",
        ], timeout=jimeng_poll_seconds() + 120)
        urls = await jimeng_store_outputs(raw, "image")
        return {"type": "url", "value": urls[0]}, raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def jimeng_canvas_video_parameters(payload: CanvasVideoRequest, capability_parameters=None):
    values = dict(capability_parameters or {})
    return {
        "duration": values.get("duration", payload.duration),
        "aspect_ratio": values.get("aspect_ratio", payload.aspect_ratio),
        "resolution": values.get("resolution", payload.resolution),
    }


def jimeng_video_reference_ratio(reference) -> float:
    def value(name):
        raw = reference.get(name) if isinstance(reference, dict) else getattr(reference, name, 0)
        try:
            return max(0.0, float(raw or 0))
        except (TypeError, ValueError):
            return 0.0

    width = value("natural_w") or value("width")
    height = value("natural_h") or value("height")
    return width / height if width > 0 and height > 0 else 0.0


def jimeng_video_requested_ratio(value) -> float:
    parts = str(value or "").strip().split(":")
    if len(parts) != 2:
        return 0.0
    try:
        width, height = float(parts[0]), float(parts[1])
    except (TypeError, ValueError):
        return 0.0
    return width / height if width > 0 and height > 0 else 0.0


def jimeng_video_requires_multimodal(payload: CanvasVideoRequest, capability_parameters=None) -> bool:
    image_refs = [ref for ref in (payload.images or []) if jimeng_video_ref_url(ref)]
    roles = {jimeng_video_ref_role(ref) for ref in image_refs}
    if len(image_refs) == 2 and {"first_frame", "last_frame"}.issubset(roles):
        return False
    if payload.multimodal or payload.videos or payload.audios or len(image_refs) > 1:
        return True
    if len(image_refs) != 1:
        return False
    requested = jimeng_video_requested_ratio(jimeng_canvas_video_parameters(payload, capability_parameters)["aspect_ratio"])
    if not requested:
        return False
    source = jimeng_video_reference_ratio(image_refs[0])
    return not source or abs(source - requested) / requested > 0.01


async def generate_jimeng_video(payload: CanvasVideoRequest, provider, capability_parameters=None):
    video_parameters = jimeng_canvas_video_parameters(payload, capability_parameters)
    payload_duration = video_parameters["duration"]
    payload_aspect_ratio = video_parameters["aspect_ratio"]
    payload_resolution = video_parameters["resolution"]
    image_refs = [ref for ref in (payload.images or []) if jimeng_video_ref_url(ref)]
    video_refs = [url for url in (payload.videos or []) if str(url or "").strip()]
    audio_refs = [url for url in (payload.audios or []) if str(url or "").strip()]
    is_seedance_25 = jimeng_video_model_version(payload.model) == "seedance2.5"
    temp_paths = []
    try:
        if jimeng_video_requires_multimodal(payload, capability_parameters):
            if not image_refs and not video_refs and not (is_seedance_25 and audio_refs):
                raise HTTPException(status_code=400, detail="即梦全能参考至少需要一张图片或一个视频，音频不能单独生成视频。")
            model_version = jimeng_video_model_for_command(payload.model, "multimodal2video")
            duration = jimeng_video_duration(payload_duration, model_version, "multimodal2video")
            image_paths = []
            video_paths = []
            audio_paths = []
            for ref in image_refs[:30 if is_seedance_25 else 9]:
                image_path, created = await jimeng_prepare_local_media(jimeng_video_ref_url(ref), "image")
                temp_paths.extend(created)
                image_paths.append(image_path)
            for ref_url in video_refs[:10 if is_seedance_25 else 3]:
                video_path, created = await jimeng_prepare_local_media(ref_url, "video")
                temp_paths.extend(created)
                video_paths.append(video_path)
            for ref_url in audio_refs[:10 if is_seedance_25 else 3]:
                audio_path, created = await jimeng_prepare_local_media(ref_url, "audio")
                temp_paths.extend(created)
                audio_paths.append(audio_path)
            args = [
                "multimodal2video",
                f"--prompt={payload.prompt}",
                f"--duration={duration}",
                f"--poll={jimeng_poll_seconds()}",
            ]
            args.append(f"--ratio={jimeng_video_ratio(payload_aspect_ratio)}")
            jimeng_append_model_resolution_args(args, payload, model_version, payload_resolution)
            for image_path in image_paths:
                args.append(f"--image={jimeng_cli_path_arg(image_path)}")
            for video_path in video_paths:
                args.append(f"--video={jimeng_cli_path_arg(video_path)}")
            for audio_path in audio_paths:
                args.append(f"--audio={jimeng_cli_path_arg(audio_path)}")
        elif len(image_refs) >= 2:
            if len(image_refs) > 20:
                raise HTTPException(status_code=400, detail="即梦多帧视频最多支持 20 张图片。")
            first_frame = next((ref for ref in image_refs if jimeng_video_ref_role(ref) == "first_frame"), None)
            last_frame = next((ref for ref in image_refs if jimeng_video_ref_role(ref) == "last_frame"), None)
            if first_frame and last_frame:
                model_version = jimeng_video_model_for_command(payload.model, "frames2video")
                duration = jimeng_video_duration(payload_duration, model_version, "frames2video")
                first_path, created = await jimeng_prepare_local_media(jimeng_video_ref_url(first_frame), "image")
                temp_paths.extend(created)
                last_path, created = await jimeng_prepare_local_media(jimeng_video_ref_url(last_frame), "image")
                temp_paths.extend(created)
                args = [
                    "frames2video",
                    f"--first={jimeng_cli_path_arg(first_path)}",
                    f"--last={jimeng_cli_path_arg(last_path)}",
                    f"--prompt={payload.prompt}",
                    f"--duration={duration}",
                    f"--poll={jimeng_poll_seconds()}",
                ]
                jimeng_append_model_resolution_args(args, payload, model_version, payload_resolution)
            else:
                image_paths = []
                for ref in image_refs:
                    image_path, created = await jimeng_prepare_local_media(jimeng_video_ref_url(ref), "image")
                    temp_paths.extend(created)
                    image_paths.append(image_path)
                args = [
                    "multiframe2video",
                    f"--images={','.join(jimeng_cli_path_arg(path) for path in image_paths)}",
                    f"--poll={jimeng_poll_seconds()}",
                ]
                # multiframe2video has its own transition arguments and does not
                # accept model_version. The CLI requires an explicit resolution.
                args.append(f"--video_resolution={jimeng_multiframe_resolution(payload_resolution)}")
                segments = max(1, len(image_paths) - 1)
                segment_duration = jimeng_transition_duration(payload_duration, segments)
                if len(image_paths) <= 2:
                    if str(payload.prompt or "").strip():
                        args.append(f"--prompt={payload.prompt}")
                    args.append(f"--duration={segment_duration}")
                else:
                    for segment_prompt in jimeng_multiframe_transition_prompts(payload.prompt, segments):
                        args.append(f"--transition-prompt={segment_prompt}")
                    for _ in range(segments):
                        args.append(f"--transition-duration={segment_duration}")
        elif image_refs:
            model_version = jimeng_video_model_for_command(payload.model, "image2video")
            duration = jimeng_video_duration(payload_duration, model_version, "image2video")
            image_path, created = await jimeng_prepare_local_media(jimeng_video_ref_url(image_refs[0]), "image")
            temp_paths.extend(created)
            args = [
                "image2video",
                f"--image={jimeng_cli_path_arg(image_path)}",
                f"--prompt={payload.prompt}",
                f"--duration={duration}",
                f"--poll={jimeng_poll_seconds()}",
            ]
            jimeng_append_model_resolution_args(args, payload, model_version, payload_resolution)
        else:
            model_version = jimeng_video_model_for_command(payload.model, "text2video")
            duration = jimeng_video_duration(payload_duration, model_version, "text2video")
            args = [
                "text2video",
                f"--prompt={payload.prompt}",
                f"--duration={duration}",
                f"--ratio={jimeng_video_ratio(payload_aspect_ratio)}",
                f"--poll={jimeng_poll_seconds()}",
            ]
            jimeng_append_model_resolution_args(args, payload, model_version, payload_resolution)
        # Do not hold the canvas request open for the full cloud generation.
        # A pending result carries submit_id and is resumed by the existing UI poller.
        submit_poll = jimeng_video_submit_poll_seconds()
        args = [f"--poll={submit_poll}" if str(arg).startswith("--poll=") else arg for arg in args]
        raw = await run_jimeng_cli(args, timeout=submit_poll + 180)
        urls = await jimeng_store_outputs(raw, "video")
        return {"videos": urls, "task_id": jimeng_submit_id(raw) or None, "raw": raw}
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

IMAGE_TASK_SUCCESS_STATUSES = {"SUCCESS", "SUCCESSFUL", "SUCCEED", "SUCCEEDED", "COMPLETED", "COMPLETE", "DONE", "FINISHED", "OK", "READY"}
IMAGE_TASK_FAILED_STATUSES = {"FAILURE", "FAILED", "FAIL", "ERROR", "ERRORED", "CANCELED", "CANCELLED", "TIMEOUT", "REJECTED", "EXPIRED"}

def image_task_url_for_provider(provider, task_id):
    base_url = (provider.get("base_url") if provider else AI_BASE_URL).rstrip("/")
    if is_ai_money_provider(provider):
        return ai_money_image_task_url(provider, task_id)
    if is_tudou_async_image_mode(provider):
        return f"{base_url}/tasks/{task_id}" if base_url.endswith("/v1") else f"{base_url}/v1/tasks/{task_id}"
    # 异步生图（openai-video-proxy）模式优先于 apimart 协议判断：
    # 提交走 /v1/videos，轮询必须走 /v1/videos/{id}；否则 protocol=apimart 的平台会错走 /v1/tasks/{id}
    if normalize_image_request_mode((provider or {}).get("image_request_mode")) == "openai-video-proxy":
        return f"{base_url}/videos/{task_id}" if base_url.endswith("/v1") else f"{base_url}/v1/videos/{task_id}"
    if is_apimart_provider(provider):
        return f"{base_url}/tasks/{task_id}" if base_url.endswith("/v1") else f"{base_url}/v1/tasks/{task_id}"
    return f"{base_url}/images/tasks/{task_id}" if base_url.endswith("/v1") else f"{base_url}/v1/images/tasks/{task_id}"

def ai_money_image_task_url(provider, task_id):
    base_url = laohu_api_base_url(provider)
    return f"{base_url}/v1/image/generations/{urllib.parse.quote(str(task_id), safe='')}"

def merge_request_body(base, overlay):
    result = dict(base or {})
    for key, value in (overlay or {}).items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_request_body(result[key], value)
        else:
            result[key] = value
    return result

def ai_money_image_request_body(prompt, model, reference_urls=None, aspect_ratio="", resolution="", capability_parameters=None):
    body = {
        "model": normalize_laohu_model_id(selected_model(model, "seedream-v5-pro-t2i")),
        "prompt": str(prompt or ""),
    }
    references = [str(url or "").strip() for url in (reference_urls or []) if str(url or "").strip()]
    if references:
        body["images"] = references
    metadata = {}
    if capability_parameters is None and str(aspect_ratio or "").strip():
        metadata["ratio"] = str(aspect_ratio).strip()
    if capability_parameters is None and str(resolution or "").strip():
        metadata["resolution"] = str(resolution).strip()
    if metadata:
        body["metadata"] = metadata
    return merge_request_body(body, capability_parameters)

def ai_money_video_request_body(model, prompt, seconds, aspect_ratio="", resolution="", image_urls=None, video_urls=None, audio_urls=None, generate_audio=False, return_last_frame=False, seed=None, capability_parameters=None):
    model_name = normalize_laohu_model_id(selected_model(model, "seedance-2.0-fast-t2v"))
    lower_model = model_name.lower()
    images = [str(url or "").strip() for url in (image_urls or []) if str(url or "").strip()]
    videos = [str(url or "").strip() for url in (video_urls or []) if str(url or "").strip()]
    audios = [str(url or "").strip() for url in (audio_urls or []) if str(url or "").strip()]
    if lower_model == "animate-motion-transfer":
        if len(images) != 1 or len(videos) != 1:
            raise HTTPException(status_code=400, detail="Animate 动作迁移需要一张角色图片和一个参考动作视频。")
        metadata = {"video_url": videos}
        if capability_parameters:
            metadata.update({key: value for key, value in capability_parameters.items() if value not in (None, "")})
        return merge_request_body({"model": model_name, "images": images, "metadata": metadata}, None)
    is_wan_3_reference = bool(re.fullmatch(r"wan-3\.0-(?:global-)?prime-r2v", lower_model))
    if lower_model.endswith("-i2v") and not images:
        raise HTTPException(status_code=400, detail="laohu 图生视频模型需要至少一张参考图片。")
    if is_wan_3_reference and not (images or videos or audios):
        raise HTTPException(status_code=400, detail="laohu Wan 3.0 参考生视频模型需要至少一个图片、视频或音频参考素材。")
    body = {
        "model": model_name,
        "prompt": str(prompt or ""),
        "seconds": str(max(1, int(seconds or 5))),
    }
    metadata = {}
    if capability_parameters is None and str(aspect_ratio or "").strip():
        metadata["ratio"] = str(aspect_ratio).strip()
    if capability_parameters is None and str(resolution or "").strip():
        metadata["resolution"] = str(resolution).strip()
    if capability_parameters is None and generate_audio:
        metadata["generate_audio"] = True
    if capability_parameters is None and return_last_frame:
        metadata["return_last_frame"] = True
    if capability_parameters is None and seed is not None:
        metadata["seed"] = seed
    if lower_model.endswith("-multi") or is_wan_3_reference:
        content = []
        for url in images:
            content.append({"type": "image_url", "image_url": {"url": url}})
        for url in videos:
            content.append({"type": "video_url", "video_url": {"url": url}})
        for url in audios:
            content.append({"type": "audio_url", "audio_url": {"url": url}})
        if content:
            metadata["content"] = content
    elif lower_model.endswith(("-fl2va-audio-drive-fast", "-ref2va-audio-drive-fast")):
        if images:
            body["images"] = images[:1]
        if audios:
            metadata["audio_urls"] = audios[:1]
    elif images:
        body["images"] = images
    if metadata:
        body["metadata"] = metadata
    return merge_request_body(body, capability_parameters)

def ai_money_fashvsr_request_body(model, video_url):
    model_name = str(model or "").strip()
    if model_name.lower() not in {"fashvsr_video_upscale", "fashvsr-video-upscale", "flashvsr_video_upscale", "vosr2-video-upscale"}:
        raise HTTPException(status_code=400, detail=f"不是 FashVSR 视频放大模型：{model_name}")
    source_url = str(video_url or "").strip()
    if not source_url:
        raise HTTPException(status_code=400, detail="FashVSR 视频放大需要一个输入视频。")
    return {"model": model_name, "metadata": {"video_url": source_url}}

AI_MONEY_AUDIO_FORMATS = {"wav", "mp3", "pcm", "ogg_opus"}
AI_MONEY_AUDIO_SAMPLE_RATES = {8000, 16000, 24000, 32000, 44100}
AI_MONEY_REFERENCE_AUDIO_MODELS = {
    "qwen3-tts-flash", "qwen3-tts-instruct-flash",
    "minimax-music-2.6", "minimax-speech-2.8-hd", "minimax-speech-2.8-turbo",
    "minimax-voice-clone",
}

def ai_money_music_api_url(provider, action=""):
    base_url = laohu_api_base_url(provider)
    suffix = str(action or "").strip().strip("/")
    return f"{base_url}/v1/music/generations/{suffix}" if suffix else f"{base_url}/v1/music/generations"

def ai_money_suno_request_body(model, prompt, capability_parameters=None):
    model_name = str(model or "").strip().lower()
    if not model_name.startswith("suno-"):
        raise HTTPException(status_code=400, detail=f"不是 Suno 模型：{model}")
    body = {"model": "suno"}
    prompt_text = str(prompt or "").strip()
    if prompt_text:
        body["prompt"] = prompt_text
    body = merge_request_body(body, capability_parameters)
    action = model_name.removeprefix("suno-")
    if action == "upload-cover" and body.get("custom") is not True:
        body["gpt_description"] = body.pop("prompt", "")
    if action == "create-model":
        body.pop("prompt", None)
        body.pop("audio_url", None)
    if action == "generation" and not body.get("version") and not body.get("custom_model_id"):
        body["version"] = "v6"
    return body

def ai_money_flowmusic_request_body(model, prompt, reference_audio_url="", capability_parameters=None):
    model_name = str(model or "").strip().lower()
    if not model_name.startswith("flowmusic-"):
        raise HTTPException(status_code=400, detail=f"不是 FlowMusic 模型：{model}")
    action = model_name.removeprefix("flowmusic-")
    parameters = dict(capability_parameters or {})
    body = {"model": "flowmusic"}
    if action == "generation":
        body["sound_prompt"] = str(prompt or "").strip()
    elif action == "lyrics":
        body["prompt"] = str(prompt or "").strip()
    reference_url = str(reference_audio_url or "").strip()
    if action == "upload-audio" and reference_url:
        body["audio_url"] = reference_url
    body = merge_request_body(body, parameters)
    if action in {"generation", "extend", "replace", "cover"}:
        body.setdefault("version", "lyria-3.5")
    return body

def ai_money_audio_request_body(model, prompt, reference_audio_url="", speaker="", audio_format="mp3", sample_rate=24000, speech_rate=0, loudness_rate=0, pitch_rate=0, capability_parameters=None):
    model_name = normalize_laohu_model_id(selected_model(model, "doubao-seed-audio-1.0"))
    if model_name.lower().startswith("flowmusic-"):
        return ai_money_flowmusic_request_body(model_name, prompt, reference_audio_url, capability_parameters)
    if model_name in {"mureka-v8-bgm", "mureka-v9-bgm"}:
        raw_parameters = capability_parameters or {}
        metadata = dict(raw_parameters.get("metadata") or {}) if isinstance(raw_parameters, dict) else {}
        if not metadata and isinstance(raw_parameters, dict):
            metadata = dict(raw_parameters)
        return {"model": model_name, "prompt": str(prompt or ""), "metadata": metadata}
    if model_name in {"mureka-o2-song", "mureka-v9-song"}:
        raw_parameters = capability_parameters or {}
        metadata = dict(raw_parameters.get("metadata") or {}) if isinstance(raw_parameters, dict) else {}
        if not metadata and isinstance(raw_parameters, dict):
            metadata = dict(raw_parameters)
        lyrics = str(metadata.get("lyrics") or prompt or "").strip()
        if not lyrics:
            raise HTTPException(status_code=400, detail="Mureka 歌曲模型需要歌词内容。")
        metadata["lyrics"] = lyrics
        return {"model": model_name, "metadata": metadata}
    if model_name in AI_MONEY_REFERENCE_AUDIO_MODELS:
        body = merge_request_body(
            {"model": model_name, "prompt": str(prompt or ""), "metadata": {}},
            capability_parameters,
        )
        reference_audio = str(reference_audio_url or "").strip()
        if reference_audio:
            body.setdefault("metadata", {})["audio_url"] = reference_audio
        return body
    if model_name != "doubao-seed-audio-1.0":
        raise HTTPException(status_code=400, detail="laohu 当前只开放已完成适配的豆包 Seed Audio 模型。")
    reference_audio = str(reference_audio_url or "").strip()
    speaker_name = str(speaker or "").strip()
    if reference_audio and speaker_name:
        raise HTTPException(status_code=400, detail="参考音频与预设音色互斥，只能选择一种。")
    format_name = str(audio_format or "mp3").strip().lower()
    if format_name not in AI_MONEY_AUDIO_FORMATS:
        raise HTTPException(status_code=400, detail=f"不支持的音频格式：{format_name}")
    try:
        rate = int(sample_rate or 24000)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="音频采样率必须是整数。") from exc
    if rate not in AI_MONEY_AUDIO_SAMPLE_RATES:
        raise HTTPException(status_code=400, detail=f"不支持的音频采样率：{rate}")
    controls = {
        "speech_rate": (speech_rate, -50, 100),
        "loudness_rate": (loudness_rate, -50, 100),
        "pitch_rate": (pitch_rate, -12, 12),
    }
    normalized = {}
    for key, (value, minimum, maximum) in controls.items():
        try:
            numeric = int(value or 0)
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail=f"{key} 必须是整数。") from exc
        if numeric < minimum or numeric > maximum:
            raise HTTPException(status_code=400, detail=f"{key} 必须在 {minimum} 到 {maximum} 之间。")
        normalized[key] = numeric
    metadata = {"format": format_name, "sample_rate": str(rate), **normalized}
    if reference_audio:
        metadata["audio_url"] = reference_audio
    elif speaker_name:
        metadata["speaker"] = speaker_name
    return merge_request_body(
        {"model": model_name, "prompt": str(prompt or ""), "metadata": metadata},
        capability_parameters,
    )

def ai_money_audio_output_urls(raw):
    urls = []
    def collect(value, depth=0):
        if depth > 8 or value is None:
            return
        if isinstance(value, str):
            text = value.strip()
            if text.startswith(("http://", "https://", "/output/", "/assets/", "/api/results/")) and text not in urls:
                urls.append(text)
            return
        if isinstance(value, list):
            for item in value:
                collect(item, depth + 1)
            return
        if isinstance(value, dict):
            for key in ("result_url", "resultUrl", "audio_url", "audioUrl", "audio_urls", "audioUrls", "url", "urls", "data", "result", "results", "content", "metadata", "output", "outputs"):
                if key in value:
                    collect(value.get(key), depth + 1)
    collect(raw)
    return urls

def ai_money_audio_result_text(raw):
    def find(value, depth=0):
        if depth > 8 or value is None:
            return ""
        if isinstance(value, list):
            for item in value:
                found = find(item, depth + 1)
                if found:
                    return found
            return ""
        if not isinstance(value, dict):
            return ""
        for key in ("voice_id", "voiceId", "result_text", "resultText", "text"):
            text = str(value.get(key) or "").strip()
            if text:
                return text
        for key in ("data", "result", "results", "content", "metadata", "output", "outputs"):
            found = find(value.get(key), depth + 1)
            if found:
                return found
        return ""
    return find(raw)

def ai_money_flowmusic_result(raw, action):
    action = str(action or "").strip().lower()
    data = raw.get("data") if isinstance(raw, dict) and isinstance(raw.get("data"), dict) else raw
    result = data.get("result") if isinstance(data, dict) and isinstance(data.get("result"), dict) else {}
    music = result.get("music") if isinstance(result, dict) else None
    first = music[0] if isinstance(music, list) and music and isinstance(music[0], dict) else {}
    if action == "lyrics":
        lyrics = result.get("lyrics") if isinstance(result, dict) else None
        if isinstance(lyrics, list) and lyrics and isinstance(lyrics[0], dict):
            text = str(lyrics[0].get("lyrics") or "").strip()
            name = str(lyrics[0].get("title") or "flowmusic-lyrics.txt").strip()
            if text:
                return {"texts": [(text, name)]}
        return {"texts": []}
    if action == "video-clip":
        url = str(first.get("video_url") or first.get("url") or "").strip()
        return {"videos": [url] if url else []}
    if action == "stems":
        url = str(first.get("file_url") or first.get("url") or "").strip()
        return {"files": [url] if url else []}
    url = str(first.get("audio_url") or first.get("wav_url") or first.get("url") or "").strip()
    return {"audios": [url] if url else []}

async def wait_for_ai_money_audio_task(client, provider, task_id):
    base_url = laohu_api_base_url(provider)
    task_url = f"{base_url}/v1/audio/generations/{urllib.parse.quote(str(task_id), safe='')}"
    deadline = time.monotonic() + VIDEO_POLL_TIMEOUT
    delay = max(2.0, IMAGE_POLL_INTERVAL)
    last_payload = {}
    while time.monotonic() < deadline:
        await asyncio.sleep(delay)
        response = await client.get(task_url, headers=api_headers(provider=provider))
        response.raise_for_status()
        raw = response.json()
        last_payload = raw
        data = raw.get("data") if isinstance(raw, dict) and isinstance(raw.get("data"), dict) else raw
        status = str((data or {}).get("status") or (raw or {}).get("status") or "").upper()
        if ai_money_audio_output_urls(raw) and status not in VIDEO_TASK_FAILURE_STATUSES:
            return raw
        if status in VIDEO_TASK_SUCCESS_STATUSES:
            return raw
        if status in VIDEO_TASK_FAILURE_STATUSES:
            reason = (data or {}).get("message") or (data or {}).get("error") or (raw or {}).get("message") or str(raw)
            raise HTTPException(status_code=502, detail=f"laohu 音频任务失败：{reason}")
        delay = min(delay * 1.5, 10.0)
    raise HTTPException(status_code=504, detail=f"laohu 音频任务超时：{last_payload or task_id}")

async def wait_for_ai_money_music_task(client, provider, task_id):
    base_url = laohu_api_base_url(provider)
    task_url = f"{base_url}/v1/music/tasks/{urllib.parse.quote(str(task_id), safe='')}"
    deadline = time.monotonic() + VIDEO_POLL_TIMEOUT
    delay = max(2.0, IMAGE_POLL_INTERVAL)
    last_payload = {}
    while time.monotonic() < deadline:
        await asyncio.sleep(delay)
        response = await client.get(task_url, headers=api_headers(provider=provider))
        response.raise_for_status()
        raw = response.json()
        last_payload = raw
        data = raw.get("data") if isinstance(raw, dict) and isinstance(raw.get("data"), dict) else raw
        status = str((data or {}).get("status") or "").strip().lower()
        if ai_money_audio_output_urls(raw) and status not in {"failed", "failure", "error", "cancelled", "canceled"}:
            return raw
        if status in {"completed", "complete", "success", "succeeded"}:
            return raw
        if status in {"failed", "failure", "error", "cancelled", "canceled"}:
            reason = (data or {}).get("message") or (data or {}).get("error") or str(raw)
            raise HTTPException(status_code=502, detail=f"laohu Suno 任务失败：{reason}")
        delay = min(delay * 1.5, 10.0)
    raise HTTPException(status_code=504, detail=f"laohu Suno 任务超时：{last_payload or task_id}")

async def generate_ai_money_audio(provider, model, prompt, reference_audio_url="", reference_audio_urls=None, speaker="", audio_format="mp3", sample_rate=24000, speech_rate=0, loudness_rate=0, pitch_rate=0, capability_parameters=None):
    api_key = provider_env_key_value((provider or {}).get("id") or "ai-money")
    if not api_key:
        raise HTTPException(status_code=400, detail="laohu 未配置 API Key，请先在 API 设置中填写。")
    base_url = laohu_api_base_url(provider)
    async with httpx.AsyncClient(timeout=VIDEO_POLL_TIMEOUT) as client:
        reference_url = str(reference_audio_url or "").strip()
        if reference_url:
            reference_url = await ai_money_upload_reference(client, provider, reference_url, "audio")
        if str(model or "").strip().lower().startswith("flowmusic-"):
            model_name = str(model or "").strip().lower()
            action = model_name.removeprefix("flowmusic-")
            body = ai_money_flowmusic_request_body(model_name, prompt, reference_url, capability_parameters)
            response = await client.post(
                ai_money_music_api_url(provider, "" if action == "generation" else action),
                headers=api_headers(provider=provider, model=body["model"]),
                json=body,
            )
            response.raise_for_status()
            raw = response.json()
            task_id = extract_task_id(raw) or midjourney_task_id(raw)
            result = await wait_for_ai_money_music_task(client, provider, task_id) if task_id else raw
            outputs = ai_money_flowmusic_result(result, action)
            if outputs.get("texts"):
                texts = [{"url": save_comfy_text_output(text, prefix="ai_money_flowmusic_", name=name), "kind": "text", "name": name} for text, name in outputs["texts"]]
                return {"texts": texts, "task_id": task_id, "raw": result}
            if outputs.get("videos"):
                videos = [await save_remote_video_to_output(url, prefix="ai_money_flowmusic_") for url in outputs["videos"] if url]
                return {"videos": [url for url in videos if url], "task_id": task_id, "raw": result}
            if outputs.get("files"):
                files = [await save_remote_zip_to_output(url, prefix="ai_money_flowmusic_") for url in outputs["files"] if url]
                return {"files": [url for url in files if url], "task_id": task_id, "raw": result}
            audios = [await save_remote_audio_to_output(url, prefix="ai_money_flowmusic_") for url in outputs.get("audios", []) if url]
            if not audios:
                raise HTTPException(status_code=502, detail=f"laohu FlowMusic 任务没有返回音频地址：{str(result)[:500]}")
            return {"audios": [url for url in audios if url], "task_id": task_id, "raw": result}
        if str(model or "").strip().lower().startswith("suno-"):
            action = str(model or "").strip().lower().removeprefix("suno-")
            action = "" if action == "generation" else action
            parameters = dict(capability_parameters or {})
            if action == "create-model":
                parameters["audio_urls"] = [await ai_money_upload_reference(client, provider, url, "audio") for url in (reference_audio_urls or [])]
                if not 6 <= len(parameters["audio_urls"]) <= 24:
                    raise HTTPException(400, "Suno 自定义模型需要 6–24 条音频")
            if reference_url and not any(parameters.get(key) for key in ("audio_url", "audioFilePath")):
                parameters["audio_url"] = reference_url
            body = ai_money_suno_request_body(model, prompt, parameters)
            response = await client.post(
                ai_money_music_api_url(provider, action),
                headers=api_headers(provider=provider),
                json=body,
            )
            response.raise_for_status()
            raw = response.json()
            task_id = extract_task_id(raw) or midjourney_task_id(raw)
            result = raw if ai_money_audio_output_urls(raw) else await wait_for_ai_money_music_task(client, provider, task_id) if task_id else raw
            if action == "create-model":
                result_data = (result.get("data") or {}).get("result") or result.get("result") or {}
                if not isinstance(result_data, dict) or not result_data.get("model_id"):
                    raise HTTPException(502, f"Suno 自定义模型任务 {task_id} 未返回 model_id，请检查平台任务状态")
                result_text = json.dumps(result_data, ensure_ascii=False, indent=2)
                return {"texts": [{"url": save_comfy_text_output(result_text, prefix="suno_model_", name="Suno 自定义模型"), "kind": "text", "name": "Suno 自定义模型"}], "task_id": task_id, "raw": result}
            urls = ai_money_audio_output_urls(result)
            if not urls:
                raise HTTPException(status_code=502, detail=f"laohu Suno 任务没有返回音频地址：{str(result)[:500]}")
            local_urls = [await save_remote_audio_to_output(url, prefix="ai_money_suno_") for url in urls]
            return {"audios": [url for url in local_urls if url], "task_id": task_id, "raw": result}
        model_name = str(model or "").strip().lower()
        body = ai_money_audio_request_body(model, prompt, reference_url, speaker, audio_format, sample_rate, speech_rate, loudness_rate, pitch_rate, capability_parameters)
        response = await client.post(
            f"{base_url}/v1/audio/generations",
            headers=api_headers(provider=provider, model=body["model"]),
            json=body,
        )
        response.raise_for_status()
        raw = response.json()
        task_id = extract_task_id(raw) or str(raw.get("id") or "") if isinstance(raw, dict) else ""
        result = raw
        immediate_text = ai_money_audio_result_text(raw) if model_name == "minimax-voice-clone" else ""
        if not ai_money_audio_output_urls(raw) and not immediate_text and task_id:
            result = await wait_for_ai_money_audio_task(client, provider, task_id)
        if model_name == "minimax-voice-clone":
            result_text = ai_money_audio_result_text(result)
            if not result_text:
                raise HTTPException(status_code=502, detail=f"laohu 音色克隆成功但没有返回音色 ID：{str(result)[:500]}")
            return {
                "texts": [{"url": result_text, "kind": "text", "name": result_text}],
                "task_id": task_id,
                "raw": result,
            }
        urls = ai_money_audio_output_urls(result)
        if not urls:
            raise HTTPException(status_code=502, detail=f"laohu 音频生成成功但没有返回音频地址：{str(result)[:500]}")
        local_urls = [await save_remote_audio_to_output(url, prefix="ai_money_audio_") for url in urls]
        return {"audios": [url for url in local_urls if url], "task_id": task_id, "raw": result}

def ai_money_file_url(payload):
    if isinstance(payload, list):
        for item in payload:
            found = ai_money_file_url(item)
            if found:
                return found
        return ""
    if not isinstance(payload, dict):
        return ""
    for key in ("url", "result_url", "resultUrl", "file_url", "fileUrl", "download_url", "downloadUrl", "uri"):
        value = str(payload.get(key) or "").strip()
        if value.startswith(("http://", "https://", "asset://")):
            return value
    for key in ("data", "result", "file", "files"):
        found = ai_money_file_url(payload.get(key))
        if found:
            return found
    return ""

def ai_money_extract_image(payload):
    try:
        return extract_image(payload)
    except HTTPException:
        result_url = ai_money_file_url(payload)
        if result_url:
            return {"type": "url", "value": result_url}
        raise

async def ai_money_upload_reference(client, provider, ref_url, kind="image"):
    value = str(ref_url or "").strip()
    if not value:
        raise HTTPException(status_code=400, detail="laohu 素材地址不能为空。")
    if value.startswith(("http://", "https://", "asset://")):
        return value
    if value.startswith("data:"):
        header, separator, encoded = value.partition(",")
        if not separator or ";base64" not in header:
            raise HTTPException(status_code=400, detail="laohu 只支持 base64 data URL 素材。")
        try:
            content = base64.b64decode(encoded)
        except Exception as exc:
            raise HTTPException(status_code=400, detail=f"laohu 素材解码失败：{exc}") from exc
        mime = header.split(":", 1)[-1].split(";", 1)[0] or "application/octet-stream"
        extension = mimetypes.guess_extension(mime) or ".bin"
        filename = f"canvas_{kind}_{uuid.uuid4().hex[:8]}{extension}"
    else:
        path = local_media_reference_path(value)
        if not path:
            raise HTTPException(status_code=400, detail=f"laohu 无法读取本地素材：{value}")
        try:
            with open(path, "rb") as file:
                content = file.read()
        except OSError as exc:
            raise HTTPException(status_code=400, detail=f"laohu 读取本地素材失败：{exc}") from exc
        mime = content_type_for_path(path)
        filename = os.path.basename(path) or f"canvas_{kind}"
    upload_url = f"{laohu_api_base_url(provider)}/v1/files/upload"
    response = await client.post(
        upload_url,
        headers=api_headers(json_body=False, provider=provider),
        files={"file": (filename, content, mime)},
    )
    response.raise_for_status()
    uploaded_url = ai_money_file_url(response.json())
    if not uploaded_url:
        raise HTTPException(status_code=502, detail=f"laohu 素材上传成功但没有返回可用地址：{response.text[:400]}")
    return uploaded_url

async def generate_ai_money_image(prompt, size, quality, model, reference_images, provider, aspect_ratio="", resolution="", capability_parameters=None):
    base_url = laohu_api_base_url(provider)
    references = []
    async with httpx.AsyncClient(timeout=AI_REQUEST_TIMEOUT) as client:
        for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
            references.append(await ai_money_upload_reference(client, provider, ref.get("url"), "image"))
        body = ai_money_image_request_body(prompt, model, references, aspect_ratio, resolution, capability_parameters)
        response = await client.post(
            f"{base_url}/v1/image/generations",
            headers=api_headers(provider=provider, model=body["model"]),
            json=body,
        )
        response.raise_for_status()
        raw = response.json()
        try:
            return ai_money_extract_image(raw), raw
        except HTTPException:
            data = raw.get("data") if isinstance(raw, dict) else {}
            task_id = extract_task_id(raw) or (data.get("id") if isinstance(data, dict) else "") or (raw.get("id") if isinstance(raw, dict) else "")
            if not task_id:
                raise
            result = await wait_for_image_task(client, str(task_id), provider)
            return ai_money_extract_image(result), result

async def generate_ai_money_midjourney_image(prompt, size, model, reference_images, provider, capability_parameters=None, operation=""):
    parameters = dict(capability_parameters or {})
    action = str(operation or "").strip().lower().removeprefix("midjourney_") or "imagine"
    image_urls = await midjourney_reference_urls(reference_images)
    speed = str(parameters.get("speed") or "relax").strip().lower()
    if speed not in MIDJOURNEY_SPEEDS:
        raise HTTPException(status_code=400, detail="Midjourney 速度仅支持 relax、fast 或 turbo。")
    size_value = str(parameters.get("size") or size or "1:1").strip()
    if not re.fullmatch(r"\d{1,2}:\d{1,2}", size_value):
        size_value = str(parameters.get("aspect_ratio") or "1:1").strip()
    if not re.fullmatch(r"\d{1,2}:\d{1,2}", size_value):
        size_value = "1:1"
    prompt_value = str(prompt or "").strip()
    body = {"speed": speed, "metadata": {"source": "infinite-canvas"}}
    if action == "imagine":
        if not prompt_value:
            raise HTTPException(status_code=400, detail="Midjourney 文生图需要提示词。")
        body.update({
            "prompt": prompt_value,
            "size": size_value,
            "version": str(parameters.get("version") or "6.1").strip()[:24],
        })
        if image_urls:
            body["image_urls"] = image_urls
        path = "/v1/midjourney/generations"
    elif action == "blend":
        if not 2 <= len(image_urls) <= 4:
            raise HTTPException(status_code=400, detail="Midjourney 多图融合需要连接 2 到 4 张图片。")
        body.update({"image_urls": image_urls, "size": size_value})
        path = "/v1/midjourney/generations/blend"
    elif action == "edits":
        if not prompt_value:
            raise HTTPException(status_code=400, detail="Midjourney 图片编辑需要提示词。")
        if not image_urls:
            raise HTTPException(status_code=400, detail="Midjourney 图片编辑需要连接至少一张图片。")
        body.update({"prompt": prompt_value, "image_urls": image_urls, "size": size_value})
        path = "/v1/midjourney/generations/edits"
    elif action == "modal":
        task_id = str(parameters.get("upstream_task_id") or "").strip()
        if not task_id:
            raise HTTPException(status_code=400, detail="Midjourney 局部重绘需要上游任务 ID。")
        mask_ref = next((ref for ref in (reference_images or []) if str(ref.get("role") or "").strip().lower() == "mask"), None)
        mask_url = await midjourney_modal_mask_url(mask_ref)
        if not mask_url:
            raise HTTPException(status_code=400, detail="Midjourney 局部重绘需要连接一个遮罩图片节点。")
        body.update({"task_id": task_id, "prompt": prompt_value, "mask_url": mask_url})
        path = "/v1/midjourney/generations/modal"
    else:
        task_id = str(parameters.get("upstream_task_id") or "").strip()
        if not task_id:
            raise HTTPException(status_code=400, detail=f"Midjourney {action} 操作需要上游任务 ID。")
        body["task_id"] = task_id
        custom_id = str(parameters.get("custom_id") or "").strip()
        if custom_id:
            body["custom_id"] = custom_id
        if action in {"upscale", "variation", "low_variation", "high_variation", "remix_subtle", "remix_strong"} and not custom_id:
            index = int(parameters.get("index") or 0)
            if index not in {1, 2, 3, 4}:
                raise HTTPException(status_code=400, detail="Midjourney 图片序号应为 1 到 4。")
            body["index"] = index
        if action == "zoom":
            zoom_ratio = float(parameters.get("zoom_ratio") or 0)
            if zoom_ratio <= 1 or zoom_ratio > 4:
                raise HTTPException(status_code=400, detail="Midjourney 缩放比例应大于 1 且不超过 4。")
            body["zoom_ratio"] = zoom_ratio
        if action == "pan":
            direction = str(parameters.get("direction") or "").strip().lower()
            if direction not in {"left", "right", "up", "down"}:
                raise HTTPException(status_code=400, detail="Midjourney 平移方向仅支持 left、right、up 或 down。")
            body["direction"] = direction
        if action in {"remix_subtle", "remix_strong"} and prompt_value:
            body["prompt"] = prompt_value
        path = MIDJOURNEY_ACTION_PATHS.get(action)
        if not path:
            raise HTTPException(status_code=400, detail=f"不支持的 Midjourney 操作：{action}")
    raw, task_id = await apimart_midjourney_request(provider, path, body)
    result = await midjourney_result(provider, task_id)
    if result.get("status") != "succeeded" or not result.get("images"):
        raise HTTPException(status_code=502, detail=result.get("error") or "Midjourney 没有返回图片结果。")
    first_url = result["images"][0]
    return {"type": "url", "value": first_url}, {**result, "submit": raw, "task_id": task_id}

async def generate_laohu_minimax_h3(payload, provider, capability_parameters):
    from laohu_protocols import minimax_h3_body
    base = laohu_api_base_url(provider)
    async with httpx.AsyncClient(timeout=VIDEO_POLL_TIMEOUT) as client:
        images = [{"url": await ai_money_upload_reference(client, provider, ref.url, "image"), "role": ref.role} for ref in payload.images]
        videos = [await ai_money_upload_reference(client, provider, url, "video") for url in payload.videos]
        audios = [await ai_money_upload_reference(client, provider, url, "audio") for url in payload.audios]
        body = minimax_h3_body(payload.prompt, images, videos, audios, capability_parameters)
        response = await client.post(f"{base}/v2/video_generation", headers=api_headers(provider=provider), json=body)
        # 受理不确定时只查询 X-Task-Id，不能重发付费创建。
        task_id = response.headers.get("X-Task-Id", "")
        if response.is_success:
            task_id = response.json().get("task_id") or task_id
        elif not task_id:
            response.raise_for_status()
        if not task_id:
            raise HTTPException(502, "MiniMax-H3 未返回任务编号；请核实平台任务后再操作")
        deadline = time.monotonic() + 1800
        delay = 5
        while time.monotonic() < deadline:
            await asyncio.sleep(delay)
            try:
                result = await client.get(f"{base}/v2/query/video_generation/{task_id}", headers=api_headers(provider=provider))
            except httpx.RequestError:
                delay = min(delay * 2, 60)
                continue
            if result.status_code == 429 or result.status_code >= 500:
                delay = min(delay * 2, 60)
                continue
            result.raise_for_status()
            raw = result.json()
            task = raw.get("task") or {}
            status = task.get("status")
            delay = 5
            if status == "succeeded":
                url = (task.get("content") or {}).get("url")
                if not url:
                    raise HTTPException(502, f"MiniMax-H3 任务 {task_id} 成功但缺少视频地址")
                return {"videos":[await save_remote_video_to_output(url, prefix="laohu_minimax_h3_")], "task_id":task_id, "raw":raw}
            if status in {"failed", "cancelled"}:
                raise HTTPException(502, f"MiniMax-H3 任务 {task_id} {status}：{task.get('error') or ''}")
        raise HTTPException(504, f"本地等待超时，上游可能继续；MiniMax-H3 任务编号：{task_id}")

async def generate_ai_money_video(payload, provider, capability_parameters=None):
    if payload.model == "MiniMax-H3":
        return await generate_laohu_minimax_h3(payload, provider, capability_parameters)
    base_url = laohu_api_base_url(provider)
    async with httpx.AsyncClient(timeout=VIDEO_POLL_TIMEOUT) as client:
        if str(payload.model or "").strip().lower() in {"fashvsr_video_upscale", "fashvsr-video-upscale", "flashvsr_video_upscale", "vosr2-video-upscale"}:
            if len(payload.videos or []) != 1:
                raise HTTPException(status_code=400, detail="FashVSR 视频放大需要且只能连接一个输入视频。")
            if payload.images or payload.audios:
                raise HTTPException(status_code=400, detail="FashVSR 视频放大只接受视频输入，不接受图片或音频。")
            uploaded_video = await ai_money_upload_reference(client, provider, payload.videos[0], "video")
            body = ai_money_fashvsr_request_body(payload.model, uploaded_video)
            submit_url = f"{base_url}/v1/video/generations"
            response = await client.post(
                submit_url,
                headers=api_headers(provider=provider, model=body["model"]),
                json=body,
            )
            response.raise_for_status()
            raw = response.json()
            task_id = extract_task_id(raw)
            if not task_id and isinstance(raw, dict):
                data = raw.get("data") if isinstance(raw.get("data"), dict) else {}
                task_id = data.get("id") or raw.get("id") or raw.get("task_id")
            result = raw if video_output_urls(raw) else await wait_for_video_task(client, provider, str(task_id), submit_url) if task_id else raw
            urls = video_output_urls(result)
            if not urls:
                raise HTTPException(status_code=502, detail=f"laohu FashVSR 成功但没有返回视频：{result}")
            return {"videos": [await save_remote_video_to_output(url, prefix="ai_money_fashvsr_") for url in urls], "task_id": task_id, "raw": result}
        image_urls = []
        for ref in (payload.images or [])[:10]:
            image_urls.append(await ai_money_upload_reference(client, provider, getattr(ref, "url", ""), "image"))
        video_urls = []
        for ref in (payload.videos or [])[:5]:
            video_urls.append(await ai_money_upload_reference(client, provider, ref, "video"))
        audio_urls = []
        for ref in (payload.audios or [])[:5]:
            audio_urls.append(await ai_money_upload_reference(client, provider, ref, "audio"))
        body = ai_money_video_request_body(
            model=payload.model,
            prompt=payload.prompt,
            seconds=payload.duration,
            aspect_ratio=payload.aspect_ratio,
            resolution=payload.resolution,
            image_urls=image_urls,
            video_urls=video_urls,
            audio_urls=audio_urls,
            generate_audio=payload.generate_audio,
            return_last_frame=payload.return_last_frame,
            seed=payload.seed,
            capability_parameters=capability_parameters,
        )
        submit_endpoint = "/v1/video/generations" if str(payload.model or "").strip().lower() == "animate-motion-transfer" else "/v1/videos"
        response = await client.post(
            f"{base_url}{submit_endpoint}",
            headers=api_headers(provider=provider, model=body["model"]),
            json=body,
        )
        response.raise_for_status()
        raw = response.json()
        task_id = extract_task_id(raw)
        if not task_id and isinstance(raw, dict):
            data = raw.get("data") if isinstance(raw.get("data"), dict) else {}
            task_id = data.get("id") or raw.get("id") or raw.get("task_id")
        result = raw if video_output_urls(raw) else await wait_for_video_task(client, provider, str(task_id), f"{base_url}/v1/videos") if task_id else raw
        urls = video_output_urls(result)
        if not urls:
            raise HTTPException(status_code=502, detail=f"laohu 视频生成成功但没有返回视频：{result}")
        return {"videos": [await save_remote_video_to_output(url, prefix="ai_money_video_") for url in urls], "task_id": task_id, "raw": result}

def image_task_data(payload):
    if isinstance(payload, dict) and isinstance(payload.get("data"), dict):
        return payload["data"]
    return payload if isinstance(payload, dict) else {}

def image_task_status(payload):
    task_data = image_task_data(payload)
    return str(task_data.get("status") or task_data.get("task_status") or "").upper()

def image_task_fail_reason(payload):
    task_data = image_task_data(payload)
    error = task_data.get("error") if isinstance(task_data.get("error"), dict) else {}
    return task_data.get("fail_reason") or task_data.get("message") or error.get("message") or (payload.get("message") if isinstance(payload, dict) else "") or "生图任务失败"


async def fetch_image_task_payload(client, task_id, provider=None):
    task_url = image_task_url_for_provider(provider, task_id)
    response = await httpx_request_with_transient_retries(
        client,
        "GET",
        task_url,
        attempts=3,
        headers=api_headers(provider=provider),
    )
    response.raise_for_status()
    return response.json()

async def wait_for_image_task(client, task_id, provider=None):
    is_apimart = is_apimart_provider(provider)
    is_tudou_async = is_tudou_async_image_mode(provider)
    timeout = TUDOU_ASYNC_IMAGE_TASK_TIMEOUT if is_tudou_async else APIMART_IMAGE_TASK_TIMEOUT if is_apimart else IMAGE_TASK_TIMEOUT
    interval = TUDOU_ASYNC_IMAGE_POLL_INTERVAL if is_tudou_async else APIMART_IMAGE_POLL_INTERVAL if is_apimart else IMAGE_POLL_INTERVAL
    initial_delay = TUDOU_ASYNC_IMAGE_INITIAL_POLL_DELAY if is_tudou_async else APIMART_IMAGE_INITIAL_POLL_DELAY if is_apimart else 0
    deadline = time.monotonic() + timeout
    last_payload = {}
    while time.monotonic() < deadline:
        if initial_delay:
            await asyncio.sleep(min(initial_delay, max(0.0, deadline - time.monotonic())))
            initial_delay = 0
            if time.monotonic() >= deadline:
                break
        last_payload = await fetch_image_task_payload(client, task_id, provider)
        status = image_task_status(last_payload)
        if not status:
            try:
                if extract_image(last_payload):
                    return last_payload
            except HTTPException:
                pass
        if status in IMAGE_TASK_SUCCESS_STATUSES:
            return last_payload
        if status in IMAGE_TASK_FAILED_STATUSES:
            raise HTTPException(status_code=502, detail=f"生图任务失败：{image_task_fail_reason(last_payload)}")
        await asyncio.sleep(min(interval, max(0.0, deadline - time.monotonic())))
    raw_text = json.dumps(last_payload, ensure_ascii=False)[:800] if last_payload else ""
    extra = f"，最后响应：{raw_text}" if raw_text else ""
    raise HTTPException(status_code=504, detail=f"生图任务超时（已等待 {int(timeout)} 秒），task_id={task_id}{extra}")

def output_storage(category="output"):
    return (OUTPUT_INPUT_DIR, "input") if category == "input" else (OUTPUT_OUTPUT_DIR, "output")

def result_kind_for_filename(filename):
    kind = stored_media_kind(str(filename or ""))
    return kind if kind in {"image", "video", "audio", "text"} else "file"

def pending_result_path(filename):
    rel = str(filename or "").replace("\\", "/").lstrip("/")
    return os.path.join(OUTPUT_OUTPUT_DIR, ".pending", result_kind_for_filename(rel), rel)

def output_url_for(filename, category="output"):
    if category != "input" and os.path.abspath(OUTPUT_OUTPUT_DIR) == os.path.abspath(str(PROJECT_STORAGE.results_dir)):
        rel = str(filename or "").replace("\\", "/").lstrip("/")
        candidates = [
            pending_result_path(rel),
            os.path.join(OUTPUT_OUTPUT_DIR, rel),
            os.path.join(OUTPUT_OUTPUT_DIR, result_kind_for_filename(rel), rel),
        ]
        source = next((path for path in candidates if os.path.isfile(path)), "")
        if source:
            try:
                return PROJECT_STORAGE.store_result_file(source, os.path.basename(rel), move=True)["url"]
            except StorageError as exc:
                print(f"登记生成结果失败: {exc}")
        existing = next((
            item for item in PROJECT_STORAGE.list_results()
            if item.get("original_name") == os.path.basename(rel) or item.get("display_name") == os.path.basename(rel)
        ), None)
        if existing:
            return PROJECT_STORAGE.result_url(existing["id"])
    folder, subdir = output_storage(category)
    rel = str(filename or "").replace("\\", "/").lstrip("/")
    try:
        asset_rel = os.path.relpath(os.path.join(folder, rel), ASSETS_DIR).replace("\\", "/")
        if not asset_rel.startswith("../") and asset_rel != "..":
            return f"/assets/{urllib.parse.quote(asset_rel, safe='/')}"
    except Exception:
        pass
    kind = "upload" if category == "input" else "generated"
    return f"/api/storage-files/{kind}/{urllib.parse.quote(rel, safe='/')}"

def output_path_for(filename, category="output"):
    if category != "input" and os.path.abspath(OUTPUT_OUTPUT_DIR) == os.path.abspath(str(PROJECT_STORAGE.results_dir)):
        path = pending_result_path(filename)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        return path
    folder, _ = output_storage(category)
    path = os.path.join(folder, filename)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return path

def storage_kind_dir(kind):
    kind = str(kind or "").strip().lower()
    if kind == "upload":
        return os.path.abspath(OUTPUT_INPUT_DIR)
    if kind == "generated":
        return os.path.abspath(OUTPUT_OUTPUT_DIR)
    if kind == "local":
        return os.path.abspath(LOCAL_UPLOAD_DIR)
    raise HTTPException(status_code=404, detail="未知存储目录")

def storage_file_path(kind, rel):
    root = storage_kind_dir(kind)
    rel_path = str(rel or "").replace("\\", "/").lstrip("/")
    rel_path = os.path.normpath(rel_path).replace("\\", "/")
    if not rel_path or rel_path == "." or rel_path == ".." or rel_path.startswith("../") or os.path.isabs(rel_path):
        raise HTTPException(status_code=400, detail="非法文件路径")
    path = os.path.abspath(os.path.join(root, rel_path))
    try:
        if os.path.commonpath([root, path]) != root:
            raise HTTPException(status_code=400, detail="非法文件路径")
    except ValueError:
        raise HTTPException(status_code=400, detail="非法文件路径")
    return path if os.path.exists(path) else None

def output_file_from_url(url):
    if isinstance(url, dict):
        url = url.get("url", "")
    if not url:
        return None
    clean = urllib.parse.unquote(url.split("?", 1)[0]).replace("\\", "/")
    if clean.startswith("/api/materials/"):
        return str(PROJECT_STORAGE.material_path(clean.rsplit("/", 1)[-1]) or "") or None
    if clean.startswith("/api/results/"):
        return str(PROJECT_STORAGE.result_path(clean.rsplit("/", 1)[-1]) or "") or None
    if clean.startswith("/api/smart-canvas/director-reference/"):
        filename = clean.rsplit("/", 1)[-1]
        if filename != os.path.basename(filename):
            return None
        path = Path(PROJECT_STORAGE.root) / "cache" / "director-references" / filename
        return str(path) if path.is_file() else None
    if clean.startswith("/api/storage-files/"):
        rest = clean[len("/api/storage-files/"):].lstrip("/")
        kind, _, rel = rest.partition("/")
        return storage_file_path(kind, rel) if kind and rel else None
    if clean.startswith("/workflow-files/"):
        rel = clean[len("/workflow-files/"):].lstrip("/")
        if not rel or rel == ".." or rel.startswith("../") or os.path.isabs(rel):
            return None
        root = os.path.abspath(str(PROJECT_STORAGE.canvas_workflows_dir))
        path = os.path.abspath(os.path.join(root, rel))
        try:
            return path if os.path.commonpath([root, path]) == root and os.path.isfile(path) else None
        except ValueError:
            return None
    if not (clean.startswith("/output/") or clean.startswith("/assets/")):
        return None
    if clean.startswith("/assets/"):
        root = ASSETS_DIR
        rel = clean[len("/assets/"):]
    else:
        rel = clean[len("/output/"):]
    rel = rel.lstrip("/")
    if not rel:
        return None
    roots = [ASSETS_DIR] if clean.startswith("/assets/") else [OUTPUT_OUTPUT_DIR, OUTPUT_DIR]
    for root in roots:
        path = os.path.abspath(os.path.join(root, rel))
        output_root = os.path.abspath(root)
        if os.path.commonpath([output_root, path]) == output_root and os.path.exists(path):
            return path
    return None


LOCAL_MEDIA_ROUTE_PREFIXES = (
    "/api/materials/",
    "/api/results/",
    "/api/smart-canvas/director-reference/",
    "/api/storage-files/",
    "/workflow-files/",
    "/output/",
    "/assets/",
)


def _local_media_route(value):
    """提取项目内部媒体路由；不把公网 URL 误认成本地文件。"""
    if isinstance(value, dict):
        value = value.get("url", "")
    text = str(value or "").strip()
    if not text:
        return ""
    parsed = urllib.parse.urlsplit(text)
    if parsed.scheme in {"http", "https"}:
        host = (parsed.hostname or "").lower()
        is_loopback = host in {"localhost", "127.0.0.1", "::1"}
        if not is_loopback:
            return ""
        route = urllib.parse.unquote(parsed.path or "")
        return route if route.startswith(LOCAL_MEDIA_ROUTE_PREFIXES) else ""
    if parsed.scheme == "file":
        return ""
    clean = urllib.parse.unquote(text.split("?", 1)[0]).replace("\\", "/")
    return clean if clean.startswith(LOCAL_MEDIA_ROUTE_PREFIXES) else ""


def local_media_reference_path(value):
    """把画布媒体引用解析成真实绝对路径。

    画布保存的是 /api/results、/api/materials 等逻辑 URL；本地 CLI、图像处理
    和文件上传只能使用解析后的磁盘路径。该函数也兼容 file:// 和已有绝对路径，
    所有入口应优先复用它，不应自行判断 URL 前缀。
    """
    if isinstance(value, dict):
        value = value.get("url", "")
    text = str(value or "").strip()
    if not text:
        return None
    route = _local_media_route(text)
    if route:
        return output_file_from_url(route)
    if text.startswith("file://"):
        parsed = urllib.parse.urlsplit(text)
        path = urllib.parse.unquote(parsed.path or "")
        if os.name == "nt" and re.match(r"^/[A-Za-z]:/", path):
            path = path[1:]
        if os.path.isfile(path):
            return os.path.abspath(path)
        return None
    if text.startswith(("http://", "https://", "data:")):
        return None
    candidate = text if os.path.isabs(text) else os.path.join(BASE_DIR, text)
    return os.path.abspath(candidate) if os.path.isfile(candidate) else None


def is_local_media_reference(value):
    if _local_media_route(value):
        return True
    if isinstance(value, dict):
        value = value.get("url", "")
    text = str(value or "").strip()
    if text.startswith("file://"):
        return True
    if text.startswith(("http://", "https://", "data:")):
        return False
    return bool(text and (os.path.isabs(text) or not urllib.parse.urlsplit(text).scheme))

def image_has_alpha(img: Image.Image) -> bool:
    if img.mode in ("RGBA", "LA"):
        return True
    if img.mode == "P":
        return "transparency" in img.info
    return False

STORAGE_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".avif"}


def material_public_item(item):
    if not isinstance(item, dict):
        return {}
    value = dict(item)
    display_name = value.get("display_name") or value.get("original_name") or "素材"
    value["name"] = os.path.splitext(display_name)[0] if os.path.splitext(display_name)[1] else display_name
    value["extension"] = os.path.splitext(value.get("path") or value.get("original_name") or "")[1]
    value["filename"] = f"{value['name']}{value['extension']}" if value["extension"] else value["name"]
    value["file"] = value.get("id") or ""
    value["url"] = PROJECT_STORAGE.material_url(value.get("id") or "")
    path = PROJECT_STORAGE.material_path(value.get("id") or "")
    if path and value.get("kind") == "image":
        try:
            with Image.open(path) as image:
                value["natural_w"], value["natural_h"] = image.size
                value["width"], value["height"] = image.size
        except Exception:
            pass
    return value

def result_public_item(item):
    if not isinstance(item, dict):
        return {}
    value = dict(item)
    value["name"] = value.get("display_name") or value.get("original_name") or "生成结果"
    value["url"] = PROJECT_STORAGE.result_url(value.get("id") or "")
    path = PROJECT_STORAGE.result_path(value.get("id") or "")
    if path and value.get("kind") == "image":
        try:
            with Image.open(path) as image:
                value["natural_w"], value["natural_h"] = image.size
                value["width"], value["height"] = image.size
        except Exception:
            pass
    return value

def sync_material_display_name(material_id, name):
    url = PROJECT_STORAGE.material_url(material_id)
    changed = 0
    for path in [ASSET_LIBRARY_PATH, *glob.glob(os.path.join(CANVAS_DIR, "*.json"))]:
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8-sig") as handle:
                value = json.load(handle)
        except Exception:
            continue
        file_changed = 0
        def update(entry):
            nonlocal changed, file_changed
            if isinstance(entry, dict):
                if entry.get("material_id") == material_id or entry.get("url") == url:
                    key = "name" if "name" in entry or path == ASSET_LIBRARY_PATH else "display_name"
                    if entry.get(key) != name:
                        entry[key] = name
                        changed += 1
                        file_changed += 1
                for nested in entry.values():
                    update(nested)
            elif isinstance(entry, list):
                for nested in entry:
                    update(nested)
        update(value)
        if not file_changed:
            continue
        if path == ASSET_LIBRARY_PATH:
            atomic_write_json(path, value)
        elif isinstance(value, dict) and value.get("id"):
            save_canvas(value, touch_updated_at=False)
    return changed

