@app.get("/api/view")
def view_image(filename: str, type: str = "input", subfolder: str = ""):
    # 先按原逻辑去各 ComfyUI 后端找
    for addr in COMFYUI_INSTANCES:
        try:
            url = f"http://{addr}/view"
            params = {"filename": filename, "type": type, "subfolder": subfolder}
            r = requests.get(url, params=params, timeout=1)
            if r.status_code == 200:
                return Response(content=r.content, media_type=r.headers.get('Content-Type'))
        except Exception:
            continue
    # 后端都拿不到时回退本地 assets/<input|output>/
    # 适用场景：画布通过 /api/ai/upload 把参考图直接落到本地 assets/input/，
    # 但 ComfyUI 的 input 可能因为重启/清理而丢失，导致 enhance/klein 等页面预览对比图 404
    if not subfolder and type in ("input", "output"):
        safe_name = os.path.basename(filename or "")
        if safe_name:
            local_path = output_path_for(safe_name, "input" if type == "input" else "output")
            if os.path.isfile(local_path):
                return FileResponse(local_path, media_type=content_type_for_path(local_path))
    raise HTTPException(status_code=404, detail="Image not found on any available backend")

@app.get("/api/download-output")
def download_output(request: Request, url: str, name: str = "", inline: bool = False):
    url = rewrite_runninghub_file_url(url)
    path = output_file_from_url(url)
    if not path:
        path = local_media_file_by_basename(filename_from_media_url(url, ""))
    if path:
        filename = sanitize_export_filename(os.path.basename(name) if name else os.path.basename(path), os.path.basename(path))
        return FileResponse(path, media_type=content_type_for_path(path), filename=None if inline else filename)
    # 远程文件：流式代理，绝不把整段视频/大文件读进内存（否则多个视频同时代理会撑爆内存、拖垮单进程服务）。
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise HTTPException(status_code=400, detail="无效的下载地址")
    try:
        upstream_headers = {"User-Agent": "ComfyUI-API-Modelscope/1.0"}
        range_header = request.headers.get("range")
        if range_header:
            upstream_headers["Range"] = range_header
        upstream = requests.get(
            url, stream=True, timeout=(10, 60),
            headers=upstream_headers,
        )
        upstream.raise_for_status()
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"远程文件下载失败：{exc}")
    content_type = upstream.headers.get("content-type") or "application/octet-stream"
    fallback = filename_from_media_url(url, "download.bin")
    filename = sanitize_export_filename(os.path.basename(name) if name else fallback, fallback)
    disposition = "inline" if inline else "attachment"
    headers = {"Content-Disposition": f"{disposition}; filename*=UTF-8''{urllib.parse.quote(filename)}"}
    for key in ("content-range", "accept-ranges"):
        value = upstream.headers.get(key)
        if value:
            headers["-".join(part.capitalize() for part in key.split("-"))] = value

    def stream_remote():
        try:
            for chunk in upstream.iter_content(chunk_size=256 * 1024):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return StreamingResponse(stream_remote(), media_type=content_type, headers=headers, status_code=upstream.status_code)

def director_reference_cache_dir() -> Path:
    path = Path(PROJECT_STORAGE.root) / "cache" / "director-references"
    path.mkdir(parents=True, exist_ok=True)
    return path


def director_reference_source_digest(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def director_reference_duration_ms(path: str) -> int:
    ffprobe = shutil.which("ffprobe")
    if not ffprobe:
        raise HTTPException(status_code=500, detail="未找到 ffprobe，无法校验导演台视频时间范围")
    command = [
        ffprobe, "-v", "error", "-show_entries", "format=duration",
        "-of", "default=noprint_wrappers=1:nokey=1", path,
    ]
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError) as exc:
        raise HTTPException(status_code=500, detail=f"读取视频时长失败：{exc}")
    if result.returncode != 0:
        raise HTTPException(status_code=400, detail=(result.stderr or "无法读取视频时长").strip()[:300])
    try:
        duration_ms = round(float((result.stdout or "").strip()) * 1000)
    except (TypeError, ValueError):
        duration_ms = 0
    if duration_ms <= 0:
        raise HTTPException(status_code=400, detail="无法读取有效的视频时长")
    return duration_ms


def validate_director_reference_range(payload: DirectorReferenceRequest, duration_ms: int) -> tuple[int, int]:
    if payload.operation != "video_segment":
        if payload.start_ms is not None and payload.start_ms < 0:
            raise HTTPException(status_code=400, detail="时间不能为负数")
        if payload.end_ms is not None and payload.end_ms < 0:
            raise HTTPException(status_code=400, detail="时间不能为负数")
        return 0, duration_ms
    if payload.start_ms is None or payload.end_ms is None:
        raise HTTPException(status_code=400, detail="视频片段必须提供开始和结束时间")
    start_ms = int(payload.start_ms)
    end_ms = int(payload.end_ms)
    if start_ms < 0 or end_ms < 0:
        raise HTTPException(status_code=400, detail="时间不能为负数")
    if end_ms <= start_ms:
        raise HTTPException(status_code=400, detail="结束时间必须晚于开始时间")
    if start_ms >= duration_ms or end_ms > duration_ms:
        raise HTTPException(status_code=400, detail=f"请求时间范围超出源视频时长（{duration_ms}ms）")
    return start_ms, end_ms


def build_director_reference_file(source_path: str, target_path: str, payload: DirectorReferenceRequest, duration_ms: int) -> None:
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        raise HTTPException(status_code=500, detail="未找到 ffmpeg，无法生成导演台时间线引用")
    if payload.operation == "first_frame":
        command = [
            ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
            "-ss", "0", "-i", source_path, "-map", "0:v:0", "-frames:v", "1", target_path,
        ]
    elif payload.operation == "last_frame":
        seek_seconds = max(0, duration_ms - 50) / 1000
        command = [
            ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
            "-ss", f"{seek_seconds:.3f}", "-i", source_path, "-map", "0:v:0", "-frames:v", "1", target_path,
        ]
    else:
        start_ms, end_ms = validate_director_reference_range(payload, duration_ms)
        command = [
            ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
            "-ss", f"{start_ms / 1000:.3f}", "-t", f"{(end_ms - start_ms) / 1000:.3f}", "-i", source_path,
            "-map", "0:v:0", "-map", "0:a?", "-c:v", "libx264", "-preset", "veryfast",
            "-crf", "18", "-pix_fmt", "yuv420p", "-c:a", "aac", "-movflags", "+faststart", target_path,
        ]
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=300)
    except (OSError, subprocess.SubprocessError) as exc:
        raise HTTPException(status_code=500, detail=f"生成导演台引用失败：{exc}")
    if result.returncode != 0 or not os.path.isfile(target_path) or os.path.getsize(target_path) <= 0:
        try:
            os.remove(target_path)
        except OSError:
            pass
        raise HTTPException(status_code=500, detail=(result.stderr or "生成导演台引用失败").strip()[:300])


@app.post("/api/smart-canvas/director-reference")
async def create_director_reference(payload: DirectorReferenceRequest):
    source_path = local_media_reference_path(payload.source_url)
    if not source_path or not os.path.isfile(source_path):
        raise HTTPException(status_code=400, detail="导演台时间线引用只支持当前项目可访问的本地视频")
    if not content_type_for_path(source_path).startswith("video/"):
        raise HTTPException(status_code=400, detail="来源文件不是可识别的视频")
    duration_ms = director_reference_duration_ms(source_path)
    start_ms, end_ms = validate_director_reference_range(payload, duration_ms)
    digest = director_reference_source_digest(source_path)
    cache_source = f"{digest}:{payload.operation}:{start_ms}:{end_ms}".encode("utf-8")
    cache_key = hashlib.sha256(cache_source).hexdigest()
    suffix = ".mp4" if payload.operation == "video_segment" else ".png"
    filename = f"{cache_key}-{payload.operation}{suffix}"
    target_path = director_reference_cache_dir() / filename
    if not target_path.is_file() or target_path.stat().st_size <= 0:
        await asyncio.to_thread(build_director_reference_file, source_path, str(target_path), payload, duration_ms)
    return {
        "url": f"/api/smart-canvas/director-reference/{filename}",
        "kind": "video" if payload.operation == "video_segment" else "image",
        "operation": payload.operation,
        "start_ms": start_ms if payload.operation == "video_segment" else None,
        "end_ms": end_ms if payload.operation == "video_segment" else None,
        "duration_ms": end_ms - start_ms if payload.operation == "video_segment" else None,
        "cache_key": cache_key,
    }


@app.get("/api/smart-canvas/director-reference/{filename}")
async def read_director_reference(filename: str):
    safe_filename = os.path.basename(str(filename or ""))
    if not safe_filename or safe_filename != filename:
        raise HTTPException(status_code=400, detail="非法导演台引用路径")
    path = director_reference_cache_dir() / safe_filename
    if not path.is_file():
        raise HTTPException(status_code=404, detail="导演台引用不存在或已清理，可重新运行连接 Clip 生成")
    return FileResponse(path, media_type=content_type_for_path(str(path)))


def director_export_project_name(value: str) -> str:
    name = re.sub(r'[\\/:*?"<>|\x00-\x1f]+', "_", str(value or "").strip()).strip(" ._")
    return (name or "导演台工程")[:120]


def director_export_sort_key(clip: DirectorExportClip):
    start_ms = max(0, int(clip.start_ms or 0))
    duration_ms = max(1, int(clip.duration_ms or 1))
    return (start_ms + duration_ms / 2, start_ms, int(clip.created_at or 0), str(clip.id))


@app.post("/api/smart-canvas/director-export")
async def export_director_clips(payload: DirectorExportRequest):
    if not payload.clips:
        raise HTTPException(status_code=400, detail="导演台还没有可导出的 Clip")
    ordered = sorted(payload.clips, key=director_export_sort_key)
    missing = [clip.id for clip in ordered if not str(clip.url or "").strip()]
    if missing:
        raise HTTPException(status_code=400, detail=f"以下 Clip 还没有生成结果：{', '.join(missing[:8])}")
    sources = []
    for clip in ordered:
        path = local_media_reference_path(clip.url)
        if not path or not os.path.isfile(path):
            raise HTTPException(status_code=400, detail=f"Clip {clip.id} 不是当前项目可访问的本地结果，无法打包")
        if not content_type_for_path(path).startswith("video/"):
            raise HTTPException(status_code=400, detail=f"Clip {clip.id} 的结果不是视频")
        sources.append(path)
    project_name = director_export_project_name(payload.project_name)
    archive_name = f"{project_name}-clips-{uuid.uuid4().hex[:8]}.zip"
    archive_path = output_path_for(archive_name, "output")
    manifest_clips = []
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for index, (clip, source_path) in enumerate(zip(ordered, sources), start=1):
            suffix = Path(source_path).suffix.lower()
            if suffix not in {".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv"}:
                suffix = ".mp4"
            filename = f"{project_name}-clip-{index:03d}{suffix}"
            archive.write(source_path, filename)
            start_ms = max(0, int(clip.start_ms or 0))
            duration_ms = max(1, int(clip.duration_ms or 1))
            manifest_clips.append({
                "clip_id":clip.id,
                "type":clip.type,
                "start_ms":start_ms,
                "end_ms":start_ms + duration_ms,
                "midpoint_ms":start_ms + duration_ms / 2,
                "duration_ms":duration_ms,
                "result_id":clip.result_id,
                "filename":filename,
            })
        manifest = {"version":1, "project_name":payload.project_name, "export_name":project_name, "clips":manifest_clips}
        archive.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
    return {"url":output_url_for(archive_name, "output"), "name":archive_name, "kind":"file", "clips":manifest_clips}


@app.post("/api/smart-canvas/minimax-export")
async def export_minimax_timeline(payload: MiniMaxTimelineExportRequest):
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        raise HTTPException(status_code=500, detail="未找到 ffmpeg，无法导出完整剪辑")
    clips = [clip for clip in (payload.clips or []) if clip.url]
    if not clips:
        raise HTTPException(status_code=400, detail="时间轴里还没有可导出的视频")
    tmpdir = tempfile.mkdtemp(prefix="minimax_timeline_")
    try:
        clip_sources = []
        for clip in clips:
            src = output_file_from_url(clip.url)
            if not src:
                raise HTTPException(status_code=400, detail="完整剪辑导出只支持本地生成素材")
            clip_sources.append(src)
        ffprobe = shutil.which("ffprobe")
        preserve_audio = bool(ffprobe)
        if ffprobe:
            for src in clip_sources:
                probe_cmd = [
                    ffprobe, "-v", "error", "-select_streams", "a:0",
                    "-show_entries", "stream=index", "-of", "csv=p=0", src,
                ]
                probe = await asyncio.to_thread(subprocess.run, probe_cmd, capture_output=True, text=True, timeout=30)
                if probe.returncode != 0 or not (probe.stdout or "").strip():
                    preserve_audio = False
                    break
        part_paths = []
        normalize_video = "scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30"
        for index, (clip, src) in enumerate(zip(clips, clip_sources)):
            start = max(0.0, float(clip.start or 0))
            end = float(clip.end or 0)
            source_duration = max(0.0, float(clip.duration or 0))
            if end <= start:
                end = source_duration if source_duration > start else start + 0.1
            trim_duration = max(0.1, end - start)
            part_path = os.path.join(tmpdir, f"part_{index:03d}.mp4")
            if preserve_audio:
                cmd = [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-ss", f"{start:.3f}", "-t", f"{trim_duration:.3f}", "-i", src,
                    "-map", "0:v:0", "-map", "0:a:0", "-vf", normalize_video,
                    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-ar", "48000", "-ac", "2",
                    "-movflags", "+faststart", part_path,
                ]
            else:
                cmd = [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-ss", f"{start:.3f}", "-t", f"{trim_duration:.3f}", "-i", src,
                    "-f", "lavfi", "-t", f"{trim_duration:.3f}", "-i", "anullsrc=channel_layout=stereo:sample_rate=48000",
                    "-map", "0:v:0", "-map", "1:a:0", "-vf", normalize_video, "-shortest",
                    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-ar", "48000", "-ac", "2",
                    "-movflags", "+faststart", part_path,
                ]
            proc = await asyncio.to_thread(subprocess.run, cmd, capture_output=True, text=True, timeout=300)
            if proc.returncode != 0:
                raise HTTPException(status_code=500, detail=(proc.stderr or "视频裁剪失败").strip()[:300])
            part_paths.append(part_path)
        filename = sanitize_export_filename(payload.filename or "minimax-timeline.mp4", "minimax-timeline.mp4")
        if not filename.lower().endswith(".mp4"):
            filename += ".mp4"
        output_path = output_path_for(filename, "output")
        if len(part_paths) == 1:
            shutil.copyfile(part_paths[0], output_path)
        else:
            concat_path = os.path.join(tmpdir, "concat.txt")
            with open(concat_path, "w", encoding="utf-8") as fh:
                for part in part_paths:
                    safe_part = part.replace("\\", "/").replace("'", "'\\''")
                    fh.write(f"file '{safe_part}'\n")
            cmd = [
                ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                "-f", "concat", "-safe", "0", "-i", concat_path,
                "-c", "copy", "-movflags", "+faststart", output_path,
            ]
            proc = await asyncio.to_thread(subprocess.run, cmd, capture_output=True, text=True, timeout=300)
            if proc.returncode != 0:
                raise HTTPException(status_code=500, detail=(proc.stderr or "视频拼接失败").strip()[:300])
        return {"url": output_url_for(filename, "output"), "name": filename, "kind": "video"}
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

@app.post("/api/upload")
async def upload_image(files: List[UploadFile] = File(...)):
    uploaded_files = []
    files_content = []
    for file in files:
        content = await file.read()
        files_content.append((file, content))

    for file, content in files_content:
        success_count = 0
        last_result = None
        for addr in COMFYUI_INSTANCES:
            try:
                files_data = {'image': (file.filename, content, file.content_type)}
                response = requests.post(f"http://{addr}/upload/image", files=files_data, timeout=5)
                if response.status_code == 200:
                    last_result = response.json()
                    success_count += 1
            except Exception as e:
                print(f"Upload error for {addr}: {e}")

        if success_count > 0 and last_result:
            uploaded_files.append({"comfy_name": last_result.get("name", file.filename)})
        else:
            raise HTTPException(status_code=500, detail="Failed to upload to any backend")

    return {"files": uploaded_files}

@app.post("/api/ai/upload")
async def upload_ai_reference(files: List[UploadFile] = File(...)):
    uploaded = []
    image_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    doc_exts = {".pdf", ".txt", ".md", ".markdown", ".doc", ".docx", ".xls", ".xlsx", ".csv", ".json", ".zip", ".yaml", ".yml", ".log"}
    max_upload_bytes = 50 * 1024 * 1024
    for file in files:
        content = await file.read()
        if not content:
            continue
        if len(content) > max_upload_bytes:
            raise HTTPException(status_code=413, detail=f"{file.filename or '文件'} 超过 50MB，无法上传")
        ext = os.path.splitext(file.filename or "")[1].lower()
        content_type = (file.content_type or "").lower()
        kind = "image"
        if ext in video_exts or content_type.startswith("video/"):
            kind = "video"
            if ext not in video_exts:
                ext = ".webm" if "webm" in content_type else ".mov" if "quicktime" in content_type else ".mp4"
        elif ext in audio_exts or content_type.startswith("audio/"):
            kind = "audio"
            if ext not in audio_exts:
                ext = ".wav" if "wav" in content_type else ".ogg" if "ogg" in content_type else ".m4a" if "mp4" in content_type else ".mp3"
        elif ext in image_exts or content_type.startswith("image/"):
            kind = "image"
            if ext not in image_exts:
                ext = ".jpg" if "jpeg" in content_type else ".webp" if "webp" in content_type else ".gif" if "gif" in content_type else ".png"
        elif ext in doc_exts or content_type.startswith(("text/", "application/")):
            kind = "file"
            if not ext:
                ext = mimetypes.guess_extension(content_type) or ".bin"
        else:
            kind = "file"
            if not ext:
                ext = ".bin"
        try:
            item = PROJECT_STORAGE.store_material_bytes(
                content,
                file.filename or f"素材{ext}",
                scope="temporary",
                content_type=content_type,
            )
        except StorageError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        uploaded.append({
            "url": item["url"],
            "name": item["display_name"],
            "kind": item["kind"] if item["kind"] != "file" else kind,
            "mime": item["mime"],
            "material_id": item["id"],
            "deduplicated": True,
        })
    return {"files": uploaded}

class Base64UploadRequest(BaseModel):
    data: str = ""            # 纯 base64 或 data:URL
    name: str = ""
    content_type: str = ""

@app.post("/api/ai/upload-base64")
async def upload_ai_base64(payload: Base64UploadRequest):
    """以 base64 JSON 方式上传字节到 assets/input，返回 /assets 地址。
    给不便用 multipart/FormData 的客户端（如 PS UXP 面板）用——UXP 的 fetch+FormData 经常发不出有效 multipart。"""
    raw = (payload.data or "").strip()
    ct = (payload.content_type or "").split(";", 1)[0].strip().lower()
    if raw.startswith("data:"):
        header, _, raw = raw.partition(",")
        if not ct:
            ct = header[5:].split(";", 1)[0].strip().lower()
    try:
        content = base64.b64decode(raw, validate=False)
    except Exception:
        raise HTTPException(status_code=400, detail="数据无法解码")
    if not content:
        raise HTTPException(status_code=400, detail="内容为空")
    if len(content) > 50 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="超过 50MB")
    kind, ext = _local_upload_kind_ext(payload.name or "", ct or "image/png")
    if kind is None:
        kind, ext = "image", ".png"
    try:
        item = PROJECT_STORAGE.store_material_bytes(
            content,
            payload.name or f"素材{ext}",
            scope="temporary",
            content_type=ct,
        )
    except StorageError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"files": [{
        "url": item["url"],
        "name": item["display_name"],
        "kind": item["kind"] if item["kind"] != "file" else kind,
        "material_id": item["id"],
        "deduplicated": True,
    }]}

@app.post("/api/comfyui/upload-base64")
async def upload_comfyui_base64(payload: Base64UploadRequest):
    """base64 方式把图片传到 ComfyUI 各后端的 input 目录，返回 comfy 用文件名（供 UXP 做 ComfyUI 图生图）。"""
    raw = (payload.data or "").strip()
    ct = (payload.content_type or "").split(";", 1)[0].strip().lower()
    if raw.startswith("data:"):
        header, _, raw = raw.partition(",")
        if not ct:
            ct = header[5:].split(";", 1)[0].strip().lower()
    try:
        content = base64.b64decode(raw, validate=False)
    except Exception:
        raise HTTPException(status_code=400, detail="数据无法解码")
    if not content:
        raise HTTPException(status_code=400, detail="内容为空")
    _, ext = _local_upload_kind_ext(payload.name or "", ct or "image/png")
    filename = f"dx_{uuid.uuid4().hex[:12]}{ext or '.png'}"
    comfy_name = None
    for addr in COMFYUI_INSTANCES:
        try:
            resp = requests.post(f"http://{addr}/upload/image",
                                 files={'image': (filename, content, ct or 'image/png')}, timeout=10)
            if resp.status_code == 200:
                comfy_name = resp.json().get("name", filename)
        except Exception as exc:
            print(f"ComfyUI base64 upload error for {addr}: {exc}")
    if not comfy_name:
        raise HTTPException(status_code=502, detail="上传到 ComfyUI 失败")
    return {"name": comfy_name}

def _local_upload_kind_ext(filename, content_type):
    image_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    ext = os.path.splitext(filename or "")[1].lower()
    ct = (content_type or "").lower()
    if ext in video_exts or ct.startswith("video/"):
        if ext not in video_exts:
            ext = ".webm" if "webm" in ct else ".mov" if "quicktime" in ct else ".mp4"
        return "video", ext
    if ext in audio_exts or ct.startswith("audio/"):
        if ext not in audio_exts:
            ext = ".wav" if "wav" in ct else ".ogg" if "ogg" in ct else ".m4a" if "mp4" in ct else ".mp3"
        return "audio", ext
    if ext in image_exts or ct.startswith("image/"):
        if ext not in image_exts:
            ext = ".jpg" if "jpeg" in ct else ".webp" if "webp" in ct else ".gif" if "gif" in ct else ".png"
        return "image", ext
    return None, ext

def _local_upload_display_name(filename):
    # 文件名形如 up_<hex>_<原始名>；去掉前缀还原展示名
    base = os.path.basename(str(filename or ""))
    m = re.match(r"^up_[0-9a-f]{12}_(.+)$", base)
    return m.group(1) if m else base

def _local_upload_rel_path(value):
    text = str(value or "").replace("\\", "/").strip().lstrip("/")
    if not text:
        return ""
    norm = os.path.normpath(text).replace("\\", "/")
    if norm in {".", ""}:
        return ""
    if norm.startswith("../") or norm == ".." or os.path.isabs(norm):
        raise HTTPException(status_code=400, detail="非法路径")
    return norm

def _local_upload_abs(rel):
    rel_path = _local_upload_rel_path(rel)
    path = os.path.abspath(os.path.join(LOCAL_UPLOAD_DIR, rel_path))
    root = os.path.abspath(LOCAL_UPLOAD_DIR)
    try:
        common = os.path.commonpath([root, path])
    except ValueError:
        raise HTTPException(status_code=400, detail="非法路径")
    if common != root:
        raise HTTPException(status_code=400, detail="非法路径")
    return rel_path, path

def _local_upload_safe_path(name):
    filename, path = _local_upload_abs(name)
    if not filename:
        raise HTTPException(status_code=400, detail="文件名不能为空")
    return filename, path

def _local_upload_safe_folder(path_value):
    rel, path = _local_upload_abs(path_value)
    return rel, path

def _local_upload_safe_folder_name(name):
    cleaned = sanitize_asset_name(os.path.basename(str(name or "").strip()), "")
    cleaned = re.sub(r"[\\/]+", "_", cleaned).strip(" ._")
    if not cleaned:
        raise HTTPException(status_code=400, detail="文件夹名称不能为空")
    return cleaned[:60]

def _local_upload_safe_file_stem(name):
    raw = os.path.splitext(os.path.basename(str(name or "").strip()))[0]
    cleaned = sanitize_asset_name(raw, "")
    cleaned = re.sub(r"[\\/]+", "_", cleaned).strip(" ._")
    if not cleaned:
        raise HTTPException(status_code=400, detail="文件名称不能为空")
    return cleaned[:120]

def _local_upload_caption_path(filename):
    return os.path.splitext(os.path.join(LOCAL_UPLOAD_DIR, filename))[0] + ".txt"

def _read_local_upload_caption(filename):
    caption_path = _local_upload_caption_path(filename)
    if not os.path.isfile(caption_path):
        return "", ""
    try:
        with open(caption_path, "r", encoding="utf-8-sig") as f:
            text = f.read()
    except UnicodeDecodeError:
        with open(caption_path, "r", encoding="gb18030", errors="replace") as f:
            text = f.read()
    except OSError:
        return "", ""
    return text, os.path.basename(caption_path)

def _local_upload_item(filename):
    path = os.path.join(LOCAL_UPLOAD_DIR, filename)
    rel = _local_upload_rel_path(filename)
    try:
        stat = os.stat(path)
        size = stat.st_size
        created_at = stat.st_mtime
    except OSError:
        size = 0
        created_at = 0
    kind, _ = _local_upload_kind_ext(filename, "")
    item = {
        "id": rel,
        "file": rel,
        "name": _local_upload_display_name(rel),
        "url": f"/api/storage-files/local/{urllib.parse.quote(rel, safe='/')}",
        "kind": kind or "image",
        "size": size,
        "created_at": created_at,
        "folder": os.path.dirname(rel).replace("\\", "/"),
    }
    if kind == "image":
        try:
            with Image.open(path) as img:
                item["natural_w"], item["natural_h"] = img.size
                item["width"], item["height"] = img.size
        except Exception:
            pass
        caption, caption_file = _read_local_upload_caption(filename)
        item["caption"] = caption
        item["caption_file"] = caption_file
        classification = _read_local_upload_classification(filename)
        if classification:
            item["classification"] = classification
    return item

def _local_upload_folder_node(path="", name="全部上传"):
    rel = _local_upload_rel_path(path)
    return {
        "id": rel or "__root__",
        "path": rel,
        "name": name if not rel else os.path.basename(rel),
        "items": [],
        "children": [],
    }

def _local_upload_tree_and_items():
    root_node = _local_upload_folder_node("", "全部上传")
    folder_map = {"": root_node}
    items = []
    for current, dirs, files in os.walk(LOCAL_UPLOAD_DIR):
        dirs[:] = sorted([d for d in dirs if not d.startswith(".") and not d.startswith("._")], key=str.lower)
        rel_dir = os.path.relpath(current, LOCAL_UPLOAD_DIR).replace("\\", "/")
        if rel_dir == ".":
            rel_dir = ""
        node = folder_map.get(rel_dir)
        if node is None:
            node = _local_upload_folder_node(rel_dir)
            folder_map[rel_dir] = node
        for dirname in dirs:
            child_rel = f"{rel_dir}/{dirname}".lstrip("/")
            child = _local_upload_folder_node(child_rel)
            folder_map[child_rel] = child
            node["children"].append(child)
        for name in sorted(files, key=str.lower):
            if name.startswith(".") or name.startswith("._"):
                continue
            rel_file = f"{rel_dir}/{name}".lstrip("/")
            kind, _ = _local_upload_kind_ext(name, "")
            if kind is None:
                continue
            item = _local_upload_item(rel_file)
            node["items"].append(item)
            items.append(item)
    def fill_counts(node):
        total = len(node.get("items") or [])
        for child in node.get("children") or []:
            total += fill_counts(child)
        node["count"] = total
        return total
    fill_counts(root_node)
    items.sort(key=lambda it: it.get("created_at") or 0, reverse=True)
    return root_node, items

def temporary_material_tree_and_items():
    records = PROJECT_STORAGE.list_materials("temporary")
    items = [material_public_item(record) for record in records]
    root = {"id": "__root__", "path": "", "name": "临时素材", "items": [], "children": []}
    folders = {"": root}
    for item in items:
        folder = str(item.get("folder") or "").strip("/\\")
        parent = root
        current = ""
        for part in [value for value in folder.replace("\\", "/").split("/") if value]:
            current = f"{current}/{part}".lstrip("/")
            if current not in folders:
                node = {"id": current, "path": current, "name": part, "items": [], "children": []}
                folders[current] = node
                parent["children"].append(node)
            parent = folders[current]
        parent["items"].append(item)
    def count(node):
        total = len(node["items"])
        for child in node["children"]:
            total += count(child)
        node["count"] = total
        return total
    count(root)
    return root, items

_DOUBLE_EXT_RE = re.compile(r'(\.[A-Za-z0-9]{1,5})\1$', re.IGNORECASE)
_DOUBLE_EXT_MEDIA = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".avif",
                     ".mp4", ".webm", ".mov", ".m4v", ".flv"}

def migrate_double_extension_uploads():
    """修复历史遗留的双重扩展名（如 foo.png.png）：去掉重复的一层，并同步重命名 caption/classification 旁车文件。
    旧版 URL 导入会把自带扩展名的 entry.name 又拼一次 ext，导致文件名重复后缀、URL 对不上而无法显示。"""
    if not os.path.isdir(LOCAL_UPLOAD_DIR):
        return
    renamed = 0
    for current, _dirs, files in os.walk(LOCAL_UPLOAD_DIR):
        for name in files:
            m = _DOUBLE_EXT_RE.search(name)
            if not m or m.group(1).lower() not in _DOUBLE_EXT_MEDIA:
                continue
            old_path = os.path.join(current, name)
            new_path = os.path.join(current, name[:-len(m.group(1))])  # 去掉末尾重复的一层扩展名
            if os.path.exists(new_path):
                continue
            try:
                os.rename(old_path, new_path)
            except OSError:
                continue
            renamed += 1
            # caption/classification 旁车以「去掉一层扩展名」为基名，需同步改名以保留标注
            old_base = os.path.splitext(old_path)[0]
            new_base = os.path.splitext(new_path)[0]
            for suffix in (".classification.json", ".txt"):
                src_side, dst_side = old_base + suffix, new_base + suffix
                if os.path.exists(src_side) and not os.path.exists(dst_side):
                    try:
                        os.rename(src_side, dst_side)
                    except OSError:
                        pass
    if renamed:
        print(f"修复双重扩展名素材: {renamed} 个")

def _sniff_image_ext_bytes(head):
    """按文件头魔数判断真实图片格式，返回规范扩展名（含点），无法识别返回 None。"""
    head = head or b""
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return ".png"
    if head.startswith(b"\xff\xd8\xff"):
        return ".jpg"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return ".webp"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return ".gif"
    if head[:2] == b"BM":
        return ".bmp"
    return None

def _sniff_image_ext(path):
    try:
        with open(path, "rb") as f:
            return _sniff_image_ext_bytes(f.read(16))
    except OSError:
        return None

def migrate_mislabeled_image_extensions():
    """有些采集来的图片内容与扩展名不符（例如 WebP 内容却叫 .png），导致服务端按错误 content-type 返回、
    严格的客户端（PS UXP）解不出来。这里按真实魔数纠正扩展名，并同步重命名 caption/classification 旁车。"""
    if not os.path.isdir(LOCAL_UPLOAD_DIR):
        return
    img_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp"}
    fixed = 0
    for current, _dirs, files in os.walk(LOCAL_UPLOAD_DIR):
        for name in files:
            ext = os.path.splitext(name)[1].lower()
            if ext not in img_exts:
                continue
            path = os.path.join(current, name)
            real = _sniff_image_ext(path)
            if not real:
                continue
            # .jpg/.jpeg 视为同一种，不互相纠正
            if real == ext or (real == ".jpg" and ext == ".jpeg"):
                continue
            new_name = os.path.splitext(name)[0] + real
            new_path = os.path.join(current, new_name)
            if os.path.exists(new_path):
                continue
            try:
                os.rename(path, new_path)
            except OSError:
                continue
            fixed += 1
            old_base = os.path.splitext(path)[0]
            new_base = os.path.splitext(new_path)[0]
            for suffix in (".classification.json", ".txt"):
                src_side, dst_side = old_base + suffix, new_base + suffix
                if os.path.isfile(src_side) and not os.path.exists(dst_side):
                    try:
                        os.rename(src_side, dst_side)
                    except OSError:
                        pass
    if fixed:
        print(f"纠正图片扩展名(内容与后缀不符): {fixed} 个")

@app.post("/api/local-assets/upload")
async def upload_local_assets(files: List[UploadFile] = File(...), folder: str = Form("")):
    uploaded = []
    folder_rel = str(folder or "").strip("/\\")
    for file in files:
        content = await file.read()
        if not content:
            continue
        kind, ext = _local_upload_kind_ext(file.filename, file.content_type)
        if kind is None:
            continue
        try:
            record = PROJECT_STORAGE.store_material_bytes(
                content,
                file.filename or f"素材{ext}",
                scope="temporary",
                content_type=file.content_type or "",
                folder=folder_rel,
            )
        except StorageError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        uploaded.append(material_public_item(record))
    return {"files": uploaded}

@app.post("/api/local-assets/import-urls")
async def import_local_assets_from_urls(payload: LocalAssetUrlImportRequest):
    uploaded = []
    results = []
    folder_rel = str(payload.folder or "").strip("/\\")
    timeout = httpx.Timeout(connect=20.0, read=120.0, write=30.0, pool=20.0)
    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True, headers={"User-Agent": "Infinite-Canvas-Asset-Importer/1.0"}) as client:
        for entry in (payload.items or [])[:200]:
            src_url = str(entry.url or "").strip()
            inline_data = str(entry.data or "").strip()
            result = {"url": src_url, "ok": False, "file": "", "error": ""}
            if not inline_data and not src_url.startswith(("http://", "https://")):
                result["error"] = "仅支持 http(s) 素材地址"
                results.append(result)
                continue
            try:
                if inline_data:
                    # 插件已在网页上下文里把字节读成 base64（dataURL 形如 data:<ct>;base64,<payload>）
                    content_type = str(entry.content_type or "").split(";", 1)[0].strip().lower()
                    b64 = inline_data
                    if inline_data.startswith("data:"):
                        header, _, b64 = inline_data.partition(",")
                        if not content_type:
                            content_type = header[5:].split(";", 1)[0].strip().lower()
                    try:
                        content = base64.b64decode(b64, validate=False)
                    except Exception:
                        raise HTTPException(status_code=400, detail="素材数据无法解码")
                    name_path = urllib.parse.urlparse(src_url).path
                else:
                    response = await client.get(src_url)
                    response.raise_for_status()
                    content_type = response.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
                    content = response.content
                    name_path = urllib.parse.urlparse(src_url).path
                kind, ext = _local_upload_kind_ext(name_path, content_type)
                if kind == "image":
                    real = _sniff_image_ext_bytes(content[:16])   # 以真实内容为准，避免 webp 被叫成 .png 等
                    if real and not (real == ".jpg" and ext == ".jpeg"):
                        ext = real
                if kind not in ("image", "video"):
                    raise HTTPException(status_code=400, detail=f"不是图片或视频资源：{content_type or src_url}")
                if not content:
                    raise HTTPException(status_code=400, detail="素材内容为空")
                # entry.name 可能自带扩展名（采集器常传完整文件名），先 splitext 去掉，否则会和下面拼接的 ext 叠成 .png.png
                if entry.name:
                    base = os.path.splitext(entry.name)[0]
                else:
                    base = os.path.splitext(os.path.basename(urllib.parse.unquote(name_path)))[0]
                base = base or ("web-video" if kind == "video" else "web-image")
                base = re.sub(r"[^0-9A-Za-z一-鿿._-]+", "_", base).strip("_") or ("web-video" if kind == "video" else "web-image")
                base = base[:60]
                # 兜底：若 base 末尾已是同一扩展名，去掉一层再拼，杜绝重复后缀
                if ext and base.lower().endswith(ext.lower()):
                    base = base[:-len(ext)].rstrip(".") or ("web-video" if kind == "video" else "web-image")
                filename = f"{base}{ext}"
                record = PROJECT_STORAGE.store_material_bytes(
                    content,
                    filename,
                    scope="temporary",
                    content_type=content_type,
                    folder=folder_rel,
                )
                item = material_public_item(record)
                uploaded.append(item)
                result.update({"ok": True, "file": record["id"], "item": item})
            except HTTPException as exc:
                result["error"] = str(exc.detail or "导入失败")
            except Exception as exc:
                result["error"] = str(exc) or "导入失败"
            results.append(result)
    return {"ok": True, "count": len(uploaded), "files": uploaded, "items": results}

