@app.put("/api/providers")
async def save_providers(payload: List[ApiProviderPayload]):
    providers = []
    env_updates = {}
    # 收集每个 item 的 primary 字段
    raw_primary_flags = [bool(getattr(item, "primary", False)) for item in payload]
    for item in payload:
        provider = normalize_provider(item.dict(exclude={"api_key"}))
        if provider["id"] == "runninghub":
            provider = preserve_runninghub_hidden_overrides(provider)
            prune_runninghub_workflow_store_for_provider(provider, region=provider.get("rh_region", ""))
        if any(existing["id"] == provider["id"] for existing in providers):
            raise HTTPException(status_code=400, detail=f"API 平台 ID 重复：{provider['id']}")
        providers.append(provider)
        # RunningHub 的国内站与国际站使用独立 Key。旧 RUNNINGHUB_API_KEY 只保留为
        # 国际站历史配置的读取兼容，新的保存/清除操作不得再写它，否则国内 Key 会
        # 被国际站的 legacy fallback 误读。
        if provider["id"] != "runninghub":
            key_env = provider_key_env(provider["id"])
            if item.clear_key:
                env_updates[key_env] = ""
            elif item.api_key is not None and item.api_key.strip():
                env_updates[key_env] = item.api_key.strip()
        if provider["id"] == "runninghub":
            selected_region = runninghub_normalize_region(provider.get("rh_region"), "global")
            api_keys = item.rh_api_keys if isinstance(item.rh_api_keys, dict) else {}
            wallet_keys = item.rh_wallet_api_keys if isinstance(item.rh_wallet_api_keys, dict) else {}
            for region in RUNNINGHUB_REGION_DEFAULTS:
                api_env = runninghub_api_key_env(region)
                wallet_env = runninghub_wallet_key_env(region)
                if region in item.clear_rh_api_keys:
                    env_updates[api_env] = ""
                elif str(api_keys.get(region) or "").strip():
                    env_updates[api_env] = str(api_keys[region]).strip()
                if region in item.clear_rh_wallet_api_keys:
                    env_updates[wallet_env] = ""
                elif str(wallet_keys.get(region) or "").strip():
                    env_updates[wallet_env] = str(wallet_keys[region]).strip()
            # 兼容旧前端一次性提交的当前区域 Key。
            if item.clear_key:
                env_updates[runninghub_api_key_env(selected_region)] = ""
            elif item.api_key is not None and item.api_key.strip():
                env_updates[runninghub_api_key_env(selected_region)] = item.api_key.strip()
            if item.clear_wallet_key:
                env_updates[runninghub_wallet_key_env(selected_region)] = ""
            elif item.wallet_api_key is not None and item.wallet_api_key.strip():
                env_updates[runninghub_wallet_key_env(selected_region)] = item.wallet_api_key.strip()
        if provider["id"] == "volcengine":
            ak_env = volcengine_access_key_env()
            sk_env = volcengine_secret_key_env()
            if item.clear_volcengine_access_key_id:
                env_updates[ak_env] = ""
            elif item.volcengine_access_key_id is not None and item.volcengine_access_key_id.strip():
                env_updates[ak_env] = item.volcengine_access_key_id.strip()
            if item.clear_volcengine_secret_access_key:
                env_updates[sk_env] = ""
            elif item.volcengine_secret_access_key is not None and item.volcengine_secret_access_key.strip():
                env_updates[sk_env] = item.volcengine_secret_access_key.strip()
        if provider["id"] == "comfly":
            env_updates["COMFLY_BASE_URL"] = provider["base_url"]
            env_updates["IMAGE_MODELS"] = ",".join(provider["image_models"])
            env_updates["CHAT_MODELS"] = ",".join(provider["chat_models"])
            env_updates["VIDEO_MODELS"] = ",".join(provider.get("video_models") or [])
        if provider["id"] == "modelscope":
            env_updates["MODELSCOPE_CHAT_MODELS"] = ",".join(provider["chat_models"])
        if provider["id"] == "runninghub":
            provider["protocol"] = "runninghub"
        if provider["id"] == "volcengine":
            provider["protocol"] = "volcengine"
    if not providers:
        raise HTTPException(status_code=400, detail="至少保留一个 API 平台")
    # 强制最多一个 primary（取最后被标记的；都没标记则保持原样不强制）
    primary_indices = [i for i, flag in enumerate(raw_primary_flags) if flag]
    if primary_indices:
        winner = primary_indices[-1]
        for i, p in enumerate(providers):
            p["primary"] = (i == winner)
    save_api_providers(providers)
    runninghub_provider = next((item for item in providers if item.get("id") == "runninghub"), None)
    if runninghub_provider:
        sync_runninghub_provider_workflows_to_static_template(
            runninghub_provider,
            region=runninghub_provider.get("rh_region", ""),
        )
    if env_updates:
        update_env_values(env_updates)
        reload_env_globals()   # 立即将最新 env 值同步回模块全局变量，无需重启
    return {"providers": [public_provider(p) for p in providers]}

