# --- 画布与素材连接器共用的模型请求 ---

class TestConnectionPayload(BaseModel):
    base_url: str = ""
    api_key: str = ""
    provider_id: str = ""
    protocol: str = "openai"
    image_request_mode: str = "openai"
    region: str = ""

def protocol_from_payload(payload):
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    if provider_id == "volcengine":
        return "volcengine"
    if provider_id == "runninghub":
        return "runninghub"
    if provider_id == "jimeng":
        return "jimeng"
    base_url = str(getattr(payload, "base_url", "") or "").strip().lower()
    if "runninghub.cn" in base_url or "runninghub.ai" in base_url:
        return "runninghub"
    protocol = str(getattr(payload, "protocol", "") or "openai").strip().lower()
    return protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"

def api_key_from_payload(payload, protocol: str = ""):
    explicit = str(getattr(payload, "api_key", "") or "").strip()
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    protocol = str(protocol or protocol_from_payload(payload) or "").strip().lower()
    if explicit:
        return explicit
    if provider_id:
        if provider_id == "runninghub":
            region = getattr(payload, "region", "") or runninghub_region_from_base_url(getattr(payload, "base_url", ""), "global")
            value = runninghub_wallet_key_value(region)
            if value:
                return value
            value = runninghub_region_key_value(region, use_wallet=False)
        else:
            value = provider_env_key_value(provider_id)
        if value:
            return value
    if protocol == "volcengine":
        return volcengine_provider_api_key("")
    return ""

def upstream_models_url(base_url: str, protocol: str):
    if protocol == "gemini":
        return f"{base_url}/models" if base_url.endswith("/v1beta") else f"{base_url}/v1beta/models"
    if protocol == "volcengine":
        return f"{base_url}/models" if base_url.endswith("/api/v3") else f"{base_url}/api/v3/models"
    if protocol == "runninghub":
        raise ValueError("RunningHub 标准模型必须从官方 developer-kit 注册表读取")
    return f"{base_url}/models" if base_url.endswith("/v1") else f"{base_url}/v1/models"

def upstream_models_endpoint_label(protocol: str):
    if protocol == "gemini":
        return "/v1beta/models"
    if protocol == "volcengine":
        return "/api/v3/models"
    if protocol == "runninghub":
        return "developer-kit/model-registry.public.json"
    return "/v1/models"

def upstream_model_headers(api_key: str, protocol: str):
    if protocol == "gemini":
        return {"x-goog-api-key": api_key, "Accept": "application/json"}
    if protocol == "runninghub":
        return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}
    return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}

def volcengine_default_model_payload(status=200, message="", raw=None):
    return {
        "ok": True,
        "protocol": "volcengine",
        "status": status,
        "message": message or "方舟任务接口可用，模型列表接口未返回模型。请按实际方舟控制台模型名称手动填写视频模型。",
        "model_count": 0,
        "image_models": [],
        "chat_models": [],
        "video_models": [],
        "audio_models": [],
        "all": [],
        "raw": raw,
    }

def volcengine_task_probe_url(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    if base.endswith("/api/v3"):
        return f"{base}/contents/generations/tasks/healthcheck_probe_do_not_submit"
    return f"{base}/api/v3/contents/generations/tasks/healthcheck_probe_do_not_submit"

async def probe_volcengine_task_endpoint(client, base_url: str, api_key: str):
    probe_url = volcengine_task_probe_url(base_url)
    if not probe_url:
        return False, {"status": 0, "message": "Base URL 为空"}
    response = await client.get(probe_url, headers=upstream_model_headers(api_key, "volcengine"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "方舟 API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "任务接口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "方舟任务查询端点可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"方舟任务接口服务端错误 {response.status_code}", "raw": raw}

def openai_compat_root_for_probe(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if base.endswith("/api/v3"):
        base = base[: -len("/api/v3")]
    if base.endswith("/v1"):
        return base
    return f"{base}/v1" if base else ""

async def probe_openai_compat_bearer_endpoint(client, base_url: str, api_key: str):
    root = openai_compat_root_for_probe(base_url)
    if not root:
        return False, {"status": 0, "message": "Base URL 为空"}
    url = f"{root}/chat/completions"
    response = await client.post(
        url,
        headers={**upstream_model_headers(api_key, "openai"), "Content-Type": "application/json"},
        json={"messages": []},
    )
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI 兼容入口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "OpenAI 兼容 Bearer 鉴权入口可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI 兼容入口服务端错误 {response.status_code}", "raw": raw}

async def probe_openai_models_endpoint(client, base_url: str, api_key: str):
    url = upstream_models_url(base_url, "openai")
    response = await client.get(url, headers=upstream_model_headers(api_key, "openai"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (301, 302, 303, 307, 308):
        location = response.headers.get("Location") or response.headers.get("location") or ""
        suffix = f"：{location}" if location else ""
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址", "raw": raw}
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "OpenAI API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI /v1/models 返回网页 HTML，请检查请求地址是否为 API Base URL", "raw": raw}
    if response.status_code < 300:
        grouped, ids = parse_upstream_models(raw, "openai") if isinstance(raw, dict) else ({"image": [], "chat": [], "video": [], "audio": []}, [])
        grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
        grouped = apply_locked_recommended_model_rules(base_url, grouped)
        return True, {
            "status": response.status_code,
            "message": f"OpenAI 兼容模型列表端点可用{f'，找到 {len(ids)} 个模型' if ids else ''}",
            "raw": raw,
            "model_count": len(ids),
            "image_models": grouped["image"],
            "chat_models": grouped["chat"],
            "video_models": grouped["video"],
            "audio_models": grouped["audio"],
            "all": ids,
        }
    if 400 <= response.status_code < 500:
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 不可用 (HTTP {response.status_code})", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI /v1/models 服务端错误 {response.status_code}", "raw": raw}

async def probe_volcengine_auto_detect(client, base_url: str, api_key: str):
    task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
    if task_ok:
        return True, {
            "status": task_probe.get("status") or 200,
            "message": "检测到方舟/Ark 任务协议",
            "raw": {"task_probe": task_probe.get("raw")},
        }
    compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
    if compat_ok:
        return True, {
            "status": compat_probe.get("status") or 200,
            "message": "检测到方舟/Ark Bearer 鉴权入口（OpenAI 兼容透传）",
            "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
        }
    return False, {
        "status": compat_probe.get("status") or task_probe.get("status") or 0,
        "message": compat_probe.get("message") or task_probe.get("message") or "未检测到方舟/Ark 兼容入口",
        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
    }

def classify_upstream_model(mid):
    lc = normalize_laohu_model_id(mid).lower()
    if lc in {"laohu-upscaler", "minimax-h3"}:
        return "video"
    if lc.startswith("minmax-h3-context-ir-") or lc == "whisper-1" or lc == "midjourney-describe":
        return "chat"
    if lc == "midjourney-video":
        return "video"
    if re.search(r"(?:^|[-_/])(t2v|i2v|v2v|r2v|s2v)(?:$|[-_/])", lc) or any(
        token in lc for token in (
            "start-end", "start_end", "motion", "short-play", "short_play",
            "happyhorse", "vidu-q", "wan-2.7-spicy", "minimax-h3-ow",
        )
    ):
        return "video"
    if re.search(r"(?:^|[-_/])(t2i|i2i)(?:$|[-_/])", lc):
        return "image"
    audio_keys = ["audio", "speech", "tts", "voice", "music", "mureka", "suno", "whisper", "seed-tts"]
    if any(k in lc for k in audio_keys):
        return "audio"
    video_keys = ["veo", "sora", "wan2", "wanx", "doubao-seedance", "seedance", "doubao-1", "kling", "hailuo", "video", "t2v-", "i2v-", "s2v"]
    if any(k in lc for k in video_keys):
        return "video"
    image_keys = ["banana", "image", "dalle", "dall-e", "imagen", "flux", "stable", "sdxl", "midjourney", "nano-banana", "ideogram", "fal-ai", "z-image", "qwen-image", "klein", "seedream", "doubao-seedream", "text-to-image", "image-to-image"]
    if any(k in lc for k in image_keys):
        return "image"
    return "chat"

def parse_upstream_models(raw, protocol="openai"):
    items = raw.get("data") if isinstance(raw, dict) else None
    if not items and isinstance(raw, dict):
        items = raw.get("models") or raw.get("list") or []
    if not isinstance(items, list):
        items = []
    ids = []
    owner_by_id = {}
    for it in items:
        if isinstance(it, str):
            mid = it
        elif isinstance(it, dict):
            mid = it.get("id") or it.get("name") or it.get("model")
        else:
            mid = ""
        if mid:
            mid = str(mid)
            if protocol == "gemini" and mid.startswith("models/"):
                mid = mid[len("models/"):]
            ids.append(mid)
            if isinstance(it, dict):
                owner_by_id[mid] = str(it.get("owned_by") or "").strip().lower()
    ids = sorted(set(ids))
    grouped = {"image": [], "chat": [], "video": [], "audio": []}
    for mid in ids:
        owner = owner_by_id.get(mid, "")
        if owner == "apimart music":
            kind = "audio"
        elif owner == "apimart-midjourney" and mid == "midjourney-video":
            kind = "video"
        elif owner == "apimart-midjourney" and mid == "midjourney-describe":
            kind = "chat"
        else:
            kind = classify_upstream_model(mid)
        grouped[kind].append(mid)
    return grouped, ids

def apply_agnes_model_defaults(base_url, grouped, ids):
    if "apihub.agnes-ai.com" not in str(base_url or "").strip().lower():
        return grouped, ids
    grouped = {key: list(value or []) for key, value in (grouped or {}).items()}
    grouped.setdefault("image", [])
    grouped.setdefault("chat", [])
    grouped.setdefault("audio", [])
    ids = list(ids or [])
    for model in AGNES_DEFAULT_VIDEO_MODELS:
        if model not in ids:
            ids.append(model)
        if model not in grouped.setdefault("video", []):
            grouped["video"].append(model)
    ids = sorted(set(ids))
    grouped["video"] = sorted(set(grouped.get("video") or []))
    return grouped, ids

@app.post("/api/providers/test-connection")
async def test_provider_connection(payload: TestConnectionPayload):
    """检查当前平台的官方接入入口，并在可能时同步返回模型目录。"""
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        status = await codex_status()
        payload_models = codex_models_payload(raw={"status": status})
        payload_models.update({
            "ok": bool(status.get("installed")),
            "status": 200 if status.get("installed") else 0,
            "message": status.get("message") or ("OpenAI Codex CLI 可用" if status.get("installed") else "未找到 OpenAI Codex CLI"),
        })
        return payload_models
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload_models = gemini_cli_models_payload(raw={"status": status})
        payload_models.update({
            "ok": bool(status.get("installed")),
            "status": 200 if status.get("installed") else 0,
            "message": status.get("message") or ("Antigravity CLI 可用" if status.get("installed") else "未找到 Antigravity CLI"),
        })
        return payload_models
    if protocol == "jimeng":
        status = await jimeng_status()
        return {
            "ok": bool(status.get("installed") and status.get("logged_in")),
            "status": 200 if status.get("logged_in") else 0,
            "message": status.get("message") or "即梦 CLI 已登录",
            "model_count": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "audio_models": [],
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
            "raw": status.get("raw"),
        }
    if protocol == "runninghub":
        api_key = api_key_from_payload(payload, protocol)
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": (payload.base_url or RUNNINGHUB_DEFAULT_BASE_URL).strip().rstrip("/"), "protocol": "runninghub", "rh_region": getattr(payload, "region", ""), "api_key": api_key, "wallet_api_key": api_key}
        try:
            payload_models = await runninghub_models_payload(provider)
        except HTTPException:
            raise
        except Exception as exc:
            log_runninghub_error("test-connection", error_type=type(exc).__name__, message=str(exc)[:300])
            raise HTTPException(status_code=502, detail=f"RunningHub 连接失败：{str(exc)[:300]}") from exc
        message = "RunningHub 官方模型目录已读取；官方未提供无计费 Key 预验接口，Key 将在首次真实任务时验证。"
        return {
            "ok": True,
            "status": 200,
            "message": message,
            "model_count": payload_models["total"],
            "image_models": payload_models["image_models"],
            "chat_models": payload_models["chat_models"],
            "video_models": payload_models["video_models"],
            "audio_models": payload_models.get("audio_models") or [],
            "all": payload_models["all"],
            "model_names": payload_models.get("model_names") or {},
            "model_availability": payload_models.get("model_availability") or {},
            "region": payload_models.get("region") or runninghub_provider_region(provider),
            "protocol": "runninghub",
            "raw": payload_models.get("raw"),
        }
    base_url = (payload.base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                endpoint_label = upstream_models_endpoint_label(protocol)
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址"}
            if looks_like_html_response(resp.text):
                endpoint_label = upstream_models_endpoint_label(protocol)
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL"}
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                return {"ok": False, "status": resp.status_code, "message": resp.text[:300]}
            data = resp.json() if resp.text else {}
            grouped, ids = parse_upstream_models(data, protocol)
            grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
            grouped = apply_locked_recommended_model_rules(base_url, grouped)
            if protocol == "volcengine" and not ids:
                detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return volcengine_default_model_payload(status=resp.status_code, raw=data)
            return {
                "ok": True,
                "status": resp.status_code,
                "model_count": len(ids),
                "image_models": grouped["image"],
                "chat_models": grouped["chat"],
                "video_models": grouped["video"],
                "audio_models": grouped["audio"],
                "all": ids,
                "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
            }
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or 0, message=message, raw={"models_error": str(e)[:300], **(probe.get("raw") or {})})
            except Exception:
                pass
        return {"ok": False, "status": 0, "message": str(e)[:300]}

@app.post("/api/providers/probe-async")
async def probe_async_endpoint(payload: TestConnectionPayload):
    """验证异步协议：用假 task_id 请求 GET /v1/tasks/{fake_id}。
    收到 400 Invalid task ID = 端点存在且 Key 有效；401/403 = Key 无效；404/连接失败 = 不支持异步端点。"""
    base_url = (payload.base_url or "").strip().rstrip("/")
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        status = await codex_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "codex",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "OpenAI Codex CLI 本机检测完成",
            "raw": status,
        }
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "gemini-cli",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "Antigravity CLI 本机检测完成",
            "raw": status,
        }
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        raise HTTPException(status_code=400, detail="请先填写或保存 API Key")
    is_tudou_async = is_tudou_base_url(base_url)
    if protocol == "volcengine":
        try:
            async with httpx.AsyncClient(timeout=15) as client:
                task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
                if task_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": task_probe.get("status") or 200,
                        "message": "方舟/Ark 任务协议可用",
                        "raw": task_probe.get("raw"),
                    }
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                if compat_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": compat_probe.get("status") or 200,
                        "message": "方舟/Ark Bearer 鉴权入口可用（OpenAI 兼容透传）",
                        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                    }
                return {
                    "ok": False,
                    "protocol": "volcengine",
                    "status_code": compat_probe.get("status") or task_probe.get("status") or 0,
                    "message": compat_probe.get("message") or task_probe.get("message") or "方舟/Ark 任务协议不可用",
                    "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                }
        except httpx.HTTPError as e:
            raise HTTPException(status_code=502, detail=str(e)[:300])
    tasks_base = base_url if base_url.endswith("/v1") else f"{base_url}/v1"
    probe_url = f"{tasks_base}/tasks/healthcheck_probe_do_not_submit"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(probe_url, headers={"Authorization": bearer_auth_value(api_key), "Accept": "application/json"})
            try:
                body = resp.json()
            except Exception:
                body = resp.text[:500]
            sc = resp.status_code
            # 判断结果
            err_msg = ""
            if isinstance(body, dict):
                err = body.get("error") or {}
                if isinstance(err, dict):
                    err_msg = str(err.get("message") or "").lower()
                else:
                    err_msg = str(err).lower()
            # 400 + "invalid task id" → 端点存在，Key 有效
            if is_tudou_async and sc == 400:
                # 土豆对不存在的 task_id 可能使用不同的 400 错误字段；只要不是
                # 401/403，400 已证明请求命中了异步任务端点且认证通过。
                return {
                    "ok": True,
                    "protocol": "openai",
                    "image_request_mode": "tudou-async",
                    "status_code": sc,
                    "message": "土豆 GPT-Image-2 异步任务端点可用，API Key 已通过认证",
                    "raw": body,
                }
            if sc == 400 and "invalid task id" in err_msg:
                return {"ok": True, "protocol": "apimart", "status_code": sc, "message": "APIMart 异步任务端点可用，API Key 已通过认证", "raw": body}

            async_probe = {"status": sc, "message": "", "raw": body}
            if sc in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                async_probe["message"] = f"/v1/tasks/ 发生跳转{f'：{location}' if location else ''}"
            elif looks_like_html_response(resp.text):
                async_probe["message"] = "/v1/tasks/ 返回网页 HTML"
            elif sc in (401, 403):
                async_probe["message"] = "/v1/tasks/ 返回鉴权失败"
            elif sc == 404:
                async_probe["message"] = "平台不支持 /v1/tasks/ 端点，可能不是 APIMart 异步协议"
            elif 400 <= sc < 500:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}"
            elif sc < 300:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}（意外成功）"
            else:
                async_probe["message"] = f"/v1/tasks/ 服务端错误 {sc}"

            if is_tudou_async:
                return {
                    "ok": sc < 400,
                    "protocol": "openai",
                    "image_request_mode": "tudou-async" if sc < 400 else "openai",
                    "status_code": sc,
                    "message": async_probe["message"] or "土豆 GPT-Image-2 异步任务端点验证完成",
                    "raw": body,
                }

            if protocol == "apimart":
                return {"ok": False, "protocol": "apimart", "status_code": sc, "message": async_probe["message"], "raw": body}

            openai_ok, openai_probe = await probe_openai_models_endpoint(client, base_url, api_key)
            if not openai_ok and protocol == "openai":
                # /v1/models 不可用，先确认是不是“没实现 models 接口的 OpenAI 兼容站”：探一下 /v1/chat/completions。
                # 可达就判定为 OpenAI 兼容（很多网关不暴露 /v1/models），避免被下面的方舟探测（404 也算可达）误判成方舟。
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                # 仅当 /v1/chat/completions 确实存在（返回 2xx 或我们发空 messages 触发的 400 等，而非 404 路径不存在）
                # 才判为 OpenAI 兼容；404 说明该路径不存在，留给后面的方舟探测。
                if compat_ok and (compat_probe.get("status") or 0) != 404:
                    return {
                        "ok": True,
                        "protocol": "openai",
                        "status_code": compat_probe.get("status") or openai_probe.get("status") or sc,
                        "message": "OpenAI 兼容入口可达（该站未提供 /v1/models，模型请手动填写）",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), "openai_compat_probe": compat_probe.get("raw")},
                        "model_count": 0,
                        "image_models": [],
                        "chat_models": [],
                        "video_models": [],
                        "audio_models": [],
                        "all": [],
                    }
                detected, volc_probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": volc_probe.get("status") or openai_probe.get("status") or sc,
                        "message": f"{volc_probe.get('message') or '检测到方舟/Ark 兼容入口'}，已自动切换为方舟/Ark 任务协议",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), **(volc_probe.get("raw") or {})},
                    }
            return {
                "ok": openai_ok,
                "protocol": "openai",
                "status_code": openai_probe.get("status") or sc,
                "message": openai_probe.get("message") or "OpenAI 兼容验证完成",
                "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw")},
                "model_count": openai_probe.get("model_count") or 0,
                "image_models": openai_probe.get("image_models") or [],
                "chat_models": openai_probe.get("chat_models") or [],
                "video_models": openai_probe.get("video_models") or [],
                "audio_models": openai_probe.get("audio_models") or [],
                "all": openai_probe.get("all") or [],
                "image_request_mode": detect_image_request_mode(base_url, openai_probe.get("all") or []) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
            }
    except httpx.HTTPError as e:
        raise HTTPException(status_code=502, detail=str(e)[:300])

async def fetch_models_from_upstream(base_url: str, api_key: str, protocol: str = "openai", image_request_mode: str = "openai", region: str = ""):
    """从上游模型列表端点拉取模型，并按名称做轻量分类。"""
    protocol = protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"
    if protocol == "codex":
        status = await codex_status()
        payload = codex_models_payload(raw={"status": status})
        payload["message"] = status.get("message") or payload["message"]
        return payload
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload = gemini_cli_models_payload(raw={"status": status})
        payload["message"] = status.get("message") or payload["message"]
        return payload
    if protocol == "jimeng":
        return {
            "total": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "audio_models": [],
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
        }
    if protocol == "runninghub":
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": base_url or RUNNINGHUB_DEFAULT_BASE_URL, "protocol": "runninghub", "rh_region": region, "api_key": api_key, "wallet_api_key": api_key}
        return await runninghub_models_payload(provider)
    base_url = (base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = volcengine_provider_api_key(api_key) if protocol == "volcengine" else (api_key or "").strip()
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            endpoint_label = upstream_models_endpoint_label(protocol)
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址")
            if looks_like_html_response(resp.text):
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL")
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "audio_models": payload.get("audio_models") or [],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "audio_models": payload.get("audio_models") or [],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                raise HTTPException(status_code=resp.status_code, detail=f"上游 {endpoint_label} 失败：{resp.text[:300]}")
            raw = resp.json()
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or 0,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": str(e)[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "audio_models": payload.get("audio_models") or [],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
            except Exception:
                pass
        raise HTTPException(status_code=502, detail=f"请求上游模型列表失败：{e}")
    grouped, ids = parse_upstream_models(raw, protocol)
    grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
    grouped = apply_locked_recommended_model_rules(base_url, grouped)
    if protocol == "volcengine" and not ids:
        payload = volcengine_default_model_payload(raw=raw)
        return {
            "total": payload["model_count"],
            "image_models": payload["image_models"],
            "chat_models": payload["chat_models"],
            "video_models": payload["video_models"],
            "audio_models": payload.get("audio_models") or [],
            "all": payload["all"],
            "message": payload["message"],
            "raw": payload["raw"],
        }
    return {
        "total": len(ids),
        "image_models": grouped["image"],
        "chat_models": grouped["chat"],
        "video_models": grouped["video"],
        "audio_models": grouped["audio"],
        "all": ids,
        "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(image_request_mode),
    }

@app.post("/api/providers/fetch-models")
async def fetch_upstream_models_from_payload(payload: TestConnectionPayload):
    """按页面当前表单值拉取模型，支持新增平台未保存时直接使用临时 Base URL / Key。"""
    protocol = protocol_from_payload(payload)
    api_key = api_key_from_payload(payload, protocol)
    return await fetch_models_from_upstream(payload.base_url, api_key, protocol, payload.image_request_mode, payload.region)

@app.get("/api/providers/{provider_id}/fetch-models")
async def fetch_upstream_models(provider_id: str, region: str = ""):
    """从已保存的上游 OpenAI 兼容接口拉取 /v1/models 列表，按名称智能分类为 image/chat/video。"""
    provider = get_api_provider_exact(provider_id)
    if is_codex_provider(provider):
        return await fetch_models_from_upstream("", "", "codex", provider.get("image_request_mode") or "openai")
    if is_gemini_cli_provider(provider):
        return await fetch_models_from_upstream("", "", "gemini-cli", provider.get("image_request_mode") or "openai")
    if provider_protocol(provider) == "jimeng":
        return await fetch_models_from_upstream("", "", "jimeng", provider.get("image_request_mode") or "openai")
    selected_region = runninghub_normalize_region(region or provider.get("rh_region")) if provider["id"] == "runninghub" else ""
    api_key = os.getenv(runninghub_wallet_key_env(selected_region), "") if provider["id"] == "runninghub" else ""
    if not api_key:
        api_key = provider_env_key_value(provider["id"])
    if not api_key and provider["id"] != "runninghub":
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider_id} 未配置 API Key")
    base_url = provider.get("base_url") or ""
    if provider["id"] == "runninghub":
        region_config = (provider.get("rh_regions") or {}).get(selected_region) or {}
        base_url = region_config.get("base_url") or RUNNINGHUB_REGION_DEFAULTS[selected_region]["base_url"]
    payload = await fetch_models_from_upstream(base_url, api_key, provider_protocol(provider), provider.get("image_request_mode") or "openai", selected_region)
    if provider["id"] != "runninghub":
        save_provider_catalog_snapshot(Path(BASE_DIR), provider["id"], payload, source=upstream_models_url(base_url, provider_protocol(provider)))
    return payload

async def build_online_image_result(payload: OnlineImageRequest):
    provider = get_api_provider(payload.provider_id, region=payload.region)
    default_model = (provider.get("image_models") or [IMAGE_MODEL])[0]
    model = selected_model(payload.model, default_model)
    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    count = max(1, min(8, int(payload.n or 1)))
    capability_parameters = {
        key: value for key, value in {
            "resolution": str(payload.resolution or "").strip(),
            "aspect_ratio": str(payload.aspect_ratio or "").strip(),
            "quality": str(payload.quality or "").strip() if str(payload.quality or "").strip().lower() != "auto" else "",
            "count": count if count != 1 else None,
        }.items() if value not in ("", None)
    }
    capability_parameters.update(payload.parameters or {})
    request_size = canvas_image_request_size(payload.size, capability_parameters)
    profile = resolve_model_capability_request(
        provider.get("id") or payload.provider_id,
        model,
        payload.family_id,
        "image_generation",
        input_counts={"prompt": 1 if str(payload.prompt or "").strip() else 0, "image": len(image_refs)},
        input_roles=payload.input_roles or {
            "prompt": 1 if str(payload.prompt or "").strip() else 0,
            "reference": len(image_refs),
        },
        parameters=capability_parameters,
        providers=[provider],
    )
    model = str(profile.get("model_id") or model)
    payload.model = model
    platform_parameters = MODEL_CAPABILITY_REGISTRY.platform_parameters(profile, capability_parameters)
    profile_operation = str(profile.get("operation") or "").strip().lower()
    operation = str(payload.operation or "").strip().lower()
    if operation == "upscale":
        if not is_jimeng_provider(provider):
            raise HTTPException(status_code=400, detail="图片放大目前仅支持即梦（Dreamina）平台")
        if not image_refs:
            raise HTTPException(status_code=400, detail="请先选择要放大的图片")
        count = 1
    async def generate_one():
        if operation == "upscale":
            image_data, raw_item = await generate_jimeng_upscale_image(image_refs, payload.resolution_type)
        elif is_ai_money_provider(provider) and profile_operation.startswith("midjourney_"):
            image_data, raw_item = await generate_ai_money_midjourney_image(
                payload.prompt,
                payload.size,
                model,
                refs,
                provider,
                platform_parameters,
                profile_operation,
            )
        else:
            image_data, raw_item = await generate_ai_image(
                payload.prompt, request_size, payload.quality, model, image_refs, provider["id"],
                payload.aspect_ratio, payload.resolution, platform_parameters, payload.region,
            )
        try:
            image_items = extract_images(raw_item) if isinstance(raw_item, dict) else [image_data]
        except HTTPException:
            image_items = [image_data]
        local_urls = []
        local_items = []
        for item in image_items:
            local_url = await save_ai_image_to_output(item, prefix="online_")
            if local_url:
                local_urls.append(local_url)
                local_items.append(image_output_meta(local_url, item))
        return local_urls, local_items, raw_item
    try:
        generated = await asyncio.gather(*(generate_one() for _ in range(count)))
    except httpx.HTTPStatusError as exc:
        log_net_error(f"生图 HTTP状态错误 provider={provider.get('id')} model={model} size={request_size}", exc)
        text = exc.response.text or ''
        friendly = friendly_image_error_detail(text, request_size, model)
        detail = friendly or f"上游生图接口错误：{text[:300]}"
        raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
    except httpx.HTTPError as exc:
        log_net_error(f"生图 网络/TLS错误 provider={provider.get('id')} model={model}", exc)
        raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{exc}") from exc

    local_urls = [url for urls, _items, _raw in generated for url in (urls or []) if url]
    local_items = [item for _urls, items, _raw in generated for item in (items or []) if item.get("url")]
    raw = generated[0][2] if generated else {}
    if not local_urls:
        provider_name = provider.get("name") or provider["id"]
        raw_text = json.dumps(raw, ensure_ascii=False)[:800] if isinstance(raw, (dict, list)) else str(raw)[:800]
        raise HTTPException(status_code=502, detail=f"{provider_name} 没有返回图片：{raw_text}")
    result = {
        "prompt": payload.prompt,
        "images": local_urls,
        "image_items": local_items,
        "timestamp": time.time(),
        "type": "online",
        "model": model,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "task_id": extract_task_id(raw) if isinstance(raw, dict) else None,
        "request_id": raw.get("id") if isinstance(raw, dict) else None,
        "params": {"provider_id": provider["id"], "model": model, "size": request_size, "requested_size": payload.size, "quality": payload.quality, "n": count, "reference_images": refs},
        "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
    }
    generation_derivation = {
        "operation": "online-image",
        "prompt": payload.prompt,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "model": model,
        "parameters": result["params"],
    }
    for url in local_urls:
        clean_url = urllib.parse.unquote(str(url or "").split("?", 1)[0]).rstrip("/")
        if not clean_url.startswith("/api/results/"):
            continue
        result_id = clean_url.rsplit("/", 1)[-1].strip()
        if not result_id:
            continue
        try:
            PROJECT_STORAGE.update_result_metadata(result_id, derivation=generation_derivation)
        except StorageError:
            continue
    save_to_history(result)
    if GLOBAL_LOOP:
        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
    return result

async def online_image(payload: OnlineImageRequest):
    return await build_online_image_result(payload)

# Midjourney is intentionally kept outside the generic image-generation flow.
# APIMart exposes it as a task API with its own action endpoints, which does not
# match either OpenAI images or Gemini image responses.
APIMART_MIDJOURNEY_API_ROOT = "https://api.apimart.ai"
MIDJOURNEY_SPEEDS = {"relax", "fast", "turbo"}
MIDJOURNEY_ACTION_PATHS = {
    "upscale": "/v1/midjourney/generations/upscale",
    "variation": "/v1/midjourney/generations/variation",
    "low_variation": "/v1/midjourney/generations/low-variation",
    "high_variation": "/v1/midjourney/generations/high-variation",
    "reroll": "/v1/midjourney/generations/reroll",
    "zoom": "/v1/midjourney/generations/zoom",
    "pan": "/v1/midjourney/generations/pan",
    "inpaint": "/v1/midjourney/generations/inpaint",
    "remix_subtle": "/v1/midjourney/generations/remix-subtle",
    "remix_strong": "/v1/midjourney/generations/remix-strong",
}

def midjourney_api_url(provider, path):
    base_url = str((provider or {}).get("base_url") or "").strip().rstrip("/")
    root = laohu_api_base_url(provider) if is_ai_money_provider(provider) else APIMART_MIDJOURNEY_API_ROOT
    return f"{root}{path}"

def apimart_midjourney_provider(provider_id: str):
    provider = get_api_provider_exact(provider_id)
    if not (is_apimart_provider(provider) or is_ai_money_provider(provider)):
        raise HTTPException(status_code=400, detail="Midjourney 节点仅支持已完成专用任务接口适配的平台。")
    # This also validates the configured key, while all MJ requests below keep
    # using APIMart's official host instead of inheriting a custom image URL.
    api_headers(provider=provider)
    return provider

def midjourney_response_data(raw):
    if not isinstance(raw, dict):
        return {}
    data = raw.get("data")
    if isinstance(data, dict):
        return data
    if isinstance(data, list):
        return next((item for item in data if isinstance(item, dict)), raw)
    return raw

def midjourney_task_id(raw):
    data = midjourney_response_data(raw)
    for key in ("task_id", "taskId", "id"):
        value = str(data.get(key) or "").strip()
        if value:
            return value
    return ""

def midjourney_task_status(raw):
    data = midjourney_response_data(raw)
    return str(data.get("status") or data.get("task_status") or "").strip().upper()

def midjourney_error_detail(raw, fallback="Midjourney 请求失败"):
    data = midjourney_response_data(raw)
    error = data.get("error") if isinstance(data.get("error"), dict) else {}
    return str(
        error.get("message")
        or data.get("message")
        or data.get("fail_reason")
        or (raw.get("message") if isinstance(raw, dict) else "")
        or fallback
    )

def midjourney_remote_images(raw):
    data = midjourney_response_data(raw)
    values = data.get("image_urls") or data.get("imageUrls") or []
    if isinstance(values, str):
        values = [values]
    if not isinstance(values, list):
        values = []
    urls = [str(value or "").strip() for value in values if str(value or "").strip()]
    if not urls:
        result = data.get("result") if isinstance(data.get("result"), dict) else {}
        result_images = result.get("images") if isinstance(result.get("images"), list) else []
        for item in result_images:
            value = str((item or {}).get("url") if isinstance(item, dict) else item or "").strip()
            if value:
                urls.append(value)
    if not urls:
        for key in ("image_url", "imageUrl", "grid_image_url", "gridImageUrl"):
            value = str(data.get(key) or "").strip()
            if value:
                urls.append(value)
    return list(dict.fromkeys(urls))

async def midjourney_reference_urls(reference_images):
    urls = []
    for ref in (reference_images or [])[:4]:
        value = str((ref or {}).get("url") or "").strip()
        if value.startswith(("http://", "https://", "data:image/")):
            urls.append(value)
            continue
        data_url = reference_to_data_url(ref, max_size=1536)
        if data_url.startswith("data:image/"):
            urls.append(data_url)
    return urls

async def midjourney_modal_mask_url(reference):
    """Convert this canvas's white edit-mask convention to APIMart's alpha mask.
    Existing remote masks are treated as already compliant; locally generated
    `role=mask` images have white editable pixels and are inverted to transparent.
    """
    if not reference:
        return ""
    ref = reference.dict() if isinstance(reference, AIReference) else dict(reference)
    value = str(ref.get("url") or "").strip()
    if value.startswith(("http://", "https://")):
        return value
    data_url = reference_to_data_url(ref, max_size=2048)
    if not data_url.startswith("data:image/"):
        return ""
    try:
        _header, encoded = data_url.split(",", 1)
        with Image.open(BytesIO(base64.b64decode(encoded))) as image:
            luminance = ImageOps.exif_transpose(image).convert("L")
            rgba = Image.new("RGBA", luminance.size, (255, 255, 255, 255))
            rgba.putalpha(ImageOps.invert(luminance))
            out = BytesIO()
            rgba.save(out, format="PNG")
        return f"data:image/png;base64,{base64.b64encode(out.getvalue()).decode('ascii')}"
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"无法读取 Midjourney 遮罩图片：{exc}") from exc

async def apimart_midjourney_request(provider, path, body):
    timeout = httpx.Timeout(connect=20.0, read=180.0, write=120.0, pool=20.0)
    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
        response = await client.post(
            midjourney_api_url(provider, path),
            headers=api_headers(provider=provider),
            json=body,
        )
    try:
        raw = response.json()
    except ValueError:
        raw = {"message": response.text[:500]}
    if response.status_code >= 400:
        raise HTTPException(status_code=response.status_code, detail=midjourney_error_detail(raw, f"Midjourney 接口错误（{response.status_code}）"))
    task_id = midjourney_task_id(raw)
    if not task_id:
        raise HTTPException(status_code=502, detail=f"Midjourney 未返回任务 ID：{json.dumps(raw, ensure_ascii=False)[:500]}")
    return raw, task_id

async def midjourney_result(provider, task_id: str):
    safe_task_id = str(task_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.:-]{1,240}", safe_task_id):
        raise HTTPException(status_code=400, detail="Midjourney 任务 ID 不合法。")
    timeout = httpx.Timeout(connect=20.0, read=180.0, write=60.0, pool=20.0)
    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
        response = await client.get(
            midjourney_api_url(
                provider,
                f"/v1/midjourney/tasks/{urllib.parse.quote(safe_task_id, safe='')}"
                if is_ai_money_provider(provider)
                else f"/v1/midjourney/{urllib.parse.quote(safe_task_id, safe='')}",
            ),
            headers=api_headers(provider=provider),
        )
    try:
        raw = response.json()
    except ValueError:
        raw = {"message": response.text[:500]}
    if response.status_code >= 400:
        raise HTTPException(status_code=response.status_code, detail=midjourney_error_detail(raw, f"查询 Midjourney 任务失败（{response.status_code}）"))
    status = midjourney_task_status(raw)
    if status in IMAGE_TASK_FAILED_STATUSES:
        return {"status": "failed", "task_id": safe_task_id, "error": midjourney_error_detail(raw), "raw": raw}
    if status not in IMAGE_TASK_SUCCESS_STATUSES:
        return {"status": "running", "task_id": safe_task_id, "message": "Midjourney 任务仍在生成中", "raw": raw}
    remote_urls = midjourney_remote_images(raw)
    if not remote_urls:
        return {"status": "failed", "task_id": safe_task_id, "error": "Midjourney 任务成功但没有返回图片。", "raw": raw}
    local_urls, image_items = [], []
    for remote_url in remote_urls:
        local_url = await save_ai_image_to_output({"type": "url", "value": remote_url}, prefix="midjourney_")
        if local_url:
            local_urls.append(local_url)
            item = image_output_meta(local_url)
            item["mj_task_id"] = safe_task_id
            image_items.append(item)
    return {
        "status": "succeeded",
        "task_id": safe_task_id,
        "images": local_urls,
        "image_items": image_items,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "raw": raw,
    }

@app.post("/api/midjourney/submit")
async def submit_midjourney(payload: MidjourneySubmitRequest):
    provider = apimart_midjourney_provider(payload.provider_id)
    speed = str(payload.speed or "relax").strip().lower()
    if speed not in MIDJOURNEY_SPEEDS:
        raise HTTPException(status_code=400, detail="Midjourney 速度仅支持 relax、fast 或 turbo。")
    size = str(payload.size or "1:1").strip()
    if not re.fullmatch(r"\d{1,2}:\d{1,2}", size):
        raise HTTPException(status_code=400, detail="Midjourney 画幅应为宽:高，例如 16:9。")
    mode = str(payload.mode or "imagine").strip().lower()
    if mode not in {"imagine", "blend", "edit"}:
        raise HTTPException(status_code=400, detail="不支持的 Midjourney 节点模式。")
    image_urls = await midjourney_reference_urls([ref.dict() for ref in payload.reference_images if ref.url])
    prompt = str(payload.prompt or "").strip()
    if mode == "blend":
        if not 2 <= len(image_urls) <= 4:
            raise HTTPException(status_code=400, detail="Midjourney 多图融合需要连接 2 到 4 张图片。")
        body = {"image_urls": image_urls, "size": size, "speed": speed, "metadata": {"source": "infinite-canvas"}}
        path = "/v1/midjourney/generations/blend"
    elif mode == "edit":
        if not prompt:
            raise HTTPException(status_code=400, detail="Midjourney 图片编辑需要提示词。")
        if not image_urls:
            raise HTTPException(status_code=400, detail="Midjourney 图片编辑需要连接至少一张图片。")
        body = {"prompt": prompt, "image_urls": image_urls, "size": size, "speed": speed, "metadata": {"source": "infinite-canvas"}}
        path = "/v1/midjourney/generations/edits"
    else:
        if not prompt:
            raise HTTPException(status_code=400, detail="Midjourney 文生图需要提示词。")
        body = {"prompt": prompt, "size": size, "version": str(payload.version or "6.1").strip()[:24], "speed": speed, "metadata": {"source": "infinite-canvas"}}
        if image_urls:
            body["image_urls"] = image_urls
        path = "/v1/midjourney/generations"
    raw, task_id = await apimart_midjourney_request(provider, path, body)
    return {"task_id": task_id, "status": midjourney_task_status(raw) or "queued", "provider_id": provider["id"], "mode": mode, "raw": raw}

@app.post("/api/midjourney/actions")
async def submit_midjourney_action(payload: MidjourneyActionRequest):
    provider = apimart_midjourney_provider(payload.provider_id)
    action = str(payload.action or "").strip().lower()
    if action not in MIDJOURNEY_ACTION_PATHS:
        raise HTTPException(status_code=400, detail="不支持的 Midjourney 操作。")
    task_id = str(payload.task_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.:-]{1,240}", task_id):
        raise HTTPException(status_code=400, detail="Midjourney 任务 ID 不合法。")
    speed = str(payload.speed or "relax").strip().lower()
    if speed not in MIDJOURNEY_SPEEDS:
        raise HTTPException(status_code=400, detail="Midjourney 速度仅支持 relax、fast 或 turbo。")
    body = {"task_id": task_id, "speed": speed, "metadata": {"source": "infinite-canvas"}}
    custom_id = str(payload.custom_id or "").strip()
    if custom_id:
        body["custom_id"] = custom_id
    if action in {"upscale", "variation", "low_variation", "high_variation", "remix_subtle", "remix_strong"} and not custom_id:
        index = int(payload.index or 0)
        if index not in {1, 2, 3, 4}:
            raise HTTPException(status_code=400, detail="Midjourney 图片序号应为 1 到 4。")
        body["index"] = index
    elif action in {"zoom", "pan"} and int(payload.index or 0) in {1, 2, 3, 4}:
        body["index"] = int(payload.index)
    if action == "zoom" and payload.zoom_ratio is not None:
        zoom_ratio = float(payload.zoom_ratio)
        if zoom_ratio <= 1 or zoom_ratio > 4:
            raise HTTPException(status_code=400, detail="Midjourney 缩放比例应大于 1 且不超过 4。")
        body["zoom_ratio"] = zoom_ratio
    if action == "pan" and not custom_id:
        direction = str(payload.direction or "").strip().lower()
        if direction not in {"left", "right", "up", "down"}:
            raise HTTPException(status_code=400, detail="Midjourney 平移方向仅支持 left、right、up 或 down。")
        body["direction"] = direction
    if action in {"remix_subtle", "remix_strong"}:
        prompt = str(payload.prompt or "").strip()
        if prompt:
            body["prompt"] = prompt
    raw, new_task_id = await apimart_midjourney_request(provider, MIDJOURNEY_ACTION_PATHS[action], body)
    return {"task_id": new_task_id, "status": midjourney_task_status(raw) or "queued", "provider_id": provider["id"], "action": action, "raw": raw}

@app.post("/api/midjourney/modal")
async def submit_midjourney_modal(payload: MidjourneyModalRequest):
    provider = apimart_midjourney_provider(payload.provider_id)
    task_id = str(payload.task_id or "").strip()
